def _png_bytes_from_mask(mask, width, height, scale, rgb):
    """Builds an RGBA PNG from a packed bitmask, in pure Python.

    Written out by hand because Tk can display a PNG but cannot tint one,
    and pulling in Pillow just to colour a 50x72 icon would make it a hard
    dependency of the app for the sake of decoration. zlib and struct are
    already imported; the format needs nothing else.

    Set cells become `rgb` at full alpha, clear cells become fully
    transparent - so the icon sits on the panel rather than in a box of its
    own, whatever the panel's colour is.
    """
    import binascii
    r, g, b = rgb
    on = bytes((r, g, b, 255)) * scale
    off = bytes(4) * scale
    stride = (width + 7) // 8
    raw = bytearray()
    for y in range(height):
        line = bytearray()
        for x in range(width):
            line += on if (mask[y * stride + (x >> 3)] >> (7 - (x & 7))) & 1 else off
        # Filter byte 0 (none) per scanline, and each source row repeated
        # `scale` times - nearest-neighbour, which is what keeps pixel art
        # crisp instead of smearing it.
        for _ in range(scale):
            raw += b"\x00" + line

    def chunk(tag, payload):
        return (struct.pack(">I", len(payload)) + tag + payload
                + struct.pack(">I", binascii.crc32(tag + payload) & 0xFFFFFFFF))

    ihdr = struct.pack(">IIBBBBB", width * scale, height * scale, 8, 6, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n"
            + chunk(b"IHDR", ihdr)
            + chunk(b"IDAT", zlib.compress(bytes(raw), 9))
            + chunk(b"IEND", b""))


def _glyph_photoimage(w, h, rects, color):
    """A tk.PhotoImage of `rects` filled in `color`, transparent elsewhere.

    Shared by the little list glyphs. They are all a handful of rectangles,
    so describing them as rectangles is both smaller than storing bitmaps
    and the only way they can follow the UI scale and the theme instead of
    being frozen at one size and one colour.
    """
    stride = (w + 7) // 8
    mask = bytearray(stride * h)
    for x0, y0, x1, y1 in rects:
        for y in range(max(0, y0), min(h, y1)):
            row = y * stride
            for x in range(max(0, x0), min(w, x1)):
                mask[row + (x >> 3)] |= 0x80 >> (x & 7)
    rgb = tuple(int(color.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4))
    return tk.PhotoImage(
        data=base64.b64encode(_png_bytes_from_mask(bytes(mask), w, h, 1, rgb)))


def make_folder_icon(color, height=None):
    """A small folder glyph, or None.

    Replaces the "[Folder] " prefix in the file lists. That prefix is still
    what the code matches on internally; only the display changes, so every
    startswith("[Folder]") test keeps working untouched.
    """
    try:
        h = int(height or sc(13))
        w = max(6, int(round(h * 1.30)))
        tab_h = max(2, h // 4)
        tab_w = max(4, int(round(w * 0.45)))
        return _glyph_photoimage(w, h, [(0, 0, tab_w, tab_h), (0, tab_h, w, h)], color)
    except Exception as e:
        print(f"Could not build the folder icon: {e}")
        return None


def make_drive_icon(color, height=None):
    """A small drive glyph, or None.

    Used for the roots that are volumes rather than folders - a Windows
    drive letter, /Volumes, /media. They were drawn with the folder icon,
    which said the wrong thing about the one row in the tree that is not a
    folder at all.

    A wide body with a notch cut out of the lower left, reading as a disk
    caddy at thirteen pixels. Anything with more detail turns to mush at
    this size; what matters is only that it is NOT the folder shape.
    """
    try:
        h = int(height or sc(13))
        w = max(6, int(round(h * 1.30)))
        slot_y = max(1, h // 5)
        slot_h = max(1, h // 5)
        inset = max(1, w // 6)
        led = max(2, w // 5)
        return _glyph_photoimage(w, h, [
            # body
            (0, slot_y, w, h - slot_y),
            # the slot across the top half, drawn as two bars with a gap so
            # the shape has a horizontal line through it the folder lacks
            (inset, slot_y + slot_h, w - inset, slot_y + slot_h + max(1, h // 8)),
            # activity mark, bottom right
            (w - inset - led, h - slot_y - max(2, h // 6), w - inset,
             h - slot_y - max(1, h // 10)),
        ], color)
    except Exception as e:
        print(f"Could not build the drive icon: {e}")
        return None


def _windows_drive_roots():
    """Existing drive roots on Windows, e.g. ["C:\\", "D:\\"].

    Read from the GetLogicalDrives bitmask rather than by calling
    os.path.exists() on all twenty-six letters. Probing a removable letter
    with no media in it makes Windows spin the device up and can block for
    seconds, or raise the "There is no disk in the drive" dialog - for a
    list that is only being drawn.

    Falls back to probing if the call is unavailable, which is no worse
    than what it replaces.
    """
    try:
        import ctypes
        mask = ctypes.windll.kernel32.GetLogicalDrives()
        return [f"{chr(65 + i)}:\\" for i in range(26) if mask >> i & 1]
    except Exception as e:
        _swallowed(e, "_windows_drive_roots")
        return [f"{c}:\\" for c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                if os.path.exists(f"{c}:\\")]


def make_wave_icon(color, height=None):
    """A small waveform glyph for audio rows, or None.

    Bars rather than a document-with-corner: at thirteen pixels a page icon
    is an indistinct rectangle, while a run of bars still reads as sound at
    that size - and it cannot be confused with the folder, which is the one
    thing this has to do.

    Symmetrical about the middle, so it stays centred against the row's
    text baseline whatever the scale rounds the bar heights to.
    """
    try:
        h = int(height or sc(13))
        w = max(6, int(round(h * 1.30)))
        # Four bars, not six. At thirteen pixels wide the six-bar version
        # came out as 1px strokes with 1px gaps, which reads as a comb
        # rather than as a waveform. Four leaves room for a bar that is
        # actually a bar at every scale.
        bar = max(1, w // 7)
        gap = max(1, bar)
        # Fractions of full height, shaped like a short burst.
        profile = (0.45, 1.0, 0.60, 0.85)
        span = len(profile) * bar + (len(profile) - 1) * gap
        x = max(0, (w - span) // 2)
        rects = []
        for frac in profile:
            bh = max(1, int(round(h * frac)))
            y0 = (h - bh) // 2
            rects.append((x, y0, x + bar, y0 + bh))
            x += bar + gap
        return _glyph_photoimage(w, h, rects, color)
    except Exception as e:
        print(f"Could not build the waveform icon: {e}")
        return None


def make_note_icon(color, height=None):
    """A small musical-note glyph, or None.

    Used for .mp3 where .wav gets the waveform bars. A different SHAPE, not
    just a different colour: these rows sit next to each other in the same
    list, and colour alone is the one distinction that disappears for a
    colour-blind reader and in a screenshot.

    The choice is not arbitrary either. Bars stand for the samples that are
    actually in the file, which is what a .wav holds; a note stands for
    something that has to be decoded back into samples first.
    """
    try:
        h = int(height or sc(13))
        w = max(8, int(round(h * 1.30)))
        head_h = max(3, int(round(h * 0.34)))
        head_w = max(3, int(round(w * 0.34)))
        stem_w = max(1, int(round(w * 0.11)))
        beam_h = max(2, int(round(h * 0.18)))
        lift = max(1, h // 6)          # the right head sits a step higher
        # A BEAMED PAIR rather than a single note. A lone quarter note comes
        # out of a rectangle grid as an L at this size - the head is a
        # square and nothing says "music". Two heads joined by a beam has a
        # silhouette that survives thirteen pixels.
        rects = [
            (0, h - head_h, head_w, h),                                 # left head
            (head_w - stem_w, beam_h, head_w, h - head_h + 1),          # left stem
            (w - head_w, h - head_h - lift, w, h - lift),               # right head
            (w - stem_w, 0, w, h - head_h - lift + 1),                  # right stem
            (head_w - stem_w, 0, w, beam_h),                            # beam
        ]
        return _glyph_photoimage(w, h, rects, color)
    except Exception as e:
        print(f"Could not build the note icon: {e}")
        return None


def make_device_icon(name, color, scale=2):
    """A tk.PhotoImage of one of DEVICE_ICONS in `color`, or None.

    Returns None rather than raising: the icons are decoration, and a Tk
    build that cannot read PNG (8.5 and older) should cost a dialog its
    picture, not its ability to open.
    """
    try:
        width, height, mask = DEVICE_ICONS[name]
        rgb = tuple(int(color.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4))
        png = _png_bytes_from_mask(base64.b64decode(mask),
                                   width, height, scale, rgb)
        return tk.PhotoImage(data=base64.b64encode(png))
    except Exception as e:
        print(f"Could not build the {name} icon: {e}")
        return None


def resource_path(relative_path):
    """Resolves a path next to the script - and also works after bundling
    with PyInstaller (onefile or onedir), which extracts bundled data files
    into a temp folder at runtime and exposes it via sys._MEIPASS."""
    base_path = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
    return os.path.join(base_path, relative_path)


try:
    from pydub import AudioSegment
    from pydub.silence import detect_leading_silence
    from pydub.effects import normalize as pydub_normalize

    # Priority: a copy bundled alongside the app (e.g. via PyInstaller
    # --add-binary, so the app is self-contained and needs no system-wide
    # ffmpeg install) > whatever is on PATH > the Linux convenience fallback.
    _bundle_ffmpeg_name = "ffmpeg.exe" if sys.platform.startswith("win") else "ffmpeg"
    _bundle_ffprobe_name = "ffprobe.exe" if sys.platform.startswith("win") else "ffprobe"
    _bundled_ffmpeg = resource_path(_bundle_ffmpeg_name)
    _bundled_ffprobe = resource_path(_bundle_ffprobe_name)

    def _tool_fallbacks(name):
        """Where to look for `name` when PATH does not have it.

        An app launched from Finder or a desktop launcher does NOT inherit
        the login shell's PATH - .zshrc and .bash_profile are never read -
        so Homebrew's /usr/local/bin (Intel) and /opt/homebrew/bin (Apple
        Silicon) are simply absent. The symptom is that the script works
        from a terminal and the double-clicked .app reports "ffmpeg not
        found", which reads like a broken install rather than a missing
        search path. Reported from macOS 12 on an Intel Mac.

        /usr/bin was the only fallback before, and on macOS nothing is
        installed there.
        """
        roots = ["/usr/local/bin", "/opt/homebrew/bin", "/usr/bin",
                 "/opt/local/bin",        # MacPorts
                 "/snap/bin", "/var/lib/flatpak/exports/bin"]
        return [os.path.join(r, name) for r in roots]

    if os.path.exists(_bundled_ffmpeg):
        _ffmpeg_path = _bundled_ffmpeg
    else:
        _ffmpeg_path = shutil.which("ffmpeg") or next(
            (p for p in _tool_fallbacks("ffmpeg") if os.path.exists(p)),
            "/usr/bin/ffmpeg")
    if os.path.exists(_bundled_ffprobe):
        _ffprobe_path = _bundled_ffprobe
    else:
        _ffprobe_path = shutil.which("ffprobe") or next(
            (p for p in _tool_fallbacks("ffprobe") if os.path.exists(p)),
            "/usr/bin/ffprobe")

    if os.path.exists(_ffmpeg_path):
        AudioSegment.converter = _ffmpeg_path
        AudioSegment.ffmpeg = _ffmpeg_path
    if os.path.exists(_ffprobe_path):
        AudioSegment.ffprobe = _ffprobe_path
    PYDUB_AVAILABLE = True
    # Reflects whether ffmpeg is *actually* reachable (bundled, on PATH, or
    # at the fallback path), not just whether some candidate was guessed.
    FFMPEG_AVAILABLE = os.path.exists(_ffmpeg_path)
except ImportError:
    PYDUB_AVAILABLE = False
    FFMPEG_AVAILABLE = False

_log_timing("pydub import block done")

_pydub_warning_shown = False  # only nag once per session if pydub is missing


def warn_pydub_missing_once():
    """Shows a one-time notice if the user changes a setting (rate, pitch,
    mono) that requires pydub/ffmpeg to actually take effect at export time."""
    global _pydub_warning_shown
    if PYDUB_AVAILABLE or _pydub_warning_shown:
        return
    _pydub_warning_shown = True
    dark_showwarning(
        "pydub/ffmpeg missing",
        "Sample rate, pitch and forced mono require pydub + ffmpeg.\n"
        "These settings are saved, but currently have no effect on "
        "Play/Preview/Export while pydub/ffmpeg is missing."
    )

APP_NAME = "PyP6"
APP_SUBTITLE = "Roland AIRA P-6 Sample Manager"
APP_VERSION = "4.2.3"
APP_AUTHOR = "Brian Siemund"
APP_YEAR = "2026"
APP_URL = "https://github.com/j0kerpack/Roland-P6-sample-manager"
# Shown in About and carried by "Copy Info", so a bug report pasted from
# there has it too.
APP_SUPPORT_URL = "https://ko-fi.com/j0kerpack"
# Single source of truth for the version: the window title and the About
# box both read these, so a release bump can't leave one of them stale.

PYP6_DEBUG = bool(os.environ.get("PYP6_DEBUG"))


def _swallowed(exc, where):
    """Records an exception that is deliberately ignored.

    Silent `except ...: pass` is right in most places it appears here - Tk
    raises while a window is being torn down, a drive can vanish mid-scan -
    but there were 101 of them and no way to find out which one had fired,
    so a real bug could disappear without leaving a trace.

    Behaviour is unchanged by default: nothing is printed, nothing is
    raised, the exception is still swallowed. Set PYP6_DEBUG=1 in the
    environment to see them.
    """
    if PYP6_DEBUG:
        print(f"[swallowed] {where}: {type(exc).__name__}: {exc}")


APP_DIR = os.path.expanduser("~/.pyp6")
TEMP_DIR = os.path.join(APP_DIR, "temp")
CONFIG_FILE = os.path.join(APP_DIR, "config.json")


def _module_version(module, dist_name=None):
    """Best-effort version string for an optional dependency.

    Tries __version__ first, then the installed package metadata (pydub,
    for one, ships no __version__ attribute). Never raises - a missing
    version in an About box is cosmetic and must not break the dialog."""
    try:
        v = getattr(module, "__version__", None)
        if v:
            return str(v)
    except Exception as _e:
        _swallowed(_e, "_module_version")
    if dist_name:
        try:
            from importlib.metadata import version as _dist_version
            return str(_dist_version(dist_name))
        except Exception as _e:
            _swallowed(_e, "_module_version")
    return "installed (version unknown)"


_DND_APP = None  # set by P6ManagerApp so the status below can see the live state


def _dnd_is_working():
    return bool(DND_AVAILABLE and getattr(_DND_APP, "_dnd_registered", None))


def dnd_status_text():
    """Reports what drag & drop is ACTUALLY doing, not just whether the
    module imported. Those are different failures with different fixes:
    a missing package is a pip install, a failed registration is a tkdnd
    or compositor problem - and the old text said "active" for both."""
    if not DND_AVAILABLE:
        reason = f" - {DND_IMPORT_ERROR}" if DND_IMPORT_ERROR else ""
        if TK_VERSION and TK_VERSION >= (9, 0):
            # The usual cause on Tk 9, and worth naming: the import itself
            # succeeds (tkinterdnd2 is Python), and only the `package
            # require tkdnd` inside TkinterDnD.Tk() fails, because the
            # shipped tkdnd binary is built against Tcl 8 and Tcl 9 broke
            # ABI compatibility. No amount of reinstalling fixes it.
            return (f"unavailable under Tcl/Tk {TK_PATCHLEVEL} - the bundled "
                    f"tkdnd is built for Tcl 8{reason}")
        return f"tkinterdnd2 not available (pip install tkinterdnd2){reason}"
    registered = getattr(_DND_APP, "_dnd_registered", None)
    if registered is None:
        return "tkinterdnd2 loaded, drop targets not registered yet"
    if not registered:
        return "tkinterdnd2 loaded, but NO drop target could be registered"
    return "active (" + ", ".join(registered) + ")"


def collect_about_info():
    """(label, value) pairs describing this install, for the About box.

    Also what the About box's Copy button puts on the clipboard, so a bug
    report can be pasted with the exact versions and paths involved -
    which is the whole reason the optional-dependency state is in here."""
    rows = []
    rows.append(("Version", APP_VERSION))
    rows.append(("Author", APP_AUTHOR))
    rows.append(("Copyright", f"\u00a9 {APP_YEAR} {APP_AUTHOR}"))
    rows.append(("Project", APP_URL))
    rows.append(("Support", APP_SUPPORT_URL))
    try:
        rows.append(("Python", f"{sys.version.split()[0]} on {sys.platform}"))
    except Exception as _e:
        _swallowed(_e, "collect_about_info")
    try:
        # The patchlevel string once a root exists, because tk.TkVersion is
        # a float: it reports 9.0 for every 9.0.x, and the x is exactly what
        # a bug report needs.
        rows.append(("Tcl/Tk", TK_PATCHLEVEL or str(tk.TkVersion)))
    except Exception as _e:
        _swallowed(_e, "collect_about_info")
    rows.append(("NumPy", _module_version(np, "numpy")))
    rows.append(("soundfile", _module_version(sf, "soundfile")))
    rows.append(("sounddevice", _module_version(sd, "sounddevice")))
    if PYDUB_AVAILABLE:
        try:
            import pydub as _pydub
            rows.append(("pydub", _module_version(_pydub, "pydub")))
        except Exception:
            rows.append(("pydub", "installed"))
    else:
        rows.append(("pydub", "not installed - Chop, MP3, rate/pitch/mono disabled"))
    if FFMPEG_AVAILABLE:
        converter = None
        try:
            converter = AudioSegment.converter
        except Exception as _e:
            _swallowed(_e, "collect_about_info")
        rows.append(("ffmpeg", str(converter) if converter else "found"))
    else:
        rows.append(("ffmpeg", "not found"))
    rows.append(("Drag & drop", dnd_status_text()))
    rows.append(("Settings file", CONFIG_FILE))
    rows.append(("Temp folder", TEMP_DIR))
    return rows


def about_info_as_text():
    lines = [f"{APP_NAME} - {APP_SUBTITLE}"]
    lines += [f"{label}: {value}" for label, value in collect_about_info()]
    return "\n".join(lines)


def ensure_app_dirs():
    """Creates the app's folders on demand. Everything the app writes lives
    under ~/.pyp6: config.json at the top, and all generated audio (trims,
    mono downmixes, normalized copies, chops, preview conversions) under
    temp/. Keeping config OUTSIDE temp/ matters - it means clearing temp
    can never wipe the user's settings."""
    try:
        os.makedirs(TEMP_DIR, exist_ok=True)
    except Exception as e:
        print(f"Could not create app folders: {e}")
    return TEMP_DIR


def temp_path(filename):
    """Absolute path for a generated file inside the temp folder."""
    ensure_app_dirs()
    return os.path.join(TEMP_DIR, filename)


