NORMALIZE_MODE_KEYS = {"Off": "off", "Per sample": "per_sample", "Whole file": "whole"}
PITCH_MIN_CENTS = -1200
PITCH_MAX_CENTS = 1200
PITCH_STEP_CENTS = 100

