# ---------------------------------------------------------------------------
# Button fill colors
# ---------------------------------------------------------------------------
# The ACCENT_* colors above carry two jobs that pull in opposite directions:
# they're warning/status TEXT on a dark panel (wants a LIGHT color), and they
# are solid button fills under white text (wants a DARK one). The palettes
# were tuned for the text role, so on all four dark themes white-on-accent
# came out unreadable - Dracula's green was the extreme at 1.37:1, barely
# distinguishable from the fill behind it.
#
# Rather than compromise one color for both roles, the fill role gets its own
# derived value: same hue, saturation eased back a quarter so a large block
# of color doesn't shout, and lightness pulled down only as far as white text
# needs. The accents themselves are untouched and keep doing the text job.

def _relative_luminance(hex_color):
    h = hex_color.lstrip("#")
    channels = [int(h[i:i + 2], 16) / 255.0 for i in (0, 2, 4)]
    channels = [c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
                for c in channels]
    return 0.2126 * channels[0] + 0.7152 * channels[1] + 0.0722 * channels[2]


def contrast_ratio(hex_a, hex_b):
    """WCAG contrast ratio between two colors (1.0 = identical, 21 = max)."""
    la, lb = _relative_luminance(hex_a), _relative_luminance(hex_b)
    lighter, darker = max(la, lb), min(la, lb)
    return (lighter + 0.05) / (darker + 0.05)


BUTTON_SATURATION = 0.75  # button fills sit at 75% of the accent's saturation


def blend_colors(hex_a, hex_b, t):
    """Mixes two colors, t=0 gives `hex_a` and t=1 gives `hex_b`."""
    a = hex_a.lstrip("#"); b = hex_b.lstrip("#")
    out = []
    for i in (0, 2, 4):
        ca, cb = int(a[i:i + 2], 16), int(b[i:i + 2], 16)
        out.append(int(round(ca + (cb - ca) * t)))
    return "#{:02x}{:02x}{:02x}".format(*out)


def readable_on(hex_color, background, target_ratio=4.5):
    """Nudges a color's lightness until it is readable on `background`.

    Keeps the hue so it still belongs to the palette; only moves as far as it
    has to. Used for small text drawn onto canvases, where a color picked for
    a filled shape is usually far too dark or too light to read.
    """
    if contrast_ratio(hex_color, background) >= target_ratio:
        return hex_color
    h = hex_color.lstrip("#")
    r, g, b = (int(h[i:i + 2], 16) / 255.0 for i in (0, 2, 4))
    hue, lig, sat = colorsys.rgb_to_hls(r, g, b)
    # Move away from the background: lighten on dark, darken on light.
    direction = 1.0 if _relative_luminance(background) < 0.5 else -1.0
    best = hex_color
    for step in range(1, 51):
        cand_l = min(1.0, max(0.0, lig + direction * step * 0.02))
        rr, gg, bb = colorsys.hls_to_rgb(hue, cand_l, sat)
        cand = f"#{int(rr*255):02x}{int(gg*255):02x}{int(bb*255):02x}"
        best = cand
        if contrast_ratio(cand, background) >= target_ratio:
            return cand
    return best


def fill_for_white_text(hex_color, target_ratio=4.5, saturation_scale=BUTTON_SATURATION):
    """Turns an accent into a button fill that carries white text.

    Two steps, both in HLS so the hue never moves: pull the saturation back
    to `saturation_scale` of the original, then lower the lightness only as
    far as needed for white text to reach `target_ratio`. A large colored
    button is a much bigger block of color than the same accent used as a
    thin line of status text, and at full saturation those blocks shout -
    hence the first step, which applies on every theme.

    The order matters: desaturating changes luminance, so the contrast
    search has to run afterwards or the guarantee wouldn't hold."""
    h = hex_color.lstrip("#")
    r, g, b = (int(h[i:i + 2], 16) / 255.0 for i in (0, 2, 4))
    hue, lightness, saturation = colorsys.rgb_to_hls(r, g, b)
    saturation *= saturation_scale

    def at(l):
        rr, gg, bb = colorsys.hls_to_rgb(hue, l, saturation)
        return "#{:02X}{:02X}{:02X}".format(round(rr * 255), round(gg * 255), round(bb * 255))

    if contrast_ratio(at(lightness), "#FFFFFF") >= target_ratio:
        return at(lightness)  # already dark enough; keep the original brightness

    lo, hi = 0.0, lightness
    for _ in range(24):  # binary search; 24 steps is far finer than 8-bit color
        mid = (lo + hi) / 2.0
        if contrast_ratio(at(mid), "#FFFFFF") >= target_ratio:
            lo = mid  # still readable - try to keep more of the original brightness
        else:
            hi = mid
    return at(lo)


BTN_BLUE = fill_for_white_text(ACCENT_BLUE)
BTN_GREEN = fill_for_white_text(ACCENT_GREEN)
BTN_RED = fill_for_white_text(ACCENT_RED)
BTN_ORANGE = fill_for_white_text(ACCENT_ORANGE)
BTN_PURPLE = fill_for_white_text(ACCENT_PURPLE)

# A touch darker than ACCENT_BLUE itself, for a selected row's background
# in a list or tree - the same white text sits on it (see the Treeview
# style map and style_listbox), and pulling the fill down slightly gave
# that white a bit more room over the raw accent colour.
SELECT_HIGHLIGHT_BLUE = blend_colors(ACCENT_BLUE, "#000000", 0.15)


# Text drawn ON a coloured fill: a menu entry under the cursor, a selected
# row, selected text in an entry.
#
# These used to be hard-coded, and each hard-coded choice was right for
# roughly half the palettes. "#FFFFFF" was correct on the light themes,
# where every accent is dark, and unreadable on the eight dark ones, where
# the same accents are bright: white on Dracula's selection blue scored
# 1.94:1, white on "dark" 3.69:1. The near-black used by the dropdown
# menus had the mirror-image problem - fine on the dark themes, 3.0:1 on
# "bright", "latte" and "snow".
#
# Derived per palette instead, so adding a theme cannot reintroduce
# either half of it.

def text_on(background, dark_text="#10131A"):
    """Black or white on `background` - whichever reads better."""
    return ("#FFFFFF" if contrast_ratio(background, "#FFFFFF")
            >= contrast_ratio(background, dark_text) else dark_text)


ON_ACCENT_BLUE = text_on(ACCENT_BLUE)
ON_ACCENT_ORANGE = text_on(ACCENT_ORANGE)
ON_SELECT_BLUE = text_on(SELECT_HIGHLIGHT_BLUE)

# A milder, darker orange for redrawing the truncated stretch of a
# waveform trace (see draw_waveform_on_canvas's px_range and every
# _redraw..._overlay method that uses it). The raw ACCENT_ORANGE is tuned
# to stand out as warning TEXT and small markers - filling an entire
# waveform shape with it at full strength read as harsh rather than
# informative, where a name or a single line reads fine.
TRUNCATE_WAVE_COLOR = blend_colors(ACCENT_ORANGE, "#000000", 0.25)


# ---------------------------------------------------------------------------
# The bottom button row
# ---------------------------------------------------------------------------
# Four solid blocks of color across the bottom of the window is a lot of
# weight for four actions that are used once or twice a session, next to a
# pad grid whose Load/Play/Chop/Synth get clicked constantly. On the four
# themes below the row becomes a neutral key with the accent as a lit strip
# along its bottom edge instead - the hierarchy then matches the usage, and
# it reads like the edge of a piece of hardware, which is the point of those
# themes in the first place.
#
# A named set rather than a luminance test: this is a taste call about which
# palettes suit the look, not a legibility one. "dark", "tokyo", "dracula"
# and "modern" are dark too and deliberately keep the solid fills; adding one
# of them is a one-word change here.
LED_BOTTOM_ROW_THEMES = {"matrix", "ice", "synthwave", "devil"}
BOTTOM_ROW_LED = THEME in LED_BOTTOM_ROW_THEMES

# BG_INPUT rather than a value derived for this row: the dropdowns, Preset
# and the gear button in the same window are already BG_INPUT on BG_DARK, so
# the key reads as the same kind of surface they do. It also means the strip
# is the ONLY thing distinguishing these buttons, which is the whole idea.
BOTTOM_ROW_KEY_FILL = BG_INPUT


def bottom_button_style(accent, solid_fill):
    """Look for one button in the bottom row, as RoundedButton kwargs.

    On the LED themes: neutral key, hairline in the panel border color, the
    accent as a strip. Everywhere else the row is untouched - a dark strip
    under a light key is the wrong way round on "latte" and "bright", and
    the remaining dark themes were a deliberate choice to leave alone.

    The strip is lifted to 3:1 against the key because it is a graphical
    marker, not text. On all four themes every accent already clears that
    unchanged, so this is a guard for future palettes rather than a
    correction to the current ones.
    """
    if not BOTTOM_ROW_LED:
        return {"bg": solid_fill, "fg": "#FFFFFF"}
    return {"bg": BOTTOM_ROW_KEY_FILL,
            "fg": FG_TEXT,
            "outline_color": BORDER_LIGHT,
            "outline_width": 1,
            "led_color": readable_on(accent, BOTTOM_ROW_KEY_FILL, 3.0)}

# The mono stripe on a compact pad is the one place an accent is used as a
# graphical marker rather than as a button fill carrying white text, so it is
# the one place that needs its own contrast guarantee. On "dark",
# ACCENT_PURPLE scored 2.73 against the panel - under the 3:1 that a non-text
# UI element needs, and a 5 px stripe nobody can see is the same as no stripe
# at all. Lifted against BG_INPUT rather than BG_PANEL because drag mode puts
# the lighter of the two behind it.
MONO_STRIPE = readable_on(ACCENT_PURPLE, BG_INPUT, 3.0)

# Labels drawn on a waveform canvas - the wavetable zone map, both in a pad's
# mini waveform and in the main view. Derived from FG_TEXT rather than from
# WAVE_COLOR, which is what it used to be. A label in the waveform's own hue
# has plenty of luminance contrast on paper (6.4:1 on "ice") and still reads
# as washed out, because it shares the background's hue and the eye gets no
# colour separation to help it. The neutral text colour reads as writing.
# 7.0 rather than the usual 4.5: this is small text on a busy dark canvas.
WAVE_LABEL = readable_on(FG_TEXT, WAVE_BG, 7.0)

# The sample name on a pad. Given a cast of the theme's own accent rather
# than the neutral FG_MUTED the other labels use: it sits directly above the
# mini waveform, whose wavetable summary is deliberately neutral, and two
# blocks of identically coloured small text ran together. The tint is what
# separates them - it says "this is the file" as against "this is what is
# in it". Lifted to 4.5 afterwards, since blending toward an accent can
# darken it on the light themes.
PAD_NAME_FG = readable_on(blend_colors(FG_MUTED, ACCENT_BLUE, 0.45), BG_PANEL, 4.5)

# The "PRM" marker on a pad and in the storage header. Deliberately built
# from FG_MUTED rather than from an accent: it is a quiet fact about the
# sample, not a warning and not a control, and a full accent next to the
# file name would read as the louder of the two. The green cast is what
# separates it from the neutral labels around it - it says "something extra
# came with this file" - but at half strength, so it sits behind the name
# rather than next to it. Lifted to 4.5 afterwards, since blending toward
# an accent can darken it on the light themes.
PRM_TAG_FG = readable_on(blend_colors(FG_MUTED, ACCENT_GREEN, 0.5), BG_PANEL, 4.5)

# The same marker once the pad's settings have retired the sidecar. Orange
# because that is already this app's colour for "this will not reach the
# device the way you expect" - the warning badge next to the storage
# figures uses it for the same kind of statement. Full accent rather than
# the muted blend PRM_TAG_FG uses: a marker that says something is about to
# be dropped should not be quieter than the one that says it will be kept.
PRM_TAG_DROPPED_FG = readable_on(ACCENT_ORANGE, BG_PANEL, 4.5)

# The transfer icon in the Copy Banks dialog. Lifted to 3.0 rather than 4.5:
# it is a picture, not text, and WCAG asks 3:1 of graphics. Tinted toward
# the accent from FG_MUTED so it reads as an illustration beside the
# checkboxes rather than as a control competing with them - it is there to
# say what the dialog does, and it should not be the loudest thing in it.
DEVICE_ICON_FG = readable_on(blend_colors(FG_MUTED, ACCENT_BLUE, 0.6), BG_PANEL, 3.0)

# How much of a warning fits on the panel's header line before it is
# elided. Deliberately a character budget rather than a pixel one: the line
# is packed next to labels whose width depends on the sample name and the
# storage figures, so there is no fixed pixel width to measure against.
WARN_LINE_CHARS = 72


def _n_of(count, singular, plural=None):
    """"1 pad" / "4 pads". Status messages used to dodge this with "pad(s)",
    which reads like a form letter; spelling it out per case costs two
    characters and reads like a sentence."""
    return f"{count} {singular if count == 1 else (plural or singular + 's')}"


def _elide_middle(text, limit):
    """Shortens text to `limit` characters, cutting out of the middle.

    The middle, not the tail: a pad warning starts with the pad it is about
    ("C5: ...") and ends with the number that matters ("only 5.9s are
    possible"), and both are worth more than the wording in between.
    """
    if len(text) <= limit:
        return text
    keep = limit - 3
    head = (keep + 1) // 2
    return text[:head] + "\u2026" + text[len(text) - (keep - head):]


# Height of the playback waveform in the storage panel. It has that row to
# itself now that the warnings and the sample name moved up into the panel's
# header line, so it is both taller and full panel width - the wavetable zone
# map needs the width for its family names.
MAIN_WAVE_H = 80

MAIN_MIN_W = sc(_MAIN_DESIGN_W)
# Breathing room under the bottom button row. The window height itself is
# measured per view rather than fixed, so this is the only vertical padding
# that is a matter of taste instead of arithmetic.
WINDOW_BOTTOM_MARGIN = 6
# Where a top-aligned window puts its upper edge when there is no parent to
# line up with. Enough that the title bar is not jammed against the screen
# edge, and enough that a window manager reporting the CLIENT top rather
# than the frame top still leaves the decoration visible.
WINDOW_TOP_MARGIN = 40   # real screen pixels, not scaled
# Rough allowance for title bars, docks and panels when clamping the window
# to the screen. Deliberately generous: guessing too little only costs a few
# pixels of content, guessing too much can put the bottom buttons off-screen.
SCREEN_HEIGHT_ALLOWANCE = 90
# Windows needs more headroom than Linux for the same content: its title
# bar and window borders are taller, and the default UI font renders a few
# pixels larger. 860 was arrived at by testing on an actual Windows box -
# at 835 the bottom row sat too tight.
# Only the size the window is born at, before _fit_window_height() measures
# the real requirement and replaces both the geometry and the minimum. Kept
# close to the expected value purely so the window does not visibly jump on
# startup.
MAIN_MIN_H = sc(_MAIN_DESIGN_H)
# Only the size this window is born at, before the end of ChopDialog.__init__
# measures the real requirement and replaces both the geometry and the
# minimum (same idea as the main window's _fit_window_height) - kept close
# to the expected value purely so the window does not visibly jump on
# screen once that measurement lands.
CHOP_MIN_W, CHOP_MIN_H = sc(1000), sc(700)
PREVIEW_MIN_W, PREVIEW_MIN_H = sc(560), sc(480 + 32)
AUDIO_PREVIEW_MIN_W, AUDIO_PREVIEW_MIN_H = sc(660), sc(580 + 2 * 32)


def style_toplevel(win):
    win.configure(bg=BG_DARK)
    # Hidden until center_toplevel_on_parent() has placed it. A Toplevel is
    # mapped wherever the window manager first puts it - usually a corner -
    # and every dialog here then measures its own contents (which pumps
    # update_idletasks) before moving into position. That is what makes them
    # appear and jump. Withdrawn, the whole sequence happens off-screen and
    # the window shows up already in the right place.
    #
    # Every Toplevel in this file calls this function and then
    # center_toplevel_on_parent(), which puts it back on screen.
    try:
        win.withdraw()
    except tk.TclError as _e:
        _swallowed(_e, "style_toplevel")


def style_label(lbl, bg=BG_DARK, fg=FG_TEXT, **kw):
    lbl.config(bg=bg, fg=fg, **kw)


def style_listbox(lb):
    lb.config(bg=BG_INPUT, fg=FG_TEXT, selectbackground=SELECT_HIGHLIGHT_BLUE,
              selectforeground=ON_SELECT_BLUE, relief="flat", bd=0,
              highlightthickness=1, highlightbackground=BORDER_COLOR,
              highlightcolor=ACCENT_BLUE, font=ui_font(10))


_TREEVIEW_STYLE_READY = False


def ensure_dark_treeview_style():
    """Configures a dark ttk.Treeview style once per process. Using a real
    Treeview (native columns/headings) instead of faking columns with
    space-padded monospace text avoids the alignment drift that approach
    was prone to (font-metric/widget-padding differences between the
    header label and the listbox)."""
    global _TREEVIEW_STYLE_READY
    if _TREEVIEW_STYLE_READY:
        return
    style = ttk.Style()
    try:
        style.theme_use("clam")  # most reliably themeable base on all platforms
    except tk.TclError as _e:
        _swallowed(_e, "ensure_dark_treeview_style")
    style.configure("Dark.Treeview",
                     background=BG_INPUT, fieldbackground=BG_INPUT, foreground=FG_TEXT,
                     borderwidth=0, relief="flat", rowheight=sc(22), font=ui_font(10),
                     # rowheight in pixels while the font is in points:
                     # leave it fixed and the scaled text is clipped by
                     # its own row.
                     # clam draws a light 3D edge around the field; the border
                     # is drawn by the wrapping frame instead (add_focus_border).
                     bordercolor=BG_INPUT, lightcolor=BG_INPUT, darkcolor=BG_INPUT)
    style.map("Dark.Treeview", bordercolor=[("focus", BG_INPUT)])

    def _clean(option):
        """The style map for `option` with the default theme's leftovers
        stripped out.

        Tk 8.6.9 changed how ttk merges style maps: a map set here inherits
        the base theme's entries for ("!disabled", "!selected"), and those
        then win over per-item TAG colours. The visible result is that
        tag_configure(..., foreground=...) does nothing and every row is
        painted in the base theme's grey instead. Dropping exactly those
        entries is the long-standing fix, and it is a no-op on the older
        Tk versions that never added them.

        Also drops every entry that positively matches "selected" (with
        or without "focus" alongside it) - not just the "!focus" one.
        Appending our own ("selected", ACCENT_BLUE) after a partial clean
        assumed ttk always prefers the last matching entry for a given
        state; in practice the Available list still showed clam's dimmer
        base colour, which only a set of competing "selected" entries
        explains. With every one of them gone, ours is the only entry
        that can match at all, so it applies regardless of which
        first-match/last-match rule ttk turns out to actually follow.
        """
        return [e for e in style.map("Treeview", query_opt=option)
                if e[:2] != ("!disabled", "!selected")
                and "selected" not in e[:-1]]

    style.map("Dark.Treeview",
              background=_clean("background") + [("selected", SELECT_HIGHLIGHT_BLUE)],
              # White, not the near-black navy this used to be: every
              # button elsewhere in the app that uses this same blue pairs
              # it with white text (bg=BTN_BLUE, fg="#FFFFFF") - dark text
              # on it was the odd one out, not a deliberate contrast
              # choice, and it only became obvious once the background fix
              # above stopped a competing style-map entry from dimming
              # this blue down to something dark text still read on.
              foreground=_clean("foreground") + [("selected", ON_SELECT_BLUE)])
    style.configure("Dark.Treeview.Heading",
                     background=BG_PANEL, foreground=FG_MUTED, relief="flat",
                     font=ui_font(9, "bold"))
    style.map("Dark.Treeview.Heading", background=[("active", BG_PANEL)])
    style.layout("Dark.Treeview", style.layout("Treeview"))

    style.configure("Dark.Vertical.TScrollbar",
                     background=BG_INPUT, troughcolor=BG_PANEL, bordercolor=BG_PANEL,
                     arrowcolor=FG_MUTED, relief="flat", arrowsize=12, width=10)
    style.map("Dark.Vertical.TScrollbar",
              background=[("active", ACCENT_BLUE), ("pressed", ACCENT_BLUE)])

    _TREEVIEW_STYLE_READY = True


def add_focus_border(widget, container=None):
    """Gives a widget the same border behaviour tk.Listbox gets for free.

    style_listbox() sets highlightbackground/highlightcolor, so a Listbox
    already shows a neutral border that turns blue on focus. ttk widgets have
    no such option - their border comes from the theme and stays put - so the
    frame around them carries it instead, switching colour with focus.

    Pass the frame that wraps `widget`; defaults to its parent.
    """
    box = container if container is not None else widget.master
    box.configure(highlightthickness=1, highlightbackground=BORDER_COLOR,
                  highlightcolor=BORDER_COLOR)

    def on_focus(_event=None):
        box.configure(highlightbackground=ACCENT_BLUE, highlightcolor=ACCENT_BLUE)

    def off_focus(_event=None):
        box.configure(highlightbackground=BORDER_COLOR, highlightcolor=BORDER_COLOR)

    widget.bind("<FocusIn>", on_focus, add="+")
    widget.bind("<FocusOut>", off_focus, add="+")
    # Clicking a row focuses the tree, but ttk does not always raise FocusIn
    # before the selection changes, so mirror it here too.
    widget.bind("<Button-1>", on_focus, add="+")
    return box


def _drag_selection(widget):
    """The selected row ids, as strings, for either a ttk.Treeview
    (.selection()) or a classic Listbox (.curselection(), which returns
    index objects rather than strings)."""
    try:
        return list(widget.selection())
    except (AttributeError, tk.TclError) as _e:
        _swallowed(_e, "_drag_selection")
    try:
        return [str(i) for i in widget.curselection()]
    except (AttributeError, tk.TclError):
        return []


def _drag_row_at(widget, event):
    """The row id under the event, for either widget type - None if the
    click landed below the last row (a Treeview reports one there
    itself; a Listbox's .nearest() does not, so that case needs its own
    bbox check)."""
    try:
        return widget.identify_row(event.y) or None
    except (AttributeError, tk.TclError) as _e:
        _swallowed(_e, "_drag_row_at")
    try:
        idx = widget.nearest(event.y)
        bbox = widget.bbox(idx)
        if bbox and bbox[1] <= event.y <= bbox[1] + bbox[3]:
            return str(idx)
    except (AttributeError, tk.TclError) as _e:
        _swallowed(_e, "_drag_row_at")
    return None


def _drag_item_text(widget, iid):
    """Whatever text best names this row. A Treeview's own tree-column
    text is tried first; failing that (a "headings"-only Treeview keeps
    the tree column hidden and its text empty), the longest of its
    column values is used - name columns tend to be the widest thing in
    the row, a number or a length figure the narrowest. A Listbox is
    simpler: there is only ever the one string.
    """
    try:
        text = (widget.item(iid, "text") or "").strip()
        if text:
            return text
        vals = [str(v).strip() for v in (widget.item(iid, "values") or ())]
        vals = [v for v in vals if v]
        return max(vals, key=len) if vals else ""
    except (AttributeError, tk.TclError) as _e:
        _swallowed(_e, "_drag_item_text")
    try:
        return str(widget.get(int(iid))).strip()
    except (AttributeError, tk.TclError, ValueError):
        return ""


def _drag_select_only(widget, iid):
    """Collapses the selection to just `iid` - the "plain click after
    all" case in enable_drag_transfer, for either widget type."""
    try:
        widget.selection_set(iid)
        return
    except (AttributeError, tk.TclError) as _e:
        _swallowed(_e, "_drag_select_only")
    try:
        widget.selection_clear(0, "end")
        widget.selection_set(int(iid))
    except (AttributeError, tk.TclError, ValueError) as _e:
        _swallowed(_e, "_drag_select_only")


def _drag_all_names(widget):
    """Every row's display text in `widget`, for either widget type - used
    to tell whether something about to be dragged onto this widget is
    already in it."""
    try:
        children = widget.get_children("")
        return {_drag_item_text(widget, iid) for iid in children}
    except (AttributeError, tk.TclError) as _e:
        _swallowed(_e, "_drag_all_names")
    try:
        return {str(widget.get(i)).strip() for i in range(widget.size())}
    except (AttributeError, tk.TclError):
        return set()


def enable_drag_reorder(widget, on_reorder, threshold=6):
    """Lets rows be dragged up and down within `widget` to reorder them.

    `on_reorder(indices, target)` gets the selected row indices and the
    position they should land at, as indices into the CURRENT order, and is
    expected to do the move and redraw. It is the same operation the up/down
    arrow buttons perform, just addressed absolutely instead of one step at
    a time; those buttons stay, since a keyboard-driven move is still the
    precise way to do it.

    Runs alongside enable_drag_transfer() on the same widget, and the two
    cannot both fire: transfer acts only when the release lands over the
    OTHER list, this one only when it lands over this list.

    A line is drawn between rows at the insertion point rather than
    highlighting the row under the cursor. Highlighting says "this row",
    which is the wrong answer - what is being chosen is a gap, and whether
    the drop lands above or below the row under the pointer depends on
    which half of it the cursor is in.
    """
    state = {"start": None, "rows": [], "moved": False, "line": None}
    # A classic Listbox extends its selection on every motion event
    # (tk::ListboxMotion), so a drag meant to reorder swept everything it
    # passed over into the selection. ttk.Treeview selects on press only and
    # needs none of this, hence the distinction rather than doing it for
    # both - suppressing motion on a Treeview would cost nothing here, but
    # it would be a rule nobody could explain later.
    is_listbox = not hasattr(widget, "get_children")

    def _row_count():
        try:
            return len(widget.get_children())
        except (AttributeError, tk.TclError):
            try:
                return widget.size()
            except (AttributeError, tk.TclError):
                return 0

    def _gap_at(y):
        """Insertion index for a pointer at `y`: the row under it, or the
        one after, depending on which half of the row the cursor is in."""
        n = _row_count()
        if not n:
            return 0
        iid = _drag_row_at(widget, type("E", (), {"y": y})())
        if iid is None:
            return n                      # below the last row
        try:
            idx = int(widget.index(iid))
        except (AttributeError, tk.TclError):
            idx = int(iid)
        try:
            bbox = widget.bbox(iid)
        except (AttributeError, tk.TclError):
            bbox = None
        if bbox and len(bbox) >= 4 and y > bbox[1] + bbox[3] / 2:
            idx += 1
        return max(0, min(idx, n))

    def _clear_line():
        if state["line"] is not None:
            try:
                state["line"].destroy()
            except tk.TclError as _e:
                _swallowed(_e, "enable_drag_reorder._clear_line")
            state["line"] = None

    def _show_line(gap):
        n = _row_count()
        try:
            kids = widget.get_children()
        except (AttributeError, tk.TclError):
            kids = [str(i) for i in range(n)]
        y = None
        if gap < len(kids):
            b = widget.bbox(kids[gap])
            if b:
                y = b[1]
        elif kids:
            b = widget.bbox(kids[-1])
            if b:
                y = b[1] + b[3]
        if y is None:
            _clear_line()
            return
        if state["line"] is None:
            state["line"] = tk.Frame(widget, bg=ACCENT_ORANGE, height=2)
        state["line"].place(x=0, y=max(0, y - 1), relwidth=1.0, height=2)
        state["line"].lift()

    def _capture_rows():
        state["rows"] = sorted(int(i) for i in _drag_selection(widget))

    def on_press(event):
        state.update(start=(event.x, event.y), moved=False)
        state["rows"] = []
        if is_listbox:
            # after_idle, not here: this binding runs BEFORE the widget's
            # own class binding, so right now the selection is still
            # whatever it was before this click. One idle cycle later it is
            # what the press actually selected, and motion can be
            # suppressed from the very first pixel instead of after a
            # threshold - which is where the sweeping happened.
            widget.after_idle(_capture_rows)

    def on_motion(event):
        if state["start"] is None:
            # The press never reached us. enable_drag_transfer returns
            # "break" from its own press handler when an already-selected
            # row is clicked with several selected - that defers the
            # collapse-to-one-row, and it also stops every binding added
            # after it, including ours.
            #
            # Left there, this was the ONE case that got no suppression, so
            # tk::ListboxMotion extended the selection under the pointer
            # while dragging several rows out to be removed - and what came
            # off the list was whatever the sweep had left selected rather
            # than what was picked. Pick the drag up from the first motion
            # event instead, and take the selection as it stands now.
            state["start"] = (event.x, event.y)
            state["rows"] = sorted(int(i) for i in _drag_selection(widget))
        if not state["moved"]:
            if abs(event.y - state["start"][1]) < threshold:
                # Still suppressed on a Listbox, or the rows swept over
                # before the threshold is reached would already be selected
                # by the time the drag is recognised.
                return "break" if (is_listbox and state["rows"]) else None
            if not state["rows"]:
                # ttk decides what a click selects AFTER this module's press
                # binding returns, so on press it can still be the previous
                # selection. The Listbox path captured it on idle already.
                state["rows"] = sorted(int(i) for i in _drag_selection(widget))
            state["moved"] = True
        if not state["rows"]:
            return
        _show_line(_gap_at(event.y))
        if is_listbox:
            # Stops tk::ListboxMotion from growing the selection under the
            # pointer. The rows being dragged stay the rows that were
            # selected when the drag started.
            return "break"

    def on_release(event):
        rows, moved = state["rows"], state["moved"]
        state.update(start=None, rows=[], moved=False)
        _clear_line()
        if not moved or not rows:
            return
        # Only when the pointer is still inside this widget - otherwise the
        # release belongs to enable_drag_transfer's drop on the other list.
        if not (0 <= event.x <= widget.winfo_width()
                and 0 <= event.y <= widget.winfo_height()):
            return
        gap = _gap_at(event.y)
        # A drop inside the block being dragged is a no-op, not a move to
        # the row above it: the user let go where the rows already are.
        if rows[0] <= gap <= rows[-1] + 1:
            return
        try:
            on_reorder(rows, gap)
        except Exception as _e:
            _swallowed(_e, "enable_drag_reorder.on_reorder")

    widget.bind("<ButtonPress-1>", on_press, add="+")
    widget.bind("<B1-Motion>", on_motion, add="+")
    widget.bind("<ButtonRelease-1>", on_release, add="+")


def reorder_list(items, indices, gap):
    """`items` with the rows at `indices` lifted out and reinserted at
    `gap`, which is an index into the ORIGINAL list. Returns the new list
    and the new positions of the moved rows."""
    picked = [items[i] for i in indices]
    rest = [x for i, x in enumerate(items) if i not in set(indices)]
    # Every removed row that sat before the gap shifts it left by one.
    target = gap - sum(1 for i in indices if i < gap)
    target = max(0, min(target, len(rest)))
    return rest[:target] + picked + rest[target:], list(
        range(target, target + len(picked)))


def enable_drag_transfer(source, dest, on_drop):
    """Lets an item be dragged out of `source` and dropped onto `dest`,
    calling `on_drop()` - the same function the dialog's own "->" button
    already calls - when the mouse is released while over `dest`.

    Deliberately thin: it never touches what's selected in `source`. A
    press-and-drag that never leaves `source` is exactly the extended-
    selection drag the widget already handles on its own, so by the time
    the mouse comes back up somewhere over `dest`, whatever `source`
    itself decided is selected is already correct - on_drop only has to
    act on that, the same as a click on the arrow button would.

    Tk keeps mouse-motion and the eventual release routed to the widget
    that was pressed, even once the pointer has left it, so binding
    ButtonRelease-1 on `source` still fires with the drop's screen
    position - no separate binding on `dest` is needed to notice it.

    A small label follows the cursor once the drag has actually moved a
    few pixels (not on a plain click, which would otherwise flash it for
    a frame), naming what's being carried - the item's own text if one
    can be read from the widget, otherwise just a count. It is worked out
    at that point, not on the initial press: ttk's own click handling
    (which decides what actually ends up selected) runs after this
    module's press binding returns, so reading the selection immediately
    on press could still be looking at whatever was selected before this
    click, not what is about to be dragged.

    Something already present in `dest` is called out in the label too -
    "(in use)" for a single item, "N in use" alongside the names for
    several - coloured orange instead of the usual blue, the same as any
    other warning in the app.

    Multi-selection survives the drag too, which needs its own trick:
    ttk's native click handling collapses a multi-selection down to just
    the clicked row immediately on press, before a drag ever gets a
    chance to use the rest of it. Clicking an already-selected row with
    no Shift/Control held is the one case that is genuinely ambiguous -
    it could still turn into a plain click - so that specific press is
    intercepted and the collapse deferred: if the mouse comes back up
    without having moved, it is applied then (a plain click still narrows
    the selection, exactly as it always did); if a drag happened instead,
    the full selection was never touched and on_drop sees all of it.
    """
    state = {"active": False, "start": None, "tip": None, "label": "",
             "held_row": None}

    def _label_for_drag():
        sel = _drag_selection(source)
        if not sel:
            return "1 item", False
        names = [t for t in (_drag_item_text(source, iid) for iid in sel[:3]) if t]
        if names:
            label = ", ".join(names)
            if len(sel) > 3:
                label += f" +{len(sel) - 3}"
        else:
            label = f"{len(sel)} item" + ("s" if len(sel) != 1 else "")
        dest_names = _drag_all_names(dest)
        in_use = sum(1 for iid in sel if _drag_item_text(source, iid) in dest_names)
        if not in_use:
            return label, False
        if len(sel) == 1:
            return f"{label}  (in use)", True
        return f"{label}  \u00b7  {in_use} in use", True

    def _make_tip(warn):
        tip = tk.Toplevel(source)
        tip.wm_overrideredirect(True)
        try:
            tip.attributes("-topmost", True)
        except tk.TclError as _e:
            _swallowed(_e, "enable_drag_transfer._make_tip")
        color = ACCENT_ORANGE if warn else ACCENT_BLUE
        lbl = tk.Label(tip, text=state["label"], bg=BG_INPUT,
                       fg=ACCENT_ORANGE if warn else FG_TEXT,
                       font=ui_font(9), padx=8, pady=4, bd=0,
                       highlightthickness=1, highlightbackground=color)
        lbl.pack()
        return tip

    def on_press(event):
        state["active"] = True
        state["start"] = (event.x_root, event.y_root)
        state["held_row"] = None
        # Shift (0x0001) or Control (0x0004) held means this press is
        # unambiguously "modify the selection", not "maybe drag the whole
        # thing" - left alone, so Ctrl-click-to-deselect and friends keep
        # working exactly as they did before any of this existed.
        modified = bool(event.state & 0x0001) or bool(event.state & 0x0004)
        row = _drag_row_at(source, event)
        cur_sel = _drag_selection(source)
        if row and row in cur_sel and len(cur_sel) > 1 and not modified:
            state["held_row"] = row
            return "break"

    def on_motion(event):
        if not state["active"]:
            return
        if state["tip"] is None:
            sx, sy = state["start"]
            # A few pixels of slack: without it, a plain click (no actual
            # drag at all) could still fire one stray motion event and
            # flash the label for a single frame before the release.
            if abs(event.x_root - sx) < 4 and abs(event.y_root - sy) < 4:
                return
            # Read now, not on press - see the docstring for why.
            state["label"], warn = _label_for_drag()
            try:
                state["tip"] = _make_tip(warn)
            except tk.TclError:
                state["tip"] = False
        if state["tip"]:
            try:
                state["tip"].wm_geometry(f"+{event.x_root + 14}+{event.y_root + 12}")
            except tk.TclError as _e:
                _swallowed(_e, "enable_drag_transfer.on_motion")
        over = _point_in_widget(event.x_root, event.y_root, dest)
        try:
            source.config(cursor="hand2" if over else "")
        except tk.TclError as _e:
            _swallowed(_e, "enable_drag_transfer.on_motion")

    def on_release(event):
        if not state["active"]:
            return
        state["active"] = False
        # Whether a drag actually happened - checked before the tip (the
        # only record of it) is torn down below.
        dragged = bool(state["tip"])
        try:
            source.config(cursor="")
        except tk.TclError as _e:
            _swallowed(_e, "enable_drag_transfer.on_release")
        if state["tip"]:
            try:
                state["tip"].destroy()
            except tk.TclError as _e:
                _swallowed(_e, "enable_drag_transfer.on_release")
        state["tip"] = None
        if state["held_row"] is not None and not dragged:
            # The deferred plain click: apply now the collapse-to-one-row
            # that a normal click would have done immediately.
            _drag_select_only(source, state["held_row"])
            return
        if _point_in_widget(event.x_root, event.y_root, dest):
            on_drop()

    source.bind("<ButtonPress-1>", on_press, add="+")
    source.bind("<B1-Motion>", on_motion, add="+")
    source.bind("<ButtonRelease-1>", on_release, add="+")


def _point_in_widget(x_root, y_root, widget):
    wx, wy = widget.winfo_rootx(), widget.winfo_rooty()
    return (wx <= x_root <= wx + widget.winfo_width()
            and wy <= y_root <= wy + widget.winfo_height())


def style_checkbutton(cb, bg=None):
    bg = bg or BG_DARK
    cb.config(bg=bg, fg=FG_TEXT, selectcolor=BG_INPUT,
              activebackground=bg, activeforeground=FG_TEXT,
              disabledforeground=FG_MUTED,
              relief="flat", bd=0, highlightthickness=0,
              font=ui_font(9))


class RoundedButton(tk.Canvas):
    def __init__(self, parent, text="", command=None, bg=BTN_BLUE, fg="#FFFFFF",
                 parent_bg=None, width=110, height=32, radius=10,
                 font=ui_font(9, "bold"), state="normal", outline_color=None,
                 outline_width=2, led_color=None):
        parent_bg = parent_bg or parent.cget("bg")
        super().__init__(parent, width=sc(width), height=sc(height), bg=parent_bg,
                          highlightthickness=0, bd=0, cursor="hand2")
        self.command = command
        self.bg_color = bg
        self.fg_color = fg
        self.text = text
        self.font = font
        # Scaled here, in the one constructor all 115 call sites go through,
        # rather than at each of them. The numbers passed in stay the design
        # sizes at 100 %.
        width, height = sc(width), sc(height)
        self.radius = min(sc(radius), height // 2)
        self.width = width
        self.height = height
        self._state = state
        self.outline_color = outline_color
        self.outline_width = max(1, sc(outline_width))
        # A lit strip along the bottom edge, in place of a colored fill. The
        # button itself stays a neutral key and the color says which one it
        # is - see bottom_button_style().
        self.led_color = led_color
        self._draw()
        self.bind("<Button-1>", self._on_click)
        self.bind("<Enter>", self._on_enter)
        self.bind("<Leave>", self._on_leave)

    def _round_rect(self, x1, y1, x2, y2, r, **kw):
        self.create_arc(x1, y1, x1 + 2*r, y1 + 2*r, start=90, extent=90, style="pieslice", **kw)
        self.create_arc(x2 - 2*r, y1, x2, y1 + 2*r, start=0, extent=90, style="pieslice", **kw)
        self.create_arc(x1, y2 - 2*r, x1 + 2*r, y2, start=180, extent=90, style="pieslice", **kw)
        self.create_arc(x2 - 2*r, y2 - 2*r, x2, y2, start=270, extent=90, style="pieslice", **kw)
        self.create_rectangle(x1 + r, y1, x2 - r, y2, **kw)
        self.create_rectangle(x1, y1 + r, x2, y2 - r, **kw)

    def _draw(self, hover=False):
        _t0 = time.time()
        self.delete("all")
        fill = self._lighten(self.bg_color) if hover and self._state == "normal" else self.bg_color
        if self._state == "disabled":
            fill = BORDER_COLOR
        self._round_rect(1, 1, self.width - 1, self.height - 1, self.radius, fill=fill, outline=fill)
        if self.outline_color and self._state == "normal":
            self._round_outline(1, 1, self.width - 1, self.height - 1,
                                self.radius, self.outline_color,
                                self.outline_width)
        text_fg = self.fg_color if self._state == "normal" else FG_MUTED
        # Inset far enough to clear the corner radius, so the strip meets two
        # straight edges rather than being clipped by the curves.
        lit = self.led_color and self._state == "normal"
        if lit:
            inset = max(self.radius + sc(2), sc(10))
            top = self.height - sc(7)
            self.create_rectangle(inset, top, self.width - inset, top + sc(3),
                                  fill=self.led_color, outline=self.led_color)
        # Nudged up by the strip's own height plus its gap, so the label stays
        # optically centred in the space that is left rather than sitting on
        # the strip.
        self.create_text(self.width / 2, self.height / 2 - (sc(3) if lit else 0),
                          text=self.text, fill=text_fg, font=self.font)
        _PERF["button_draws"] += 1
        _PERF["button_draw_time"] += time.time() - _t0

    def _round_outline(self, x1, y1, x2, y2, r, color, width=2):
        """Rounded-rectangle ring: four corner arcs plus four straight edges.

        Deliberately not _round_rect with an empty fill - that shape is made
        of pieslices and rectangles, so outlining it draws the corner radii
        and the seams between the pieces straight across the button.
        """
        inset = width / 2
        x1, y1, x2, y2 = x1 + inset, y1 + inset, x2 - inset, y2 - inset
        r = max(1, min(r, (x2 - x1) / 2, (y2 - y1) / 2))
        for cx, cy, start in ((x1, y1, 90), (x2 - 2 * r, y1, 0),
                              (x1, y2 - 2 * r, 180), (x2 - 2 * r, y2 - 2 * r, 270)):
            self.create_arc(cx, cy, cx + 2 * r, cy + 2 * r, start=start,
                            extent=90, style="arc", outline=color, width=width)
        self.create_line(x1 + r, y1, x2 - r, y1, fill=color, width=width)
        self.create_line(x1 + r, y2, x2 - r, y2, fill=color, width=width)
        self.create_line(x1, y1 + r, x1, y2 - r, fill=color, width=width)
        self.create_line(x2, y1 + r, x2, y2 - r, fill=color, width=width)

    def _lighten(self, hex_color, amount=18):
        hex_color = hex_color.lstrip("#")
        r, g, b = (int(hex_color[i:i+2], 16) for i in (0, 2, 4))
        r, g, b = (min(255, c + amount) for c in (r, g, b))
        return f"#{r:02x}{g:02x}{b:02x}"

    def _on_enter(self, event):
        if self._state == "normal":
            self._draw(hover=True)
            self.config(cursor="hand2")

    def _on_leave(self, event):
        self._draw(hover=False)

    def _on_click(self, event):
        if self._state == "normal" and self.command:
            self.command()

    def _darken(self, hex_color, amount=26):
        """`hex_color` with each channel pulled down, clamped at 0.

        A flat subtraction rather than a multiply: the button fills are
        already mid-tones, and scaling them by a factor moves the light ones
        much further than the dark ones, so the same call gave a barely
        visible change on one theme and a black hole on another.
        """
        hex_color = hex_color.lstrip("#")
        r, g, b = (int(hex_color[i:i + 2], 16) for i in (0, 2, 4))
        r, g, b = (max(0, c - amount) for c in (r, g, b))
        return f"#{r:02x}{g:02x}{b:02x}"

    def set_outline(self, color):
        """Ring around the button, or None to remove it."""
        if color != self.outline_color:
            self.outline_color = color
            self._draw()

    def config_state(self, state):
        self._state = state
        self._draw()

    def set_text(self, text):
        """Changes the label. Not config(text=...): this is a Canvas, so that
        call raises a TclError - the text is drawn, not a widget option."""
        if text != self.text:
            self.text = text
            self._draw()

class RoundedDropdown(tk.Canvas):
    def __init__(self, parent, variable, values, command=None, parent_bg=None,
                 width=110, height=30, radius=10, font=ui_font(9, "bold"),
                 value_color_fn=None, entry_builder=None):
        parent_bg = parent_bg or parent.cget("bg")
        # Scaled in the constructor, exactly as RoundedButton does it, so the
        # numbers at the call sites stay the design sizes. Without this the
        # font grew with the UI scale and its frame did not, which left the
        # text pressed against the arrow.
        width, height = sc(width), sc(height)
        super().__init__(parent, width=width, height=height, bg=parent_bg,
                          highlightthickness=0, bd=0, cursor="hand2")
        self.variable = variable
        self.values = values
        self.command = command
        self.width = width
        self.height = height
        self.radius = min(sc(radius), height // 2)
        self.font = font
        # Optional callable(value) -> color-string-or-None, checked fresh
        # every time the menu opens (not cached), so it can reflect live
        # state - e.g. highlighting which banks currently hold samples.
        self.value_color_fn = value_color_fn
        # Optional callable(menu, value, kwargs) -> True if it added its own
        # entry for that value. Lets a caller turn one entry into a cascade
        # (the bank selector uses this for Move/Copy To) without this generic
        # widget having to know anything about banks.
        self.entry_builder = entry_builder
        self._draw()
        self._enabled = True
        self.bind("<ButtonRelease-1>", self._open_menu)
        self.bind("<Enter>", lambda e: self._draw(hover=self._enabled))
        self.bind("<Leave>", lambda e: self._draw(hover=False))
        # The trace id is kept so it can be taken off again on destroy.
        #
        # This used to be an anonymous lambda with no way to remove it, which
        # was harmless only as long as the variable and the dropdown died
        # together - true for the pads, where both belong to the same
        # SampleSlot. The pad editor now hands this widget a variable that
        # OUTLIVES it (the pad's own target_rate), and an un-removable trace
        # on a longer-lived variable is a dangling callback: close the editor,
        # change the rate on the pad, and the trace fires _draw() on a canvas
        # Tk has already deleted - "invalid command name .!roundeddropdown".
        self._var_trace = self.variable.trace_add("write", self._on_var_write)
        self.bind("<Destroy>", self._on_destroy)

    def _on_var_write(self, *_args):
        # Guarded as well as removed: a trace can still fire between the
        # widget's deletion and the <Destroy> handler running.
        try:
            if not self.winfo_exists():
                return
        except tk.TclError:
            return
        self._draw()

    def _on_destroy(self, event=None):
        if event is not None and event.widget is not self:
            return
        name = getattr(self, "_var_trace", None)
        if name:
            try:
                self.variable.trace_remove("write", name)
            except Exception as _e:
                _swallowed(_e, "RoundedDropdown._on_destroy")
            self._var_trace = None

    def _round_rect(self, x1, y1, x2, y2, r, **kw):
        self.create_arc(x1, y1, x1 + 2*r, y1 + 2*r, start=90, extent=90, style="pieslice", **kw)
        self.create_arc(x2 - 2*r, y1, x2, y1 + 2*r, start=0, extent=90, style="pieslice", **kw)
        self.create_arc(x1, y2 - 2*r, x1 + 2*r, y2, start=180, extent=90, style="pieslice", **kw)
        self.create_arc(x2 - 2*r, y2 - 2*r, x2, y2, start=270, extent=90, style="pieslice", **kw)
        self.create_rectangle(x1 + r, y1, x2 - r, y2, **kw)
        self.create_rectangle(x1, y1 + r, x2, y2 - r, **kw)

    def _draw(self, hover=False):
        _t0 = time.time()
        self.delete("all")
        enabled = getattr(self, "_enabled", True)
        fill = HOVER_BG if (hover and enabled) else BG_INPUT
        self._round_rect(1, 1, self.width - 1, self.height - 1, self.radius, fill=fill, outline=fill)
        self.create_text(14, self.height / 2, text=str(self.variable.get()),
                          fill=FG_TEXT if enabled else FG_MUTED, font=self.font, anchor="w")
        self.create_text(self.width - 14, self.height / 2, text="\u25be",
                          fill=ACCENT_BLUE if enabled else BORDER_LIGHT,
                          font=ui_font(8), anchor="e")
        _PERF["dropdown_draws"] += 1
        _PERF["dropdown_draw_time"] += time.time() - _t0

    def set_enabled(self, on):
        """Greys the dropdown out and stops it opening. Used where a choice
        exists but has nothing to act on - the bank selector in the
        all-banks view, where every bank is on screen already."""
        if on == getattr(self, "_enabled", True):
            return
        self._enabled = on
        try:
            self.config(cursor="hand2" if on else "arrow")
        except tk.TclError as _e:
            _swallowed(_e, "RoundedDropdown.set_enabled")
        self._draw()

    def _open_menu(self, event):
        if not getattr(self, "_enabled", True):
            return
        menu = tk.Menu(self, tearoff=0, bg=BG_INPUT, fg=FG_TEXT,
                        activebackground=ACCENT_BLUE, activeforeground=ON_ACCENT_BLUE,
                        font=self.font, bd=0, relief="flat")
        for v in self.values:
            color = self.value_color_fn(v) if self.value_color_fn else None
            kwargs = {"foreground": color} if color else {}
            if self.entry_builder and self.entry_builder(menu, v, kwargs):
                continue  # the builder supplied its own entry for this value
            menu.add_command(label=str(v), command=lambda val=v: self._select(val), **kwargs)
        menu.bind("<Escape>", lambda e: menu.unpost())
        menu.tk_popup(event.x_root, event.y_root)

    def _select(self, val):
        self.variable.set(val)
        self._draw()
        if self.command:
            self.command(val)


class RoundedPanel(tk.Frame):
    """A Canvas-backed panel with rounded corners, a lighter border, and a
    title label, used in place of tk.LabelFrame (which cannot have rounded
    corners). Add child widgets to `.body`, not to the panel itself.

    Both the canvas (background) and body (content) occupy the same grid
    cell of `self`, so `self`'s size is naturally driven by body's packed
    content (exactly like a LabelFrame would size itself) -- no manual
    width/height math needed."""

    def __init__(self, parent, title="", parent_bg=None, panel_bg=BG_PANEL,
                 border=BORDER_LIGHT, radius=14, title_fg=ACCENT_BLUE,
                 title_font=ui_font(10, "bold"),
                 body_padx=14, body_pady=(30, 12)):
        parent_bg = parent_bg or parent.cget("bg")
        super().__init__(parent, bg=parent_bg)
        self.grid_rowconfigure(0, weight=1)
        self.grid_columnconfigure(0, weight=1)
        self._panel_bg = panel_bg
        self._border = border
        self._border_width = 1
        self._radius = sc(radius)
        self._title = title
        self._title_fg = title_fg
        self._title_font = title_font

        self.canvas = tk.Canvas(self, bg=parent_bg, highlightthickness=0, bd=0, width=1, height=1)
        self.canvas.grid(row=0, column=0, sticky="nsew")

        self.body = tk.Frame(self, bg=panel_bg)
        # The top half of body_pady is what keeps the body clear of the
        # title drawn on the canvas above it. The title grows with the UI
        # scale, so this has to as well or the two overlap.
        self.body.grid(row=0, column=0, sticky="nsew",
                        padx=_sc_pad(body_padx), pady=_sc_pad(body_pady))

        self.canvas.bind("<Configure>", lambda e: self._redraw())

    def _round_rect(self, x1, y1, x2, y2, r, fill=None, outline=None, width=1):
        # 1) Filled background: pieslices/rectangles use fill as their own
        #    outline color too, so no stray radius/seam lines are visible.
        self.canvas.create_arc(x1, y1, x1 + 2*r, y1 + 2*r, start=90, extent=90, style="pieslice", fill=fill, outline=fill)
        self.canvas.create_arc(x2 - 2*r, y1, x2, y1 + 2*r, start=0, extent=90, style="pieslice", fill=fill, outline=fill)
        self.canvas.create_arc(x1, y2 - 2*r, x1 + 2*r, y2, start=180, extent=90, style="pieslice", fill=fill, outline=fill)
        self.canvas.create_arc(x2 - 2*r, y2 - 2*r, x2, y2, start=270, extent=90, style="pieslice", fill=fill, outline=fill)
        self.canvas.create_rectangle(x1 + r, y1, x2 - r, y2, fill=fill, outline=fill)
        self.canvas.create_rectangle(x1, y1 + r, x2, y2 - r, fill=fill, outline=fill)

        # 2) Border: drawn once on top, as pure arcs (no radius lines) + straight edges.
        if outline:
            self.canvas.create_arc(x1, y1, x1 + 2*r, y1 + 2*r, start=90, extent=90, style="arc", outline=outline, width=width)
            self.canvas.create_arc(x2 - 2*r, y1, x2, y1 + 2*r, start=0, extent=90, style="arc", outline=outline, width=width)
            self.canvas.create_arc(x1, y2 - 2*r, x1 + 2*r, y2, start=180, extent=90, style="arc", outline=outline, width=width)
            self.canvas.create_arc(x2 - 2*r, y2 - 2*r, x2, y2, start=270, extent=90, style="arc", outline=outline, width=width)
            self.canvas.create_line(x1 + r, y1, x2 - r, y1, fill=outline, width=width)
            self.canvas.create_line(x1 + r, y2, x2 - r, y2, fill=outline, width=width)
            self.canvas.create_line(x1, y1 + r, x1, y2 - r, fill=outline, width=width)
            self.canvas.create_line(x2, y1 + r, x2, y2 - r, fill=outline, width=width)

    def set_title(self, title):
        """Panels whose heading carries a live count need this - the title is
        painted on the canvas, so it cannot just be a Label to reconfigure."""
        if title != self._title:
            self._title = title
            self._redraw(force=True)

    def set_border_color(self, color, width=None):
        """Changes the border color, and optionally its width.

        force=True for the same reason set_title() needs it: only the
        colour changed, not the size, so _redraw()'s size cache would skip
        the paint. Used for drag-and-drop hover feedback - a colour change
        alone at the default 1px width is easy to miss at a glance, so
        hover states should pass a thicker width too.
        """
        self._border = color
        if width is not None:
            self._border_width = width
        self._redraw(force=True)

    def _redraw(self, force=False):
        w = self.canvas.winfo_width()
        h = self.canvas.winfo_height()
        if w < 4 or h < 4:
            return
        # <Configure> fires repeatedly while the layout settles, often with a
        # size that hasn't actually changed. Redrawing ~14 canvas items each
        # time is pure waste (and on X11 every item is a server round-trip),
        # so bail out unless the size really differs.
        # force= for the callers that change what is DRAWN rather than the
        # size it is drawn at. Without it set_title() was a no-op: the
        # panel had not resized, so this guard returned before painting,
        # and the new heading only appeared once something else happened
        # to change the panel's size.
        if not force and getattr(self, "_last_size", None) == (w, h):
            return
        self._last_size = (w, h)

        _t0 = time.time()
        self.canvas.delete("all")
        r = min(self._radius, w // 2, h // 2)
        self._round_rect(1, 1, w - 1, h - 1, r, fill=self._panel_bg, outline=self._border,
                          width=self._border_width)
        if self._title:
            self.canvas.create_text(sc(16), sc(16), text=self._title, anchor="w",
                                     fill=self._title_fg, font=self._title_font)
        _PERF["panel_redraws"] += 1
        _PERF["panel_redraw_time"] += time.time() - _t0


def wm_position_suffix(win):
    """The window's own "+x+y", exactly as the window manager reports it.

    Not winfo_x()/winfo_y(): with a reparenting window manager - which is
    every normal Linux desktop - those are the coordinates of the window
    inside its title-bar frame, while wm geometry expects screen
    coordinates. Feeding one back as the other moves the window up and left
    by the thickness of the decoration on every resize, which is the jump
    that showed up when switching between the single-bank and all-banks
    views.

    Returns "" when the position is not known yet, so the caller can fall
    back to a size-only request.
    """
    try:
        match = re.search(r"([+-]\d+[+-]\d+)$", win.geometry())
        return match.group(1) if match else ""
    except Exception:
        return ""


def clamp_position_suffix(where, w, h, screen_w, screen_h):
    """Moves a "+x+y" so that a w x h window still fits on the screen.

    Takes the position as a STRING rather than reading it from the window.
    Callers read theirs before they reset the geometry - reading it again
    afterwards gets whatever Tk falls back to, which is the trap
    wm_position_suffix() already documents, and re-reading here quietly
    threw away the good value the caller had saved.

    Only the position is adjusted, never the size. Capping the height
    instead would be worse: pack() hands out space in call order, so a
    window shorter than its content loses whatever was packed last, which
    in every dialog here is the button row.

    An empty or unparseable `where` comes back unchanged, so the caller
    falls back to a size-only request exactly as before.
    """
    parts = re.findall(r"[+-]\d+", where or "")
    if len(parts) != 2:
        return where
    try:
        x, y = int(parts[0]), int(parts[1])
        # The same allowance the main window uses for the taskbar and the
        # title bar, so both agree on where the usable screen ends.
        y = max(0, min(y, screen_h - SCREEN_HEIGHT_ALLOWANCE - h))
        x = max(0, min(x, screen_w - w))
        return f"+{x}+{y}"
    except Exception:
        return where


def center_toplevel_on_parent(win, parent, align="center"):
    """Centers a Toplevel over its parent (or the screen, if no parent) -
    without this, some platforms (notably Windows) default new Toplevels to
    the top-left corner of the screen instead of somewhere sensible.

    Also guarantees the window is at least as large as its contents want to
    be. pack() hands out space in call order, so when a window is smaller
    than its content the widget packed last - always the button row - gets
    whatever is left, which can be nothing. Every dialog in this app funnels
    through here, so raising the floor once covers all of them and means a
    theme with a larger font can never hide a Cancel button.
    """
    try:
        win.update_idletasks()
        need_w, need_h = win.winfo_reqwidth(), win.winfo_reqheight()
        # Never past the screen: a floor taller than the display would leave
        # the window unusable rather than merely cramped.
        cap_w = int(win.winfo_screenwidth() * 0.95)
        cap_h = int(win.winfo_screenheight() * 0.90)
        cur_w, cur_h = win.winfo_width(), win.winfo_height()
        want_w, want_h = min(need_w, cap_w), min(need_h, cap_h)
        if want_w > cur_w or want_h > cur_h:
            win.geometry(f"{max(cur_w, want_w)}x{max(cur_h, want_h)}")
            win.update_idletasks()
        try:
            min_w, min_h = win.minsize()
            win.minsize(max(min_w, want_w), max(min_h, want_h))
        except Exception:
            win.minsize(want_w, want_h)
        w, h = win.winfo_width(), win.winfo_height()
        if align == "top":
            # For windows that grow after opening. Centring a short window
            # and then letting it get taller pushes the bottom off the
            # screen, and no amount of clamping afterwards can undo that on
            # a display where the tall version simply does not fit below
            # the middle. So the top edge is lined up with the parent's
            # instead: the whole height of the parent and everything under
            # it is then free to grow into, while the dialog still reads as
            # belonging to the window it came from rather than floating up
            # at the edge of the screen. Horizontally still centred on it.
            if parent is not None:
                y = parent.winfo_rooty()
                x = parent.winfo_rootx() + (parent.winfo_width() - w) // 2
            else:
                y = WINDOW_TOP_MARGIN
                x = (win.winfo_screenwidth() - w) // 2
        elif parent is not None:
            x = parent.winfo_rootx() + (parent.winfo_width() - w) // 2
            y = parent.winfo_rooty() + (parent.winfo_height() - h) // 2
        else:
            x = (win.winfo_screenwidth() - w) // 2
            y = (win.winfo_screenheight() - h) // 2
        # Pulled back onto the screen. Centring alone only guaranteed the
        # TOP edge (via max(0, y)); a tall dialog over a parent sitting low
        # on the display still had its bottom - and therefore its buttons -
        # hanging off the end.
        y = max(0, min(y, win.winfo_screenheight() - SCREEN_HEIGHT_ALLOWANCE - h))
        x = max(0, min(x, win.winfo_screenwidth() - w))
        # Size and position in one call. Two calls means two configure
        # requests, and a window manager is free to show the window between
        # them - which is the jump this is meant to avoid.
        win.geometry(f"{w}x{h}+{x}+{y}")
    except Exception as _e:
        _swallowed(_e, "center_toplevel_on_parent")
    finally:
        # Undoes the withdraw() in style_toplevel(). In a finally block
        # because a dialog that failed to measure itself must still appear:
        # an invisible modal window would lock the app up.
        try:
            win.deiconify()
        except Exception as _e:
            _swallowed(_e, "center_toplevel_on_parent")


class _DarkMessageDialog(tk.Toplevel):
    """Dark-themed replacement for tkinter.messagebox popups, since those
    always render in the native OS light style regardless of app theme."""

    _ICONS = {
        "info": ("\u2139", ACCENT_BLUE),
        "warning": ("\u26a0", ACCENT_ORANGE),
        "error": ("\u2715", ACCENT_RED),
        "question": ("?", ACCENT_BLUE),
    }

    def __init__(self, parent, title, message, kind="info", buttons="ok"):
        super().__init__(parent)
        self.title(title or "")
        style_toplevel(self)
        self.resizable(False, False)
        self.result = None

        icon_char, icon_color = self._ICONS.get(kind, self._ICONS["info"])

        body = tk.Frame(self, bg=BG_DARK, padx=20, pady=16)
        body.pack(fill="both", expand=True)

        top_row = tk.Frame(body, bg=BG_DARK)
        top_row.pack(fill="both", expand=True)

        icon_label = tk.Label(top_row, text=icon_char, font=ui_font(20, "bold"))
        style_label(icon_label, fg=icon_color)
        icon_label.pack(side="left", padx=(0, 14), anchor="n")

        msg_label = tk.Label(top_row, text=str(message), justify="left", anchor="w", wraplength=sc(380))
        style_label(msg_label, font=ui_font(10))
        msg_label.pack(side="left", fill="both", expand=True)

        btn_row = tk.Frame(body, bg=BG_DARK)
        btn_row.pack(fill="x", pady=(16, 0))

        if buttons == "yesno":
            no_btn = RoundedButton(btn_row, text="No", command=self._on_no,
                                    bg=BG_INPUT, fg=FG_TEXT, parent_bg=BG_DARK, width=80)
            no_btn.pack(side="right", padx=4)
            yes_btn = RoundedButton(btn_row, text="Yes", command=self._on_yes,
                                     bg=BTN_GREEN, fg="#FFFFFF", parent_bg=BG_DARK, width=80)
            yes_btn.pack(side="right", padx=4)
        else:
            ok_btn = RoundedButton(btn_row, text="OK", command=self._on_ok,
                                    bg=BTN_BLUE, fg="#FFFFFF", parent_bg=BG_DARK, width=80)
            ok_btn.pack(side="right", padx=4)

        self.protocol("WM_DELETE_WINDOW", self._on_close)
        self.transient(parent)
        self.update_idletasks()
        self._center_on_parent(parent)
        self._safe_grab()

    def _center_on_parent(self, parent):
        center_toplevel_on_parent(self, parent)

    def _safe_grab(self, attempt=0):
        try:
            self.update_idletasks()
            self.grab_set()
        except tk.TclError:
            if attempt < 20:
                self.after(50, lambda: self._safe_grab(attempt + 1))
            return
        self.deiconify()
        self.lift()
        self.focus_force()
        self.wait_visibility()
        self.grab_set()
        self.focus_set()

    def _on_ok(self):
        self.result = True
        self.destroy()

    def _on_yes(self):
        self.result = True
        self.destroy()

    def _on_no(self):
        self.result = False
        self.destroy()

    def _on_close(self):
        self.destroy()


def _dark_msg_parent(parent):
    return parent or getattr(tk, "_default_root", None)


def dark_showinfo(title=None, message=None, parent=None, **kwargs):
    root = _dark_msg_parent(parent)
    dlg = _DarkMessageDialog(root, title, message, kind="info", buttons="ok")
    root.wait_window(dlg)


def dark_showwarning(title=None, message=None, parent=None, **kwargs):
    root = _dark_msg_parent(parent)
    dlg = _DarkMessageDialog(root, title, message, kind="warning", buttons="ok")
    root.wait_window(dlg)


def dark_showerror(title=None, message=None, parent=None, **kwargs):
    root = _dark_msg_parent(parent)
    dlg = _DarkMessageDialog(root, title, message, kind="error", buttons="ok")
    root.wait_window(dlg)


def dark_askyesno(title=None, message=None, parent=None, **kwargs):
    root = _dark_msg_parent(parent)
    dlg = _DarkMessageDialog(root, title, message, kind="question", buttons="yesno")
    root.wait_window(dlg)
    return bool(dlg.result)


class _DarkTextPromptDialog(tk.Toplevel):
    """Dark-themed replacement for tkinter.simpledialog.askstring."""

    def __init__(self, parent, title, prompt, initial=""):
        super().__init__(parent)
        self.title(title or "")
        style_toplevel(self)
        self.resizable(False, False)
        self.result = None

        body = tk.Frame(self, bg=BG_DARK, padx=20, pady=16)
        body.pack(fill="both", expand=True)

        prompt_label = tk.Label(body, text=prompt, anchor="w", justify="left", wraplength=sc(320))
        style_label(prompt_label, font=ui_font(10))
        prompt_label.pack(fill="x", pady=(0, 8))

        self.entry_var = tk.StringVar(value=initial)
        entry = tk.Entry(body, textvariable=self.entry_var, bg=BG_INPUT, fg=FG_TEXT,
                          insertbackground=FG_TEXT, relief="flat", highlightthickness=1,
                          highlightbackground=BORDER_COLOR, highlightcolor=ACCENT_BLUE,
                          font=ui_font(10), width=32)
        entry.pack(fill="x")
        entry.bind("<Return>", lambda e: self._on_ok())
        entry.bind("<Escape>", lambda e: self._on_cancel())
        entry.focus_set()
        entry.select_range(0, tk.END)

        btn_row = tk.Frame(body, bg=BG_DARK)
        btn_row.pack(fill="x", pady=(16, 0))
        cancel_btn = RoundedButton(btn_row, text="Cancel", command=self._on_cancel,
                                    bg=BG_INPUT, fg=FG_TEXT, parent_bg=BG_DARK, width=80)
        cancel_btn.pack(side="right", padx=4)
        ok_btn = RoundedButton(btn_row, text="OK", command=self._on_ok,
                                bg=BTN_BLUE, fg="#FFFFFF", parent_bg=BG_DARK, width=80)
        ok_btn.pack(side="right", padx=4)

        self.protocol("WM_DELETE_WINDOW", self._on_cancel)
        self.transient(parent)
        self.update_idletasks()
        center_toplevel_on_parent(self, parent)
        self._safe_grab()

    def _safe_grab(self, attempt=0):
        try:
            self.update_idletasks()
            self.grab_set()
        except tk.TclError:
            if attempt < 20:
                self.after(50, lambda: self._safe_grab(attempt + 1))
            return
        self.deiconify()
        self.lift()
        self.focus_force()
        self.wait_visibility()
        self.grab_set()

    def _on_ok(self):
        self.result = self.entry_var.get()
        self.destroy()

    def _on_cancel(self):
        self.result = None
        self.destroy()


class _DarkChoiceDialog(tk.Toplevel):
    """Pick one of a handful of strings. A dark-themed listbox prompt.

    A dropdown was the obvious choice and the wrong one: the list here is
    the set of folders the user has, which is exactly what they want to
    look at while deciding. A closed dropdown hides it.
    """

    def __init__(self, parent, title, prompt, options, initial=None):
        super().__init__(parent)
        self.title(title or "")
        style_toplevel(self)
        self.resizable(False, False)
        self.result = None

        body = tk.Frame(self, bg=BG_DARK, padx=20, pady=16)
        body.pack(fill="both", expand=True)
        prompt_label = tk.Label(body, text=prompt, anchor="w", justify="left",
                                 wraplength=sc(320))
        style_label(prompt_label, font=ui_font(10))
        prompt_label.pack(fill="x", pady=(0, 8))

        self.lb = tk.Listbox(body, exportselection=False,
                              height=min(8, max(3, len(options))))
        style_listbox(self.lb)
        for opt in options:
            self.lb.insert("end", opt)
        want = initial if initial in options else options[0]
        self.lb.selection_set(options.index(want))
        self.lb.activate(options.index(want))
        self.lb.pack(fill="both", expand=True)
        self.lb.bind("<Double-Button-1>", lambda e: self._on_ok())
        self.lb.bind("<Return>", lambda e: self._on_ok())
        self.lb.bind("<Escape>", lambda e: self._on_cancel())
        self.lb.focus_set()

        btn_row = tk.Frame(body, bg=BG_DARK)
        btn_row.pack(fill="x", pady=(16, 0))
        cancel_btn = RoundedButton(btn_row, text="Cancel", command=self._on_cancel,
                                    bg=BG_INPUT, fg=FG_TEXT, parent_bg=BG_DARK, width=80)
        cancel_btn.pack(side="right", padx=4)
        ok_btn = RoundedButton(btn_row, text="OK", command=self._on_ok,
                                bg=BTN_BLUE, fg="#FFFFFF", parent_bg=BG_DARK, width=80)
        ok_btn.pack(side="right", padx=4)

        self.protocol("WM_DELETE_WINDOW", self._on_cancel)
        self.transient(parent)
        self.update_idletasks()
        center_toplevel_on_parent(self, parent)
        self._safe_grab()

    def _safe_grab(self, attempt=0):
        try:
            self.update_idletasks()
            self.grab_set()
        except tk.TclError:
            if attempt < 20:
                self.after(50, lambda: self._safe_grab(attempt + 1))
            return
        self.deiconify()
        self.lift()
        self.focus_force()

    def _on_ok(self):
        cur = self.lb.curselection()
        self.result = self.lb.get(cur[0]) if cur else None
        self.destroy()

    def _on_cancel(self):
        self.result = None
        self.destroy()


def dark_ask_choice(parent, title, prompt, options, initial=None):
    if not options:
        return None
    root = _dark_msg_parent(parent)
    dlg = _DarkChoiceDialog(root, title, prompt, list(options), initial)
    root.wait_window(dlg)
    return dlg.result


def dark_ask_text(parent, title, prompt, initial=""):
    root = _dark_msg_parent(parent)
    dlg = _DarkTextPromptDialog(root, title, prompt, initial)
    root.wait_window(dlg)
    return dlg.result


def wt_entry_is_multi(entry):
    """Whether a library entry is a multi family rather than a drawn pair.

    Multi families carry `shapes`/`labels` and have no `a`/`b`. Several
    places used `entry.get("a")` as the test for "is this a usable shape",
    which silently answered no for every multi family - and each of those
    places then dropped it.
    """
    return (isinstance(entry, dict) and entry.get("kind") == "multi"
            and bool(entry.get("shapes")))


def wt_entry_is_usable(entry):
    """Whether an entry holds shape data of either kind."""
    return (isinstance(entry, dict)
            and (bool(entry.get("a")) or wt_entry_is_multi(entry)))


def _wt_quantize(points):
    """Points to int16, the storage form both the packs and the built-in
    collections use: half the bytes, and the error is below what the band
    limiter passes anyway."""
    return [int(round(max(-1.0, min(1.0, float(v))) * 32767)) for v in points]


def _wt_dequantize(values):
    return [v / 32767.0 for v in values]


def user_family_pack_path(group):
    """Where the pack for one user folder lives."""
    return os.path.join(USER_FAMILY_DIR, safe_base_name(group) + ".p6wf")


def export_user_family_pack(group, entries):
    """Writes one folder of drawn shapes as a single shareable file.

    LZMA over JSON, not plain JSON: a chained import of sixteen shapes is
    sixteen pairs of 512 floats, which is roughly a megabyte of decimal
    text and compresses to a small fraction of that. The result is one file
    someone can send, and the point sizes are stored as int16 for the same
    reason the built-in collections are - they cost half the bytes and the
    difference is below what the band limiter passes anyway.

    Returns the path, or raises.
    """
    os.makedirs(USER_FAMILY_DIR, exist_ok=True)
    shapes = []
    for name, e in entries:
        if wt_entry_is_multi(e):
            # A multi family used to fall through the `not e.get("a")` test
            # below and be dropped without a word, so it could never be
            # shared or backed up at all.
            shapes.append({
                "name": name, "kind": "multi",
                "shapes": [_wt_quantize(p) for p in e.get("shapes") or []],
                "labels": [str(x) for x in (e.get("labels") or [])],
            })
            continue
        if not isinstance(e, dict) or not e.get("a"):
            continue
        shapes.append({
            "name": name,
            "a": _wt_quantize(e.get("a", [])),
            "b": _wt_quantize(e.get("b", [])),
        })
    if not shapes:
        raise ValueError("this folder holds no drawn shapes")
    blob = {"format": USER_FAMILY_FORMAT, "group": group,
            "app": APP_VERSION, "shapes": shapes}
    raw = lzma.compress(json.dumps(blob, separators=(",", ":")).encode("utf-8"),
                        preset=6)
    path = user_family_pack_path(group)
    with open(path, "wb") as f:
        f.write(raw)
    return path


def import_user_family_pack(path):
    """Reads a pack back to (group, [entry dicts]).

    The group name travels with the file, so a pack lands in the folder it
    was exported from rather than in whatever the receiving app calls its
    default - two people swapping packs end up with the same folder names.
    """
    with open(path, "rb") as f:
        blob = json.loads(lzma.decompress(f.read()).decode("utf-8"))
    if not isinstance(blob, dict) or "shapes" not in blob:
        raise ValueError("not a PyP6 waveform pack")
    if int(blob.get("format", 0)) > USER_FAMILY_FORMAT:
        raise ValueError(
            f"this pack was written by a newer PyP6 (format "
            f"{blob.get('format')}, this build reads {USER_FAMILY_FORMAT})")
    group = str(blob.get("group") or WT_DEFAULT_USER_GROUP)
    out = []
    for sh in blob["shapes"]:
        name = str(sh.get("name") or "Shape")
        if sh.get("kind") == "multi":
            shapes = [_wt_dequantize(p) for p in sh.get("shapes") or []]
            if not shapes:
                continue
            out.append({"kind": "multi", "name": name, "group": group,
                        # Trimmed on the way in as well as on the way out:
                        # a pack edited by hand must not be able to put a
                        # family with more steps than the table has into
                        # the library.
                        "shapes": shapes[:WT_MULTI_MAX],
                        "labels": [str(x) for x in
                                   (sh.get("labels") or [])][:WT_MULTI_MAX]})
            continue
        a = _wt_dequantize(sh.get("a", []))
        b = _wt_dequantize(sh.get("b", []))
        if not a:
            continue
        out.append({"kind": "draw", "name": name,
                    "a": a, "b": b or list(a), "group": group})
    if not out:
        raise ValueError("the pack holds no usable shapes")
    return group, out


def sync_user_family_packs(library):
    """Writes one pack per user folder, and removes packs with no folder.

    Runs after every change to the drawn library, so the folder on disk is
    always a faithful copy rather than something the user has to remember
    to export. Handing a collection to someone else is then just copying a
    file out of it.

    Failures are reported and swallowed: losing the ability to share a
    folder must never cost the edit that was just made to it.
    """
    groups = {}
    for name, entry in (library or {}).items():
        if wt_entry_is_usable(entry):
            groups.setdefault(entry.get("group") or WT_DEFAULT_USER_GROUP,
                              []).append((name, entry))
    try:
        os.makedirs(USER_FAMILY_DIR, exist_ok=True)
        wanted = set()
        for group, entries in groups.items():
            wanted.add(os.path.basename(user_family_pack_path(group)))
            export_user_family_pack(group, entries)
        # A folder whose last shape was deleted must lose its pack too -
        # otherwise the next start would import it straight back.
        for fname in os.listdir(USER_FAMILY_DIR):
            if fname.lower().endswith(".p6wf") and fname not in wanted:
                os.remove(os.path.join(USER_FAMILY_DIR, fname))
    except Exception as e:
        print(f"Could not update {USER_FAMILY_DIR}: {e}")


def import_new_user_family_packs(library):
    """Adds any pack in the folder whose group the library does not have.

    This is the whole import path: drop a .p6wf someone sent you into
    ~/.pyp6/user_wave_families and it is there the next time the Synth
    dialog opens. Only MISSING groups are read - a pack for a folder that
    already exists is the copy this app wrote itself, and reading it back
    would undo every edit made since.

    Returns (number of shapes added, [group names]).
    """
    have = {(e.get("group") or WT_DEFAULT_USER_GROUP)
            for e in (library or {}).values() if isinstance(e, dict)}
    added, groups = 0, []
    try:
        files = sorted(f for f in os.listdir(USER_FAMILY_DIR)
                       if f.lower().endswith(".p6wf"))
    except OSError:
        return 0, []
    for fname in files:
        try:
            group, shapes = import_user_family_pack(
                os.path.join(USER_FAMILY_DIR, fname))
        except Exception as e:
            print(f"Skipping {fname}: {e}")
            continue
        if group in have:
            continue
        # Unique against built-ins too, not just the library: a cycle file
        # named "Sine.wav" or "Saw.wav" would otherwise get the exact name
        # of a built-in family, and inserting it into the tree under a
        # different parent with the same id silently corrupts the rest of
        # the fill (see _fill_available).
        builtin_names = {nm for nm, _f in WT_FAMILIES}
        for sh in shapes:
            # Unique against the WHOLE library, not just this group: two
            # folders each holding a "Cycle 01" would otherwise overwrite
            # one another.
            base, n = sh["name"], 2
            while sh["name"] in library or sh["name"] in builtin_names:
                sh["name"] = f"{base} ({n})"
                n += 1
            library[sh["name"]] = sh
            added += 1
        have.add(group)
        groups.append(group)
    return added, groups


def load_drawn_library():
    """All shapes the user has drawn so far, keyed by name.

    A drawing is not a setting you can retype - if it is gone, it is gone.
    So it is kept for good, and every wavetable dialog starts with the full
    palette rather than a blank slate.
    """
    try:
        with open(WAVEFORM_LIB_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return {}
    out = {}
    if isinstance(data, dict):
        for name, entry in data.items():
            if wt_entry_is_usable(entry):
                entry["name"] = name
                # Shapes drawn before folders existed have no group; they
                # land in the default one rather than in a nameless node.
                entry["group"] = entry.get("group") or WT_DEFAULT_USER_GROUP
                out[name] = entry
    return out


def _drawn_lib_record(name, e):
    """One library entry in its on-disk form.

    Multi families used to be flattened into `{"kind": "draw", "a": [],
    "b": []}` here, because the writer named the five keys a drawn shape
    has and a multi family has none of the two that carry its data. The
    entry survived the save as an empty husk and was then dropped by the
    loader on the next start - so a multi family never lived past closing
    the app, without anything being reported.
    """
    group = e.get("group") or WT_DEFAULT_USER_GROUP
    if wt_entry_is_multi(e):
        return {"kind": "multi", "name": name, "group": group,
                "shapes": e.get("shapes") or [],
                "labels": [str(x) for x in (e.get("labels") or [])]}
    return {"kind": "draw", "name": name, "group": group,
            "a": e.get("a") or [], "b": e.get("b") or []}


def save_drawn_library(library, sync_folder=True):
    try:
        os.makedirs(APP_DIR, exist_ok=True)
        with open(WAVEFORM_LIB_FILE, "w", encoding="utf-8") as f:
            # "group" is the user folder this shape sits in. Written here
            # because this function used to drop every key it did not name,
            # so a folder assignment would have survived exactly until the
            # next save.
            json.dump({n: _drawn_lib_record(n, e)
                       for n, e in library.items()}, f)
    except Exception as e:
        print(f"Could not save the waveform library: {e}")
        return False
    # Here, not at the call sites: there are six of them, and a seventh
    # appears every time a new way to change a shape is added. Tied to the
    # save itself, the folder cannot fall out of step with the library.
    if sync_folder:
        sync_user_family_packs(library)
    return True


def load_config():
    if os.path.exists(CONFIG_FILE):
        try:
            with open(CONFIG_FILE, "r") as f:
                return json.load(f)
        except Exception as _e:
            _swallowed(_e, "load_config")
    return {}


def load_last_sample_dir():
    data = load_config()
    path = data.get("last_sample_dir")
    if path and os.path.isdir(path):
        return path
    return None


def find_prm_for(filepath):
    """The .PRM settings file the P-6 stores next to a sample, if this
    sample still has one. Matched on the base name, which is how the device
    pairs them.

    Module level rather than a method: the pads and the storage header both
    need to ask this question now, and neither should have to reach into
    P6ManagerApp to do it.
    """
    if not filepath:
        return None
    base = os.path.splitext(filepath)[0]
    for ext in (".PRM", ".prm"):
        if os.path.isfile(base + ext):
            return base + ext
    return None


def load_last_export_dir():
    """Where the user last pointed the "P6 → Bank" import.

    Deliberately the folder they PICKED (usually the P-6 drive), not the
    BANK_x folder it resolved to - the device exports a different bank next
    time, so re-resolving from the picked folder finds whichever bank is
    actually there now."""
    data = load_config()
    path = data.get("last_export_dir")
    if path and os.path.isdir(path):
        return path
    return None


def save_config_value(key, value):
    data = load_config()
    data[key] = value
    try:
        # On a fresh install ~/.pyp6 doesn't exist yet - without this the
        # write fails and (because of the except below) settings would
        # silently never be saved.
        os.makedirs(APP_DIR, exist_ok=True)
        with open(CONFIG_FILE, "w") as f:
            json.dump(data, f)
    except Exception as e:
        print(f"Could not save configuration: {e}")


PRESET_MANIFEST_NAME = "preset.json"
PRESET_FORMAT_VERSION = 3  # v3: pads can carry wavetable synth state
#     v2: force_mono moved from one global flag to per-bank


def is_preset_folder(path):
    """A folder counts as a preset if it directly contains preset.json."""
    return os.path.isfile(os.path.join(path, PRESET_MANIFEST_NAME))


def read_preset_manifest(preset_dir):
    """Returns the parsed preset.json, or None if missing/unreadable."""
    manifest_path = os.path.join(preset_dir, PRESET_MANIFEST_NAME)
    try:
        with open(manifest_path, "r") as f:
            data = json.load(f)
        if not isinstance(data, dict) or "banks" not in data:
            return None
        return data
    except Exception:
        return None


def write_preset_manifest(preset_dir, data):
    manifest_path = os.path.join(preset_dir, PRESET_MANIFEST_NAME)
    with open(manifest_path, "w") as f:
        json.dump(data, f, indent=2)


def verify_preset_folder(preset_dir):
    """Checks that a preset folder is complete and portable.

    A preset is meant to be handed to someone else, so anything that only
    works on the machine that wrote it counts as a fault: absolute paths,
    paths escaping the folder, a manifest entry with no file behind it, or a
    wavetable pad whose .PRM never made it across.

    Returns (problems, stray_files) - both lists of plain strings, empty when
    the folder is sound.
    """
    problems, referenced = [], set()
    manifest = read_preset_manifest(preset_dir)
    if not manifest:
        return ([f"{PRESET_MANIFEST_NAME} is missing or unreadable."], [])
    referenced.add(os.path.normcase(os.path.join(preset_dir, PRESET_MANIFEST_NAME)))

    try:
        version = int(manifest.get("format_version", 1))
    except (TypeError, ValueError):
        problems.append("format_version is not a number.")
        version = 1
    if version > PRESET_FORMAT_VERSION:
        problems.append(f"Written in format version {version}; this build "
                        f"understands up to {PRESET_FORMAT_VERSION}.")

    for bank, bank_entry in sorted((manifest.get("banks") or {}).items()):
        if not isinstance(bank_entry, dict):
            problems.append(f"BANK_{bank}: malformed entry.")
            continue
        for pad_key, entry in sorted((bank_entry.get("pads") or {}).items()):
            if not entry:
                continue
            where = f"BANK_{bank}/PAD_{pad_key}"
            rel = entry.get("filepath") or ""
            if not rel:
                problems.append(f"{where}: no file recorded.")
                continue
            # Portability first: an absolute path or a .. escape means the
            # preset only works on the machine that wrote it.
            if os.path.isabs(rel) or rel[1:3] == ":\\" or ".." in rel.split("/"):
                problems.append(f"{where}: path is not relative to the preset "
                                f"folder ({rel}).")
                continue
            wav = os.path.normpath(os.path.join(preset_dir, *rel.split("/")))
            if not os.path.isfile(wav):
                problems.append(f"{where}: {rel} is missing.")
                continue
            referenced.add(os.path.normcase(wav))
            if os.path.getsize(wav) == 0:
                problems.append(f"{where}: {rel} is empty (0 bytes).")
                continue
            # The check that matters: the device and the player both need a
            # readable RIFF file, and a truncated or half-written copy only
            # shows up here, not in the manifest.
            try:
                with wave.open(wav, "rb") as wf:
                    frames, rate = wf.getnframes(), wf.getframerate()
                if frames == 0:
                    problems.append(f"{where}: {rel} contains no audio frames.")
            except Exception as e:
                problems.append(f"{where}: {rel} is not a readable WAV ({e}).")
                continue

            wt = entry.get("wavetable")
            if wt:
                # A shared preset must carry every shape its table was built
                # from. Without them the receiving side silently drops the
                # family from the step order and a rebuild sounds different.
                cfg = (wt or {}).get("config") or {}
                drawn = {e.get("name") for e in (cfg.get("custom") or [])
                         if isinstance(e, dict)}
                for fam in (cfg.get("families") or []):
                    if (wt_canonical_family(fam) not in WT_FAMILY_MAP
                            and fam not in drawn):
                        problems.append(f"{where}: step order uses \"{fam}\", but no "
                                        f"such waveform is stored in the preset.")
                for e in (cfg.get("custom") or []):
                    if not isinstance(e, dict) or not e.get("a"):
                        problems.append(f"{where}: a drawn waveform entry has no "
                                        f"shape data.")
                    elif len(e.get("a") or []) < 4:
                        problems.append(f"{where}: drawn waveform "
                                        f"\"{e.get('name')}\" is too short to use.")
            prm = os.path.splitext(wav)[0] + ".PRM"
            referenced.add(os.path.normcase(prm))
            if wt:
                meta = (wt or {}).get("meta") or {}
                if not os.path.isfile(prm):
                    problems.append(f"{where}: wavetable pad without its .PRM - "
                                    f"the P-6 cannot loop a segment without it.")
                else:
                    try:
                        text = open(prm, "r").read()
                        got = {k: int(v) for k, v in
                               re.findall(r"^(\w+)\s*=\s*(-?\d+)\s*$", text, re.M)}
                    except Exception as e:
                        got = {}
                        problems.append(f"{where}: .PRM unreadable ({e}).")
                    want_size = meta.get("L")
                    if want_size and got.get("SIZE") not in (None, want_size):
                        problems.append(f"{where}: .PRM SIZE is {got.get('SIZE')}, "
                                        f"expected {want_size}.")
                    if got and got.get("LOOP") != 1:
                        problems.append(f"{where}: .PRM does not have LOOP enabled.")
                total = meta.get("total_frames")
                if total and frames and frames != total:
                    problems.append(f"{where}: WAV has {frames} frames, the wavetable "
                                    f"was built with {total}.")
                if rate and rate != WT_SR:
                    problems.append(f"{where}: wavetable is {rate} Hz, expected {WT_SR}.")

    strays = []
    for root, dirs, files in os.walk(preset_dir):
        dirs[:] = [d for d in dirs if not d.startswith(".")]
        for name in files:
            full = os.path.join(root, name)
            if os.path.normcase(full) not in referenced:
                strays.append(os.path.relpath(full, preset_dir).replace(os.sep, "/"))
    return problems, sorted(strays)


def load_recent_presets():
    return load_config().get("recent_presets", [])


def add_recent_preset(path):
    recents = load_recent_presets()
    recents = [p for p in recents if p != path]  # de-dupe, most-recent-first
    recents.insert(0, path)
    recents = recents[:5]
    save_config_value("recent_presets", recents)


