def _vintage_wt_families():
    """Builds the Vintage Collection entries for WT_FAMILIES.

    Decoded once at import. Failure is survivable on purpose: a corrupt
    blob costs the two collections, not the ability to open the app, and
    every other family goes on working.
    """
    try:
        raw = lzma.decompress(base64.b64decode(VINTAGE_WT_DATA))
        q = np.frombuffer(raw, dtype="<i2").astype(np.float64) / 32767.0
        pts = VINTAGE_WT_POINTS
        arr = q.reshape(2, 16, 2, pts)
    except Exception as e:
        print(f"Vintage Collection could not be decoded: {e}")
        return []
    out = []
    for vol in range(2):
        # "VC1 - No 03" rather than "Vintage Collection 1 - No 03": the
        # collection is now the folder these sit in, so repeating it in
        # every one of the sixteen names only made the list harder to read.
        names = []
        for k in range(16):
            name = f"VC{vol + 1} - No {k + 1:02d}"
            entry = {"kind": "draw", "name": name,
                     "a": arr[vol, k, 0].tolist(), "b": arr[vol, k, 1].tolist()}
            out.append((name, wt_drawn_family(entry)))
            names.append(name)
        WT_FAMILY_GROUPS.append((f"Vintage Collection {vol + 1}", names))
    return out



# Two sweep collections built from Waldorf Microwave single cycles, stored
# the same way as VINTAGE_WT_DATA: int16 points, LZMA, base64. Shape is
# (2 collections, 64 waveforms, 512 points).
#
# The CHAIN is stored, not the pairs. Both collections are continuous
# sweeps - waveform 2 ends family 1 and starts family 2 - so keeping 64
# waveforms and deriving the 63 families from consecutive pairs holds
# exactly the same data as 126 stored endpoints, in half the bytes.
