    ("TENV_SUSTAIN", 255), ("TENV_RELEASE", 3), ("TENV_TIME_KEYF", 255),
    ("TVF_TYPE", 0), ("TVF_CUTOFF", 255), ("TVF_RESO", 0), ("TVF_KEYF", 255),
