for _wt_name, _wt_ov in PRM_TEMPLATES.items():
    if _wt_ov.get("GATE") != 1 or _wt_ov.get("LOOP") != 1:
        raise ValueError(f"PRM template {_wt_name!r} must set GATE = 1 and LOOP = 1")


def phrase_number(bank, pad):
    """PHRASE = bank index * 6 + (pad - 1). Bank 'A', pad 1 -> 0."""
    return BANKS.index(bank) * len(PADS) + (pad - 1)


def render_prm(bank, pad, start_frame, size_frames, total_frames,
               template="Init", poly=None, overrides=None):
    """The .PRM text for one pad. `poly` overrides the template's MONO_POLY."""
    values = dict(PRM_DEFAULTS)
    values.update(PRM_TEMPLATES[template])
    values["PHRASE"] = phrase_number(bank, pad)
    values["START_POS"] = int(start_frame)
    values["SIZE"] = int(size_frames)
    # The device writes the full frame count here even for a one-segment loop
    values["LOOP_SIZE"] = int(total_frames)
    if poly is not None:
        values["MONO_POLY"] = 1 if poly else 0
    if overrides:
        values.update(overrides)
    return "".join(f"{k}\t= {values[k]}\n" for k, _v in PRM_DEFAULTS)


def retarget_prm_phrase(prm_path, bank, pad):
    """Reads a device .PRM and returns its text with PHRASE set to `bank`/`pad`.

    PHRASE names the slot the settings belong to. The device wrote it for
    wherever the sample sat when it was exported, so a sample that has since
    been copied or dragged to another bank/pad goes back carrying the old
    number - which is the same mistake the wavetable path already guards
    against by rendering its .PRM fresh every time.

    Only that one line is touched. The rest of the file is undocumented and
    is passed through byte for byte, so nothing else can be lost by getting
    this wrong. Returns None if the file cannot be read or holds no PHRASE
    line, and the caller then falls back to copying it verbatim - a stale
    PHRASE is still better than no settings at all.
    """
    try:
        with open(prm_path, "r", newline="") as f:
            text = f.read()
    except Exception as e:
        print(f"Could not read settings file {prm_path}: {e}")
        return None
    want = phrase_number(bank, pad)
    out, found = [], False
    for line in text.splitlines(keepends=True):
        stripped = line.strip()
        if not found and stripped.split("=")[0].strip().upper() == "PHRASE":
            # Keep the file's own line ending, whatever it is - these come
            # off a FAT volume written by the device, not by this app.
            ending = line[len(line.rstrip("\r\n")):]
            out.append(f"PHRASE\t= {want}{ending}")
            found = True
        else:
            out.append(line)
    if not found:
        return None
    return "".join(out)


def write_wavetable_files(pcm, wav_path, prm_text=None):
    with wave.open(wav_path, "wb") as f:
        f.setnchannels(1)
        f.setsampwidth(2)
        f.setframerate(WT_SR)
        f.writeframes(pcm.tobytes())
    if prm_text is not None:
        with open(os.path.splitext(wav_path)[0] + ".PRM", "w", newline="") as f:
            f.write(prm_text)


def write_wavetable_map(rows, meta, csv_path, cfg=None):
    """A one-page overview of what sits where on the START knob.

    One row per ZONE, not per step. It used to be 255 rows - one for every
    segment - carrying the frame offset, the time offset and the morph
    position as a four-decimal float. None of that is reachable from the
    device: you cannot turn START to "frame 40440", and the morph value is
    an internal parameter. What you can do is turn the knob to a number, so
    that is what the sheet is built around.

    Dropped: start_frame, start_sec, the per-step morph value, the harmonic
    count and the segment length in frames. Kept: the START range of each
    zone, what it sounds like at either end of that range, and the tuning -
    the three things you need in front of you while playing the pad.
    """
    import csv as _csv
    names = meta.get("families") or []
    counts = meta.get("counts") or []
    # cfg's own note first, so this sheet and the pad's header cannot
    # disagree; derived from the frequency only when there is no cfg.
    note = ((cfg or {}).get("note") or "").strip() \
        or cycle_note_name(meta.get("f_real") or 0.0)
    register = ((cfg or {}).get("register") or "").strip()
    source = wavetable_source_label(cfg) if cfg else ""

    # rows are [step, family, morph, waveform, frame, sec]; the description
    # of the first and last step of a zone is what the zone travels between.
    by_zone, start = [], 0
    for name, count in zip(names, counts):
        if count <= 0:
            continue
        first = rows[start] if start < len(rows) else None
        last = rows[start + count - 1] if start + count - 1 < len(rows) else first
        by_zone.append((start, start + count - 1, name,
                        (first[3] if first else ""), (last[3] if last else ""),
                        count))
        start += count

    with open(csv_path, "w", newline="") as f:
        wr = _csv.writer(f)
        wr.writerow(["PyP6 wavetable overview"])
        if source:
            wr.writerow(["Built from", source])
        if register:
            wr.writerow(["Register", register])
        wr.writerow(["Root note", f"{note} ({meta.get('f_real', 0):.2f} Hz)"
                     if note else f"{meta.get('f_real', 0):.2f} Hz"])
        wr.writerow(["Zones", f"{len(by_zone)} across {WT_SEGMENTS} START positions"])
        wr.writerow(["On the P-6", "set SIZE to 1, then turn START"])
        wr.writerow([])
        wr.writerow(["START from", "START to", "Zone", "Starts as", "Ends as",
                     "Positions"])
        for lo, hi, name, d0, d1, count in by_zone:
            # One waveform per position means there is nothing to travel
            # between, so the two description columns would just repeat.
            same = (count == 1) or (d0 == d1)
            wr.writerow([lo, hi, name, d0, "" if same else d1, count])


def wavetable_source_label(cfg):
    """Where the table's waveforms came from, for the pad's header line.

    Simple mode builds from one named set, so the name is the useful answer
    - "Basic", "Vintage Collection 1". Advanced is a selection the user put
    together by hand and has no name, so it says so instead of naming the
    first family and implying the rest.

    Tables built before this was recorded carry no mode; they get nothing
    rather than a guess.
    """
    if not isinstance(cfg, dict):
        return ""
    if cfg.get("mode") == "Simple":
        return str(cfg.get("simple_set") or "").strip()
    if cfg.get("mode"):
        return "Custom Selection"
    return ""


def wavetable_summary(cfg, meta):
    """Two short lines for the pad's mini display.

    Everything that only matters while building the table was dropped:
    harmonic count, cutoff, cent error, duration in seconds, segment length
    in frames, and the segment count (always WT_SEGMENTS, so it carries no
    information per pad). What is left is what identifies the pad at a glance.
    Two lines instead of three buys enough room for a readable font size in a
    field that is only 50 px tall.
    """
    fams = meta.get("families") or []
    counts = meta.get("counts") or []
    per = "-" if not counts else (
        str(counts[0]) if len(set(counts)) == 1 else f"{min(counts)}-{max(counts)}")
    dot = " \u00b7 "
    # The upward span the band limiting was optimised for. At 0 the table is
    # only guaranteed clean at its own pitch, and there is nothing to report.
    span = f"{dot}+{cfg['up']} st" if cfg.get("up") else ""
    return [
        f"{cfg['register']}{dot}{cfg['note']}{dot}{meta['f_real']:.2f} Hz{span}",
        f"{len(fams)} famil{'y' if len(fams) == 1 else 'ies'}{dot}~{per} steps",
    ]


