class RoundedScrollbar(tk.Canvas):
    """Canvas scrollbar in the app's palette, since ttk.Scrollbar follows the
    ttk theme and ignores the color scheme entirely.

    Hides itself whenever the content fits, so it behaves like the rest of
    the UI where chrome only appears when it has something to do. Works under
    grid or pack - it asks the widget which manager placed it.
    """

    THICKNESS = 10

    def __init__(self, parent, orient="vertical", command=None, parent_bg=None,
                 auto_hide=True):
        self.orient = orient
        self.command = command
        parent_bg = parent_bg or parent.cget("bg")
        # Both axes on purpose. Tk's Canvas defaults are 10c x 7c - roughly
        # 378 x 265 px - and leaving the long axis at that makes the
        # scrollbar demand that much room from whatever holds it. fill="x"
        # or fill="y" stretches it to the real length anyway, so asking for
        # 1 px costs nothing.
        kw = ({"width": self.THICKNESS, "height": 1} if orient == "vertical"
              else {"height": self.THICKNESS, "width": 1})
        super().__init__(parent, bg=parent_bg, highlightthickness=0, bd=0, **kw)
        self._first, self._last = 0.0, 1.0
        self._visible = True
        # With auto_hide off, set() only ever redraws. Callers that place the
        # scrollbar themselves need it to stay exactly where they put it -
        # having two places decide the same thing is how it ends up nowhere.
        self.auto_hide = auto_hide
        self._pack_info = None
        self._manager = None        # how it was placed, recorded when hiding
        self._placed = False        # has anyone ever placed it?
        self._drag_origin = None
        self.bind("<Configure>", lambda e: self._draw())
        self.bind("<Button-1>", self._on_press)
        self.bind("<B1-Motion>", self._on_drag)
        self.bind("<ButtonRelease-1>", lambda e: setattr(self, "_drag_origin", None))

    def pack(self, *a, **kw):
        self._placed = True
        return super().pack(*a, **kw)

    def grid(self, *a, **kw):
        self._placed = True
        return super().grid(*a, **kw)

    def _span(self):
        return (self.winfo_height() if self.orient == "vertical"
                else self.winfo_width())

    def set(self, first, last):
        self._first, self._last = float(first), float(last)
        fits = self._first <= 0.0 and self._last >= 1.0
        if not self.auto_hide:
            self._draw()
            return
        # Nothing to do until somebody has placed it once - and note that
        # "not currently managed" is not the same thing, because that is
        # exactly the state this class puts it in when it hides itself.
        if not self.winfo_manager() and not self._placed:
            self._draw()
            return
        if fits and self._visible:
            self._visible = False
            self._hide()
        elif not fits and not self._visible:
            self._visible = True
            self._show()
        if self._visible:
            self._draw()

    def _hide(self):
        """winfo_manager() reports whichever manager owns the widget, so the
        same scrollbar works in a grid-based dialog and a pack-based one.

        Which one it was is remembered, because once the widget is removed
        that information is gone - and getting it wrong on the way back means
        calling grid() inside a pack-managed frame, which Tk refuses.
        """
        manager = self.winfo_manager()
        if manager == "pack":
            info = dict(self.pack_info())
            if "in" in info:                 # pack() spells this one in_
                info["in_"] = info.pop("in")
            self._pack_info = info
            self._manager = "pack"
            self.pack_forget()
        elif manager == "grid":
            self._manager = "grid"
            self.grid_remove()
        else:
            self._manager = None

    def _show(self):
        if self._manager == "grid":
            self.grid()
            return
        if self._manager is None:
            return          # never placed - nothing to restore
        if getattr(self, "_pack_info", None) is not None:
            try:
                self.pack(**self._pack_info)
            except tk.TclError:
                self.pack(**{k: v for k, v in self._pack_info.items()
                             if k not in ("in_", "after", "before")})
        else:
            self.grid()

    def _draw(self):
        self.delete("all")
        span = self._span()
        if span < 4:
            return
        t = self.THICKNESS
        pad = 2
        if self.orient == "vertical":
            self._pill(pad, pad, t - pad, span - pad, BG_INPUT)
        else:
            self._pill(pad, pad, span - pad, t - pad, BG_INPUT)
        lo = int(self._first * span)
        hi = max(int(self._last * span), lo + 16)
        if self.orient == "vertical":
            self._pill(pad, lo + pad, t - pad, min(hi, span) - pad, BORDER_LIGHT)
        else:
            self._pill(lo + pad, pad, min(hi, span) - pad, t - pad, BORDER_LIGHT)

    def _pill(self, x1, y1, x2, y2, color):
        r = min((x2 - x1), (y2 - y1)) / 2
        if r <= 0 or x2 <= x1 or y2 <= y1:
            return
        self.create_oval(x1, y1, x1 + 2 * r, y1 + 2 * r, fill=color, outline=color)
        self.create_oval(x2 - 2 * r, y2 - 2 * r, x2, y2, fill=color, outline=color)
        self.create_rectangle(x1 + r if x2 - x1 > y2 - y1 else x1,
                              y1 if x2 - x1 > y2 - y1 else y1 + r,
                              x2 - r if x2 - x1 > y2 - y1 else x2,
                              y2 if x2 - x1 > y2 - y1 else y2 - r,
                              fill=color, outline=color)

    def _fraction(self, event):
        span = max(self._span(), 1)
        pos = event.y if self.orient == "vertical" else event.x
        return max(0.0, min(1.0, pos / span))

    def _on_press(self, event):
        span = max(self._span(), 1)
        pos = event.y if self.orient == "vertical" else event.x
        lo, hi = self._first * span, self._last * span
        if lo <= pos <= hi:
            # Grab the thumb where it was clicked instead of jumping, so the
            # content doesn't leap under the cursor on the first pixel of drag.
            self._drag_origin = (pos - lo) / span
        else:
            self._drag_origin = (self._last - self._first) / 2
            self._scroll_to(self._fraction(event) - self._drag_origin)

    def _on_drag(self, event):
        if self._drag_origin is None:
            return
        self._scroll_to(self._fraction(event) - self._drag_origin)

    def _scroll_to(self, first):
        if not self.command:
            return
        page = self._last - self._first
        first = max(0.0, min(1.0 - page, first))
        self.command("moveto", first)


class WaveformCreatorDialog(tk.Toplevel):
    """Build one cycle twice - by hand or from a file - and morph A to B.

    Two lanes rather than one because a single shape would fill its share of
    the table with the same sound repeated - the morph is what a wavetable is
    for. Leaving B untouched copies A into it, which gives a static block on
    purpose.
    """

    POINTS = WT_DRAW_POINTS

    PRESETS = {
        "Sine":     lambda t: np.sin(2 * np.pi * t),
        "Triangle": lambda t: 2.0 * np.abs(2.0 * ((t + 0.25) % 1.0) - 1.0) - 1.0,
        "Saw":      lambda t: 2.0 * t - 1.0,
        "Square":   lambda t: np.where(t < 0.5, 1.0, -1.0),
        "Flat":     lambda t: np.zeros_like(t),
    }

    def __init__(self, parent, app, entry=None, on_apply=None):
        super().__init__(parent)
        self.app = app
        self.on_apply = on_apply
        self.result = None
        self.title("Waveform Creator")
        style_toplevel(self)
        self.minsize(sc(720), sc(520))

        t = np.arange(self.POINTS) / float(self.POINTS)
        self.lanes = {
            "A": np.array((entry or {}).get("a") or self.PRESETS["Sine"](t), dtype=float),
            "B": np.array((entry or {}).get("b") or self.PRESETS["Saw"](t), dtype=float),
        }
        for k, v in self.lanes.items():
            if v.size != self.POINTS:
                self.lanes[k] = np.interp(t, np.linspace(0, 1, v.size, endpoint=False), v)
        self.active = tk.StringVar(value="A")
        self.name_var = tk.StringVar(value=(entry or {}).get("name") or "Custom")
        self.show_result = tk.BooleanVar(value=True)
        self._last_xy = None
        self._preview_playing = False
        self._loaded_note = None

        head = tk.Frame(self, padx=14, pady=10, bg=BG_DARK)
        head.pack(fill="x")
        name_lbl = tk.Label(head, text="Name:")
        style_label(name_lbl, font=ui_font(9))
        name_lbl.pack(side="left")
        self.name_entry = tk.Entry(head, textvariable=self.name_var, width=18,
                                    bg=BG_INPUT, fg=FG_TEXT, insertbackground=FG_TEXT,
                                    relief="flat", highlightthickness=1,
                                    highlightbackground=BORDER_COLOR,
                                    highlightcolor=ACCENT_BLUE, font=ui_font(10))
        self.name_entry.pack(side="left", padx=(6, 18))
        for lane in ("A", "B"):
            rb = tk.Radiobutton(head, text=f"Shape {lane}", variable=self.active,
                                 value=lane, command=self._redraw)
            style_checkbutton(rb)   # same styling helper the Mode radios use
            rb.pack(side="left", padx=(0, 10))
        cb = tk.Checkbutton(head, text="Show what will actually sound",
                             variable=self.show_result, command=self._redraw)
        style_checkbutton(cb)
        cb.pack(side="left", padx=(12, 0))
        add_tooltip(cb,
                    "Overlays the band-limited result on your line. They differ "
    "wherever the drawing is sharper than a segment can hold - that "
    "difference is what you hear.")

        panel = RoundedPanel(self, title="Cycle", parent_bg=BG_DARK, panel_bg=BG_PANEL,
                             radius=12, title_font=ui_font(9, "bold"),
                             body_padx=10, body_pady=(24, 8))
        panel.pack(fill="both", expand=True, padx=14)
        self.canvas = tk.Canvas(panel.body, bg=WAVE_BG, highlightthickness=0,
                                 height=sc(260), cursor="pencil")
        self.canvas.pack(fill="both", expand=True)
        self.canvas.bind("<Button-1>", self._on_press)
        self.canvas.bind("<B1-Motion>", self._on_drag)
        self.canvas.bind("<ButtonRelease-1>", self._on_release)
        self.canvas.bind("<Configure>", lambda e: self._redraw())

        self.info = tk.Label(panel.body, text="", anchor="w")
        style_label(self.info, bg=BG_PANEL, fg=FG_MUTED, font=ui_font(8))
        self.info.pack(fill="x", pady=(4, 0))

        tools = tk.Frame(self, padx=14, pady=8, bg=BG_DARK)
        tools.pack(fill="x")
        for label in self.PRESETS:
            b = RoundedButton(tools, text=label,
                              command=lambda l=label: self._load_preset(l),
                              bg=BG_INPUT, fg=FG_TEXT, parent_bg=BG_DARK,
                              width=72, height=26, font=ui_font(8))
            b.pack(side="left", padx=2)
            add_tooltip(b, f"Replaces the active shape with a {label.lower()}. "
                           f"Draw over it from there.")
        load_btn = RoundedButton(tools, text="Load\u2026", command=self._load_file,
                                  bg=BTN_PURPLE, fg="#FFFFFF", parent_bg=BG_DARK,
                                  width=72, height=26, font=ui_font(8))
        load_btn.pack(side="left", padx=(10, 2))
        add_tooltip(load_btn,
                    "Loads a single-cycle WAV into the active shape. Only the shape is "
    "taken: rate and bit depth are ignored, pitch comes from the "
    "wavetable's root note. Stereo is mixed down, DC offset removed.")

        smooth_btn = RoundedButton(tools, text="Smooth", command=self._smooth,
                                    bg=BG_INPUT, fg=FG_TEXT, parent_bg=BG_DARK,
                                    width=72, height=26, font=ui_font(8))
        smooth_btn.pack(side="left", padx=(14, 2))
        add_tooltip(smooth_btn, "Rounds off mouse jitter. Repeating it keeps taking harmonics off "
    "the top.")
        copy_btn = RoundedButton(tools, text="A \u2192 B", command=self._copy_lane,
                                  bg=BG_INPUT, fg=FG_TEXT, parent_bg=BG_DARK,
                                  width=72, height=26, font=ui_font(8))
        copy_btn.pack(side="left", padx=2)
        add_tooltip(copy_btn, "Copies the active shape onto the other lane. With both lanes equal "
    "the family is a static block.")
        self.prev_btn = RoundedButton(tools, text="\u25b6", command=self._toggle_preview,
                                       bg=BTN_BLUE, fg="#FFFFFF", parent_bg=BG_DARK,
                                       width=40, height=26, font=ui_font(10, "bold"))
        self.prev_btn.pack(side="right", padx=2)
        add_tooltip(self.prev_btn,
                    "Plays the morph from A to B at the dialog's root note, with the "
    "band limit the table will get.")

        foot = tk.Frame(self, padx=14, pady=10, bg=BG_DARK)
        foot.pack(fill="x")
        if entry:
            # Only when editing something that already exists - the library
            # would otherwise fill up with abandoned experiments and offer no
            # way out.
            self.btn_delete = RoundedButton(foot, text="Delete", command=self._delete,
                                             bg=BTN_RED, fg="#FFFFFF",
                                             parent_bg=BG_DARK, width=110)
            self.btn_delete.pack(side="left")
            add_tooltip(self.btn_delete,
                        "Removes this waveform from the library and the step order. Tables "
    "already built with it keep working - their audio is on the pad, "
    "not here.")
        cancel = RoundedButton(foot, text="Cancel", command=self._cancel, bg=BG_INPUT,
                                fg=FG_TEXT, parent_bg=BG_DARK)
        cancel.pack(side="right", padx=4)
        ok = RoundedButton(foot, text="Use Waveform", command=self._apply,
                            bg=BTN_GREEN, fg="#FFFFFF", parent_bg=BG_DARK, width=150)
        ok.pack(side="right", padx=4)

        self.protocol("WM_DELETE_WINDOW", self._cancel)
        self.transient(parent)
        center_toplevel_on_parent(self, parent)
        self.after(50, self._redraw)
        self._safe_grab()

    def _safe_grab(self):
        try:
            self.grab_set()
        except tk.TclError as _e:
            _swallowed(_e, "WaveformCreatorDialog._safe_grab")

    # ----------------------------------------------------------- drawing
    def _geom(self):
        w = max(2, self.canvas.winfo_width())
        h = max(2, self.canvas.winfo_height())
        return w, h, h / 2.0

    def _x_to_index(self, x):
        w, _h, _m = self._geom()
        return int(min(self.POINTS - 1, max(0, round(x / w * (self.POINTS - 1)))))

    def _y_to_value(self, y):
        # The 6 px is the top/bottom margin the drawing keeps clear. It has
        # to be clamped away from zero: _geom() only guarantees h >= 2, so
        # an unmapped canvas (winfo_height() reports 1 before the window is
        # laid out) gave mid = 1 and a denominator of -5 - which flipped the
        # drawing upside down - and a canvas exactly 12 px tall divided by
        # zero outright.
        _w, h, mid = self._geom()
        span = max(1.0, mid - 6)
        return float(min(1.0, max(-1.0, (mid - y) / span)))

    def _on_press(self, event):
        self._last_xy = (event.x, event.y)
        self._set_point(event.x, event.y)

    def _on_drag(self, event):
        # A fast drag skips pixels, so the span since the last event is filled
        # in - otherwise the drawing gets holes that read as vertical jumps.
        if self._last_xy:
            x0, y0 = self._last_xy
            steps = max(1, int(abs(event.x - x0)))
            for i in range(1, steps + 1):
                f = i / steps
                self._set_point(x0 + (event.x - x0) * f, y0 + (event.y - y0) * f)
        else:
            self._set_point(event.x, event.y)
        self._last_xy = (event.x, event.y)
        self._redraw()

    def _on_release(self, _event=None):
        self._last_xy = None
        self._redraw()

    def _set_point(self, x, y):
        self.lanes[self.active.get()][self._x_to_index(x)] = self._y_to_value(y)
        self._loaded_note = None    # edited by hand, no longer the file as loaded

    def _load_preset(self, label):
        t = np.arange(self.POINTS) / float(self.POINTS)
        self.lanes[self.active.get()] = np.asarray(self.PRESETS[label](t), dtype=float)
        self._loaded_note = None
        self._redraw()

    def _load_file(self):
        cfg = getattr(self.app, "_wt_last_config", None) or {}
        try:
            hz = midi_to_hz(name_to_midi(cfg.get("note", "C2")))
        except Exception:
            hz = 65.41
        # Auditioned at the wavetable's own root note, so what you hear in the
        # browser is the pitch the table will be built at.
        start_dir = (load_last_cycle_dir()
                     or getattr(self.app, "import_root", None))
        browser = AudioPreviewDialog(self, initial_dir=start_dir, cycle_hz=hz)
        self.wait_window(browser)
        # Remembered even when the browser was cancelled - you were browsing
        # there, and coming back to the top of the tree helps nobody.
        try:
            if browser.current_dir and os.path.isdir(browser.current_dir):
                save_last_cycle_dir(browser.current_dir)
        except Exception as _e:
            _swallowed(_e, "WaveformCreatorDialog._load_file")
        # The browser took the grab; without taking it back this dialog stops
        # being modal and clicks fall through to the one behind it.
        self._safe_grab()
        path = browser.selected_path
        if not path:
            return
        try:
            pts, info = wt_load_cycle_file(path, self.POINTS)
        except Exception as e:
            dark_showerror("Load Waveform",
                           f"Could not read this file as a waveform cycle:\n{e}",
                           parent=self)
            return
        if info["long"]:
            # A single cycle is a few hundred frames. Anything this long is a
            # normal sample, and squeezing it into one cycle turns it into a
            # dense inharmonic buzz rather than a waveform.
            keep_hz = (info["rate"] or WT_SR) / float(info["frames"]) \
                * (WT_DRAW_POINTS // 2)
            if not dark_askyesno(
                    "Not a Single Cycle?",
                    f"This file is {info['frames']} frames long. A single-cycle "
                    f"waveform is usually a few hundred.\n\n"
                    f"The whole file becomes one cycle, so only its lowest "
                    f"{WT_DRAW_POINTS // 2} harmonics survive - everything above "
                    f"about {keep_hz:.0f} Hz in this file is discarded. What is "
                    f"left is roughly its loudness contour, not its sound.\n\n"
                    f"Load it anyway?", parent=self):
                return
        self.lanes[self.active.get()] = np.asarray(pts, dtype=float)
        self._loaded_note = (
            f"{os.path.basename(path)}  \u00b7  {info['frames']} frames "
            f"@ {info['rate']} Hz  \u00b7  {info['harmonics']} harmonics")
        self._redraw()

    def _smooth(self):
        v = self.lanes[self.active.get()]
        # Wrap-around kernel: the cycle is a loop, so the last point's
        # neighbour is the first one.
        self.lanes[self.active.get()] = (np.roll(v, 1) + 2.0 * v + np.roll(v, -1)) / 4.0
        self._redraw()

    def _copy_lane(self):
        src = self.active.get()
        dst = "B" if src == "A" else "A"
        self.lanes[dst] = self.lanes[src].copy()
        self._redraw()

    def _band_limited(self, values):
        """One cycle as the segment will hold it, at the current settings.

        Deliberately one cycle, not one segment. A segment holds R of them -
        two in the Mid and Lead registers - so rendering the whole segment
        drew two waves on top of a drawing that shows one, at the same width.
        The band limit is what matters here, and it is identical either way.
        """
        cfg = getattr(self.app, "_wt_last_config", None) or {}
        midi = name_to_midi(cfg.get("note", "C2"))
        cycles = max(1, int(cfg.get("cycles", 1)))
        up = int(cfg.get("up", 0))
        try:
            L, _f, _c = wt_tuning_info(midi, cycles)
            h, _hm = wt_harmonics_for(L, cycles, up)
        except Exception:
            L, h, cycles = 674, 337, 1
        one = max(16, L // cycles)
        s = WTSynth(one, 1, max(1, min(h, one // 2)))
        return wt_points_to_cycle(values, s), h, min(h, self.POINTS // 2)

    def _redraw(self):
        c = self.canvas
        c.delete("all")
        w, h, mid = self._geom()
        grid = blend_colors(WAVE_BG, FG_MUTED, 0.25)
        for frac in (0.25, 0.5, 0.75):
            c.create_line(w * frac, 0, w * frac, h, fill=grid, dash=(2, 4))
        c.create_line(0, mid, w, mid, fill=blend_colors(WAVE_BG, FG_MUTED, 0.45))

        vals = self.lanes[self.active.get()]
        other = self.lanes["B" if self.active.get() == "A" else "A"]
        span = mid - 6

        def poly(values, color, width, dash=None):
            pts = []
            for i, v in enumerate(values):
                pts += [i / (len(values) - 1) * w, mid - v * span]
            kw = dict(fill=color, width=width, smooth=False)
            if dash:
                kw["dash"] = dash
            c.create_line(*pts, **kw)

        poly(other, blend_colors(WAVE_BG, FG_MUTED, 0.55), 1, dash=(3, 3))
        poly(vals, readable_on(WAVE_COLOR, WAVE_BG, 7.0), 2)

        usable = min(self.POINTS // 2, 1)
        if self.show_result.get():
            band, h_avail, usable = self._band_limited(vals)
            step = max(1, len(band) // 600)
            poly(band[::step], ACCENT_ORANGE, 1)
            self.info.config(
                text=f"Shape {self.active.get()}  \u00b7  drawn with {self.POINTS} points "
                     f"\u2192 {usable} harmonics usable  \u00b7  the segment allows "
                     f"{h_avail}  \u00b7  orange is what will sound")
        else:
            self.info.config(text=f"Shape {self.active.get()}  \u00b7  dashed line is the "
                                  f"other shape  \u00b7  the family morphs A \u2192 B")
        note = getattr(self, "_loaded_note", None)
        if note:
            self.info.config(text=self.info.cget("text") + "\n" + note)

    # ----------------------------------------------------------- preview
    def _toggle_preview(self):
        if self._preview_playing:
            self._stop_preview()
            return
        try:
            cfg = getattr(self.app, "_wt_last_config", None) or {}
            midi = name_to_midi(cfg.get("note", "C2"))
            audio = wt_render_sweep(self._entry(), midi, int(cfg.get("cycles", 1)),
                                    int(cfg.get("up", 0)), 24)
            sd.play(audio, WT_SR)
        except Exception as e:
            dark_showerror("Preview", f"Could not play the sweep:\n{e}", parent=self)
            return
        self._preview_playing = True
        self.prev_btn.text = "\u25a0"
        self.prev_btn._draw()
        self.after(int(WT_PREVIEW_SECONDS * 1000) + 100, self._stop_preview)

    def _stop_preview(self):
        if not self._preview_playing:
            return
        self._preview_playing = False
        try:
            sd.stop()
        except Exception as _e:
            _swallowed(_e, "WaveformCreatorDialog._stop_preview")
        try:
            self.prev_btn.text = "\u25b6"
            self.prev_btn._draw()
        except tk.TclError as _e:
            _swallowed(_e, "WaveformCreatorDialog._stop_preview")

    # ----------------------------------------------------------- result
    def _entry(self):
        return {"kind": "draw",
                "name": self.name_var.get().strip() or "Custom",
                # Rounded on the way out: a preset folder is meant to be
                # swapped around, and full float repr would triple its size
                # for precision no ear can use.
                "a": [round(float(v), 4) for v in self.lanes["A"]],
                "b": [round(float(v), 4) for v in self.lanes["B"]]}

    def _apply(self):
        self._stop_preview()
        self.result = self._entry()
        if self.on_apply:
            self.on_apply(self.result)
        self.destroy()

    def _delete(self):
        name = self.name_var.get().strip() or "Custom"
        if not dark_askyesno("Delete Waveform",
                             f"Remove \"{name}\" from the saved waveforms?\n\n"
                             "Wavetables already built with it are not affected.",
                             parent=self):
            return
        self._stop_preview()
        self.result = {"delete": name}
        if self.on_apply:
            self.on_apply(self.result)
        self.destroy()

    def _cancel(self):
        self._stop_preview()
        self.result = None
        self.destroy()


class SynthDialog(tk.Toplevel):
    """The wavetable builder, themed to match the main window.

    Bank and pad come from the calling pad, so there is no bank/pad picker
    here; the init patch and poly switch live on the pad itself. Everything
    else from the standalone tool is present."""

    def __init__(self, parent, app, bank, pad, initial_config=None):
        super().__init__(parent)
        style_toplevel(self)
        self.title(f"Synth  \u2014  Bank {bank}  Pad {pad}")
        self.app = app
        # bank/pad are only used for the window title above. The PRM is
        # written by the pad itself, from wherever it sits at that moment -
        # keeping copies here would invite writing a stale PHRASE.
        self.result = None
        self.prev_family = None
        self.prev_playing = False
        self.transient(parent)
        self.resizable(True, True)

        cfg = dict(initial_config or {})
        self.var_mode = tk.StringVar(value=cfg.get("mode", "Simple"))
        # Which sixteen Simple builds from. Saved with the pad, so reopening
        # a wavetable shows the set it was actually made from.
        # One set at a time. A shared StringVar with a per-box onvalue gives
        # tick boxes that behave like radio buttons: ticking one clears the
        # others, with no code to keep them in step.
        self.var_set = tk.StringVar(value=cfg.get("simple_set") or "Basic")
        self.var_reg = tk.StringVar(value=cfg.get("register", "Bass"))
        self.var_note = tk.StringVar(value=cfg.get("note", "C2"))
        self.var_up = tk.IntVar(
            value=max(0, min(WT_DEVICE_MAX_UP, int(cfg.get("up", 0)))))
        self.var_save_map = tk.BooleanVar(value=bool(cfg.get("save_map", False)))
        self.var_autoplay = tk.BooleanVar(value=load_default_autoplay())
        # The two listboxes keep holding plain names; the drawn shapes live
        # here and are looked up by name. Putting dicts into a Listbox would
        # have meant rewriting every selection, reorder and duplicate check.
        #
        # Starts from the saved library, then this pad's own shapes are laid
        # over it. The pad wins on a name clash: its table was built from
        # that exact shape, and a same-named entry in the library would
        # otherwise silently change what a rebuild produces.
        self.custom = load_drawn_library()
        # Packs dropped into ~/.pyp6/user_wave_families since last time.
        # Read before anything is drawn, so a folder copied in from
        # elsewhere is simply there when the dialog opens.
        added, new_groups = import_new_user_family_packs(self.custom)
        self._imported_note = (f"{added} waveforms found in "
                                f"{', '.join(new_groups)}" if added else "")
        if added:
            save_drawn_library({n: e for n, e in self.custom.items()
                                if wt_entry_is_usable(e)})
        for entry in (cfg.get("custom") or []):
            nm = entry.get("name")
            if nm:
                self.custom[nm] = entry

        self._build()
        base = WT_REGISTERS[self.var_reg.get()][0]
        self.dd_note.values = [midi_to_name(base + o) for o in range(-6, 7)]
        if cfg.get("families"):
            dropped, over_limit = [], []
            for name in cfg["families"]:
                # Through the alias map first, so a pad saved before the
                # collections were renamed still restores its step order
                # instead of reporting every entry as missing.
                name = wt_canonical_family(name)
                # Drawn families are not in WT_FAMILY_MAP - they live in
                # self.custom, restored from the config a few lines above.
                if not (name in WT_FAMILY_MAP or name in self.custom):
                    dropped.append(name)
                elif self.lb_sel.size() >= WT_MAX_SELECTED:
                    over_limit.append(name)
                else:
                    self.lb_sel.insert("end", name)
            if over_limit:
                dropped.extend(over_limit)
            if dropped:
                # Silently shortening the step order would change the table
                # on the next build without the user noticing.
                self.after(60, lambda d=list(dropped), o=list(over_limit):
                           dark_showwarning(
                    "Step Order Shortened",
                    "This pad's wavetable used families that could not all be "
                    "restored:\n\n" + "\n".join(f"\u2022 {n}" for n in d) +
                    (f"\n\nThe step order is limited to {WT_MAX_SELECTED} "
                     f"families." if o else "") +
                    "\n\nThey have been left out of the step order. Rebuilding "
                    "now would produce a different table.", parent=self))
        self._apply_mode(restore=bool(cfg))
        if self._imported_note:
            # Only when something actually arrived - a message about an
            # empty folder every time the dialog opens is noise.
            self._status(self._imported_note, "good")
        # Top edge lined up with the main window, not centred on it. This
        # window changes height when the mode is switched, and Advanced is
        # much taller than Simple - centred, it opened low enough that
        # growing downward ran off the bottom of smaller displays.
        center_toplevel_on_parent(self, parent, align="top")
        self.protocol("WM_DELETE_WINDOW", self._cancel)
        self.grab_set()

    # -- layout ------------------------------------------------------------

    def _scrolled_tree(self, parent, title):
        """A Treeview in a RoundedPanel, for the grouped Available list.

        A Listbox is flat by construction, so grouping the families into
        folders needs a different widget. Only the LEFT list changes: the
        step order is an ordered sequence of at most sixteen entries with
        no hierarchy in it, and a tree there would add machinery for
        nothing.
        """
        panel = RoundedPanel(parent, title=title, parent_bg=parent.cget("bg"),
                             panel_bg=BG_PANEL, radius=12,
                             title_font=ui_font(9, "bold"),
                             body_padx=14, body_pady=(24, 8))
        # The Dark.Treeview style is set up lazily by whichever dialog
        # needs it first, and until it exists a Treeview renders with ttk's
        # default WHITE field. The two file browsers already call this; the
        # Synth dialog used the style without ever asking for it, so the
        # list was white until some other window happened to build it.
        ensure_dark_treeview_style()
        box = tk.Frame(panel.body, bg=BG_PANEL)
        box.rowconfigure(0, weight=1)
        box.columnconfigure(0, weight=1)
        tv = ttk.Treeview(box, show="tree", selectmode="extended",
                          height=11, style="Dark.Treeview")
        # A small requested width on purpose. uniform= on the grid columns
        # makes them share the space evenly, but Tk never shrinks a column
        # below what its content asks for - and a Treeview's default #0
        # column asks for far more than a Listbox does, so the two panels
        # stayed different widths. With both asking for almost nothing, the
        # grid alone decides, and stretch=True lets the column fill whatever
        # it is given.
        tv.column("#0", width=sc(120), stretch=True)
        tv.grid(row=0, column=0, sticky="nsew")
        vs = RoundedScrollbar(box, orient="vertical", command=tv.yview,
                              parent_bg=BG_PANEL)
        vs.grid(row=0, column=1, sticky="ns", padx=(3, 0))
        hs = RoundedScrollbar(box, orient="horizontal", command=tv.xview,
                              parent_bg=BG_PANEL)
        hs.grid(row=1, column=0, sticky="ew", pady=(3, 0))
        tv.configure(yscrollcommand=vs.set, xscrollcommand=hs.set)

        def wheel(event):
            if getattr(event, "num", None) == 4:
                tv.yview_scroll(-1, "units")
            elif getattr(event, "num", None) == 5:
                tv.yview_scroll(1, "units")
            else:
                tv.yview_scroll(-1 if event.delta > 0 else 1, "units")
            return "break"

        for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
            tv.bind(seq, wheel)
        # A family that is already in the step order is dimmed, as it was in
        # the listbox version.
        # Tags carry the three states. The style map above is cleaned so
        # these are not overridden - see _clean() in the style setup - and
        # the widget's own foreground is FG_TEXT, so even a Tk that ignored
        # tags outright would leave the names readable rather than grey.
        tv.tag_configure("used", foreground=FG_MUTED)
        tv.tag_configure("family", foreground=FG_TEXT)
        tv.tag_configure("group", foreground=ACCENT_BLUE)
        box.pack(fill="both", expand=True)
        # Missing here until now - every other list in the app gets this,
        # the blue outline that shows which side a click last landed on.
        add_focus_border(tv, box)
        return panel, tv

    # -- the Available tree, as the rest of the dialog sees it -------------
    # Four small accessors so that everything else can keep asking "which
    # names are selected" instead of knowing about item ids, group nodes and
    # tags. Group rows are selectable in Tk and must never be mistaken for
    # a family, which is what these exist to guarantee.

    def _avail_is_family(self, iid):
        return bool(iid) and not iid.startswith((WT_GROUP_IID, WT_USER_GROUP_IID))

    def _avail_open_only(self, keep_iid):
        """Closes every top-level folder except `keep_iid`.

        Called both from the user opening one by hand and from anything
        that opens one programmatically (e.g. landing on the folder a bulk
        import just filled), so the "only one at a time" rule holds no
        matter how the folder got opened.
        """
        if not keep_iid or not keep_iid.startswith((WT_GROUP_IID,
                                                    WT_USER_GROUP_IID)):
            return
        for iid in self.lb_avail.get_children(""):
            if iid != keep_iid and self.lb_avail.item(iid, "open"):
                self.lb_avail.item(iid, open=False)
        # after_idle, not now: <<TreeviewOpen>> fires BEFORE the children
        # are laid out, and closing the other folders above moves every row
        # again. Scrolling against that geometry aims at where the folder
        # used to be.
        self.lb_avail.after_idle(lambda: self._avail_scroll_to_top(keep_iid))

    def _avail_scroll_to_top(self, iid):
        """Brings `iid` to the top of the visible area.

        see() only guarantees a row is somewhere on screen, which for a
        folder just expanded near the bottom means its header sits at the
        very bottom with all of its contents below the fold - the one thing
        that is not wanted after opening it.

        Seeing the LAST child first scrolls the view down past the whole
        folder; seeing the header then scrolls back up by the smallest
        amount that reveals it, which lands it at the top whenever the
        contents are taller than the viewport. Where they are not, nothing
        needs scrolling and see() leaves the view alone.
        """
        try:
            if not self.lb_avail.exists(iid):
                return
            kids = self.lb_avail.get_children(iid)
            if kids:
                self.lb_avail.see(kids[-1])
            self.lb_avail.see(iid)
        except tk.TclError as _e:
            _swallowed(_e, "SynthDialog._avail_scroll_to_top")

    def _avail_selected_groups(self):
        """Selected folder labels that belong to the user's own groups -
        never a built-in group like Basic, which has nothing to delete."""
        user_groups = set(self._user_groups())
        out = []
        for iid in self.lb_avail.selection():
            # Only the user namespace. Reading the label back out of a
            # shared prefix made a built-in collection selectable for
            # deletion whenever a user folder happened to share its name.
            if iid.startswith(WT_USER_GROUP_IID):
                label = iid[len(WT_USER_GROUP_IID):]
                if label in user_groups:
                    out.append(label)
        return out

    def _avail_selected(self):
        """Selected FAMILY names, in the order they appear in the tree."""
        chosen = set(self.lb_avail.selection())
        out = []
        for grp in self.lb_avail.get_children(""):
            for iid in self.lb_avail.get_children(grp):
                if iid in chosen and self._avail_is_family(iid):
                    out.append(iid)
        return out

    def _avail_first_selected(self):
        names = self._avail_selected()
        return names[0] if names else None

    def _scrolled_list(self, parent, title=None):
        """Returns (outer, listbox). With a title the list is wrapped in a
        RoundedPanel, matching how the Chop dialog frames its two lists."""
        panel = None
        if title is not None:
            panel = RoundedPanel(parent, title=title,
                                 parent_bg=parent.cget("bg"),
                                 panel_bg=BG_PANEL, radius=12,
                                 title_font=ui_font(9, "bold"),
                                 # 14, not 10: the title is drawn at sc(16)
                                 # and a Listbox adds about two pixels of its
                                 # own before the first glyph, so this puts
                                 # the entries flush under the heading
                                 # instead of two pixels to its left.
                                 body_padx=14, body_pady=(24, 8))
            parent = panel.body
        box = tk.Frame(parent, bg=BG_PANEL)
        box.rowconfigure(0, weight=1)
        box.columnconfigure(0, weight=1)
        # width in CHARACTERS, and deliberately tiny - see the Treeview in
        # _scrolled_tree() for why both sides have to ask for almost nothing.
        lb = tk.Listbox(box, selectmode="extended", exportselection=False,
                        height=11, width=1, activestyle="none")
        style_listbox(lb)
        lb.grid(row=0, column=0, sticky="nsew")

        # style_listbox's highlightcolor should already turn this blue on
        # focus, natively - but relying on that alone was inconsistent
        # next to the Available tree's border (fixed with an explicit
        # Button-1 binding, since native FocusIn wasn't reliable there
        # either). Forcing it here the same way keeps both sides governed
        # by the same mechanism instead of one native and one manual.
        def _lb_focus_on(_e=None):
            lb.configure(highlightbackground=ACCENT_BLUE, highlightcolor=ACCENT_BLUE)

        def _lb_focus_off(_e=None):
            lb.configure(highlightbackground=BORDER_COLOR, highlightcolor=BORDER_COLOR)

        lb.bind("<FocusIn>", _lb_focus_on, add="+")
        lb.bind("<FocusOut>", _lb_focus_off, add="+")
        lb.bind("<Button-1>", _lb_focus_on, add="+")
        vs = RoundedScrollbar(box, orient="vertical", command=lb.yview,
                              parent_bg=BG_PANEL)
        vs.grid(row=0, column=1, sticky="ns", padx=(3, 0))
        hs = RoundedScrollbar(box, orient="horizontal", command=lb.xview,
                              parent_bg=BG_PANEL)
        hs.grid(row=1, column=0, sticky="ew", pady=(3, 0))
        lb.configure(yscrollcommand=vs.set, xscrollcommand=hs.set)

        def wheel(event):
            if getattr(event, "num", None) == 4:
                lb.yview_scroll(-1, "units")
            elif getattr(event, "num", None) == 5:
                lb.yview_scroll(1, "units")
            else:
                lb.yview_scroll(-1 if event.delta > 0 else 1, "units")
            return "break"

        for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
            lb.bind(seq, wheel)
        if panel is not None:
            box.pack(fill="both", expand=True)
            return panel, lb
        return box, lb

    def _build(self):
        # pady=6, not 14: the footer carries its own top padding and the
        # status line below it another, so a full 14 at the bottom sat
        # under two paddings doing the same job. The top gets its 14 back
        # from the mode bar - a widget OPTION takes one value, only pack()
        # and grid() accept a (top, bottom) pair.
        root = tk.Frame(self, bg=BG_DARK, padx=14, pady=6)
        root.pack(fill="both", expand=True)

        modebar = tk.Frame(root, bg=BG_DARK)
        modebar.pack(fill="x", pady=(8, 10))
        lbl = tk.Label(modebar, text="Mode")
        style_label(lbl, font=ui_font(9, "bold"))
        lbl.pack(side="left")
        for txt in ("Simple", "Advanced"):
            rb = tk.Radiobutton(modebar, text=txt, value=txt, variable=self.var_mode,
                                command=self._apply_mode)
            style_checkbutton(rb)
            rb.pack(side="left", padx=(10, 0))
        self.lbl_mode_hint = tk.Label(modebar, text="")
        style_label(self.lbl_mode_hint, fg=FG_MUTED, font=ui_font(8))
        self.lbl_mode_hint.pack(side="left", padx=(16, 0))
        add_tooltip(modebar,
                    "Simple builds from one ready-made set: a collection, a random "
                    "mix, or a single multi family that fills the table on its own. "
                    "Advanced lets you pick the families one by one, your own drawn "
                    "shapes included. Root note and playing range work the same in "
                    "both.")

        # --- pitch ---
        pitch_panel = RoundedPanel(root, title="PITCH", parent_bg=BG_DARK,
                                   title_fg=ACCENT_BLUE)
        pitch_panel.pack(fill="x")
        pf = pitch_panel.body

        row = tk.Frame(pf, bg=BG_PANEL)
        row.pack(fill="x")
        l1 = tk.Label(row, text="Register")
        style_label(l1, bg=BG_PANEL, font=ui_font(9))
        l1.pack(side="left")
        dd = RoundedDropdown(row, self.var_reg, list(WT_REGISTERS),
                             command=lambda _v=None: self._on_register(),
                             parent_bg=BG_PANEL, width=90, height=26,
                             font=ui_font(9))
        dd.pack(side="left", padx=(6, 18))
        add_tooltip(dd,
                    "Bass keeps the full harmonics, meant for the root note or below. "
    "Mid and Lead are band limited to stay alias-free one or two "
    "octaves up.")

        self.adv_row = tk.Frame(row, bg=BG_PANEL)
        self.adv_row.pack(side="left")
        self.lbl_note = tk.Label(self.adv_row, text="Root note")
        style_label(self.lbl_note, bg=BG_PANEL, font=ui_font(9))
        self.lbl_note.pack(side="left")
        self.dd_note = RoundedDropdown(self.adv_row, self.var_note, ["C2"],
                                       command=lambda _v=None: self._refresh(),
                                       parent_bg=BG_PANEL, width=70, height=26,
                                       font=ui_font(9))
        self.dd_note.pack(side="left", padx=(6, 18))
        add_tooltip(self.dd_note,
                    "The note the table is tuned to, six semitones either side of the "
    "register default. Baking your key in here plays at 1:1, with no "
    "interpolation loss.")

        self.lbl_up = tk.Label(self.adv_row, text="Plays up to")
        style_label(self.lbl_up, bg=BG_PANEL, font=ui_font(9))
        self.lbl_up.pack(side="left")
        self.sp_up = tk.Spinbox(self.adv_row, from_=0, to=36, width=4, textvariable=self.var_up,
                                command=self._refresh, bg=BG_INPUT, fg=FG_TEXT,
                                buttonbackground=BG_INPUT, relief="flat",
                                highlightthickness=1, highlightbackground=BORDER_COLOR,
                                insertbackground=FG_TEXT, font=ui_font(9))
        self.sp_up.pack(side="left", padx=6)
        self.sp_up.bind("<KeyRelease>", lambda e: self._refresh())
        self.lbl_up_unit = tk.Label(self.adv_row, text="semitones above root")
        style_label(self.lbl_up_unit, bg=BG_PANEL, fg=FG_MUTED, font=ui_font(8))
        self.lbl_up_unit.pack(side="left")
        add_tooltip(self.sp_up,
                    "How far above the root note you intend to play. Aliasing only "
    "happens transposing up, so this sets the band limit: harmonics = "
    "max / 2^(semitones/12).")

        # On the pitch row itself, not on a line of its own below it. The
        # harmonic count is a consequence of the register, the root note and
        # the range - all three sit in this row - so it belongs beside them,
        # and the panel loses a line it was only using for one short string.
        self.lbl_info = tk.Label(row, text="", anchor="w")
        style_label(self.lbl_info, bg=BG_PANEL, fg=FG_MUTED, font=ui_font(8))
        self.lbl_info.pack(side="left", padx=(16, 0))
        add_tooltip(self.lbl_info,
                    "Two ceilings, and the lower one is shown. The table's own is "
    "the band limit: its top harmonic already sits just under Nyquist at the "
    "root, so every semitone up moves it past - fewer harmonics buy height, "
    "which is the trade Register and \"Plays up to\" make. The P-6's own is a "
    "flat three octaves above the sample's own pitch, and no setting here "
    "moves it - on the device, transposing up spends that budget rather "
    "than shifting it. Downwards neither limit applies.")

        # --- wavetable ---
        # No panel around this section: each list carries its own frame, and a
        # box drawn around both of them just competed with those two.
        # Simple mode's source sets, in a panel of their own under PITCH.
        # Check boxes rather than a dropdown: several may be combined, and a
        # dropdown cannot say "these two".
        self.sets_panel = RoundedPanel(root, title="WAVEFORMS", parent_bg=BG_DARK,
                                        title_fg=ACCENT_BLUE)
        sf = self.sets_panel.body
        sets_row = tk.Frame(sf, bg=BG_PANEL)
        sets_row.pack(fill="both", expand=True)
        # The boxes in a column of their own, so the width they do not use is
        # left over for the card beside them rather than spread across the
        # whole panel.
        sets_col = tk.Frame(sets_row, bg=BG_PANEL)
        sets_col.pack(side="left", anchor="n")
        labels = [lbl for lbl, _n in self.simple_sets()] + ["Randomize"]
        if self.var_set.get() not in labels:
            self.var_set.set(labels[0])
        for label in labels:
            cb = tk.Checkbutton(sets_col, text=label, variable=self.var_set,
                                 onvalue=label, offvalue="",
                                 command=self._on_simple_set)
            style_checkbutton(cb)
            cb.config(bg=BG_PANEL, activebackground=BG_PANEL)
            cb.pack(anchor="w", pady=(3, 3))
            if label == "Randomize":
                add_tooltip(cb,
                            "Sixteen morphing families picked at random from every "
                            "collection. Multi families are left out - each needs the "
                            "whole table to itself. Rolled fresh every time this is "
                            "selected.")
        # The description card. BG_INPUT rather than BG_PANEL so it reads as
        # a card sitting ON the panel instead of another region of it, and no
        # title of its own - the heading inside IS the title, and it changes
        # with the selection.
        self.blurb_card = RoundedPanel(sets_row, title="", parent_bg=BG_PANEL,
                                       panel_bg=BG_INPUT, border=BORDER_COLOR,
                                       radius=10, body_padx=16,
                                       body_pady=(14, 14))
        self.blurb_card.pack(side="left", fill="both", expand=True,
                             padx=(20, 0))
        self.lbl_blurb_title = tk.Label(self.blurb_card.body, text="",
                                        anchor="w", justify="left")
        style_label(self.lbl_blurb_title, bg=BG_INPUT, fg=ACCENT_BLUE,
                    font=ui_font(11, "bold"))
        self.lbl_blurb_title.pack(anchor="w")
        self.lbl_blurb_meta = tk.Label(self.blurb_card.body, text="",
                                       anchor="w", justify="left")
        style_label(self.lbl_blurb_meta, bg=BG_INPUT, fg=ACCENT_ORANGE,
                    font=ui_font(8, "bold"))
        self.lbl_blurb_meta.pack(anchor="w", pady=(1, 8))
        # wraplength in pixels, reset on every resize: a fixed value would be
        # wrong at any UI scale but the one it was measured at, and wrong
        # again as soon as the window is widened.
        self.lbl_blurb_text = tk.Label(self.blurb_card.body, text="",
                                       anchor="nw", justify="left",
                                       wraplength=sc(320))
        style_label(self.lbl_blurb_text, bg=BG_INPUT, fg=FG_TEXT,
                    font=ui_font(9))
        self.lbl_blurb_text.pack(anchor="nw", fill="both", expand=True)
        self.blurb_card.body.bind(
            "<Configure>",
            lambda e: self.lbl_blurb_text.config(
                wraplength=max(sc(180), e.width - sc(8))), add="+")


        self.wt_panel = tk.Frame(root, bg=BG_DARK)
        self.wt_panel.pack(fill="both", expand=True, pady=(12, 0))
        wf = self.wt_panel
        # uniform=: weight alone only splits the LEFTOVER width, so the two
        # panels kept the difference between what a Treeview asks for and
        # what a Listbox asks for. In one uniform group they are forced to
        # the same width whatever their contents want.
        wf.columnconfigure(0, weight=1, uniform="lists")
        wf.columnconfigure(2, weight=1, uniform="lists")
        wf.rowconfigure(1, weight=1)

        box_a, self.lb_avail = self._scrolled_tree(wf, title="Available")
        box_a.grid(row=1, column=0, sticky="nsew")
        self._fill_available()
        # Double-click moves a built-in across, but reopens a drawing for
        # editing - there is no other way back into a shape you made.
        self.lb_avail.bind("<Double-Button-1>", self._on_avail_double)
        # Both run on every selection change: one previews, the others keep
        # the two state-carrying buttons honest about what is picked.
        def on_avail_select(_e):
            self._pick_preview(self.lb_avail)
            self._sync_delete_button()
    
        self.lb_avail.bind("<<TreeviewSelect>>", on_avail_select)
        # Only one folder open at a time: opening a second one used to leave
        # the first still expanded below it, so the list kept growing until
        # everything below Basic was buried in scrolling rather than picking.
        def on_avail_open(_e):
            self._avail_open_only(self.lb_avail.focus())
        self.lb_avail.bind("<<TreeviewOpen>>", on_avail_open)

        col = tk.Frame(wf, bg=BG_DARK)
        col.grid(row=1, column=1, padx=8)
        # Clearing everything lives in the footer next to Apply/Cancel, the
        # same place the Chop dialog puts Clear Selection. An arrow glyph in
        # this column would have been one more thing to decode.
        for txt, cmd, tip in (
                ("\u2192", self._move_right, "Moves the highlighted families into the step order."),
                ("\u2190", self._move_left, "Takes the highlighted families back out."),
                ("\u25b2", lambda: self._reorder(-1), "Moves the highlighted families one place earlier."),
                ("\u25bc", lambda: self._reorder(1), "Moves the highlighted families one place later.")):
            b = RoundedButton(col, text=txt, command=cmd, bg=BG_INPUT, fg=FG_TEXT,
                              parent_bg=BG_DARK, width=40, height=26,
                              font=ui_font(10, "bold"))
            b.pack(pady=3)
            add_tooltip(b, tip)

        # Between the two lists, since it previews the family highlighted in
        # either one. Glyph only: the family name would have set the width of
        # the whole column, and it changes with every click.
        self.btn_prev = RoundedButton(col, text="\u25b6", command=self._toggle_preview,
                                      bg=BTN_BLUE, fg="#FFFFFF", parent_bg=BG_DARK,
                                      width=40, height=26, state="disabled",
                                      font=ui_font(10, "bold"))
        self.btn_prev.pack(pady=(14, 3))
        add_tooltip(self.btn_prev,
                    "Sweeps through the family highlighted in either column, at the "
    "configured root note and the table's band limit.")

        self.btn_draw = RoundedButton(col, text="\u270e", command=self._open_draw,
                                      bg=BG_INPUT, fg=FG_TEXT, parent_bg=BG_DARK,
                                      width=40, height=26, font=ui_font(11, "bold"))
        self.btn_draw.pack(pady=(14, 3))
        add_tooltip(self.btn_draw,
                    "Opens the Waveform Creator: draw a waveform or load a single-cycle "
    "file, and it joins the list as its own family of two shapes "
    "morphing into each other. Double-click one of yours to edit it.")

        self.btn_imp = RoundedButton(col, text="\u2b73", command=self._import_cycles,
                                     bg=BG_INPUT, fg=FG_TEXT, parent_bg=BG_DARK,
                                     width=40, height=26, font=ui_font(11, "bold"))
        self.btn_imp.pack(pady=3)
        add_tooltip(self.btn_imp,
                    "Imports a folder of single-cycle files at once, in natural "
                    "order (MG2 before MG10). Mode decides how they are combined."
                    "\n\nA file holding a whole wavetable is recognised and split "
                    "into its waveforms, one row each.")

        # Red only while a drawn family is highlighted. The built-in sixteen
        # cannot be deleted, so an always-red button would promise something
        # it refuses to do most of the time.
        self.btn_del = RoundedButton(col, text="\u2715", command=self._delete_custom,
                                     bg=BTN_RED, fg="#FFFFFF", parent_bg=BG_DARK,
                                     width=40, height=26, font=ui_font(11, "bold"),
                                     state="disabled")
        self.btn_del.pack(pady=3)
        add_tooltip(self.btn_del,
                    "Deletes the highlighted hand-drawn waveform from the list, the "
    "step order and the library. Built-in families stay. Select a "
    "folder header to delete it and its contents; wavetables already "
    "built keep working.")


        # The panel holding the step order carries the count in its own
        # heading. It is a fact ABOUT that list, so it belongs on it - and
        # in the heading it needs no separate line and no separate font.
        self.sel_panel, self.lb_sel = self._scrolled_list(wf, title="Step Order")
        box_s = self.sel_panel
        box_s.grid(row=1, column=2, sticky="nsew")
        self.lb_sel.bind("<Double-Button-1>", lambda e: self._move_left())
        self.lb_sel.bind("<<ListboxSelect>>",
                         lambda e: self._pick_preview(self.lb_sel))
        # Drag a family straight across instead of selecting it and then
        # reaching for the arrow button - the arrow is still there for
        # anyone who'd rather click it.
        add_tooltip(self.lb_sel,
                    "The step order - the families the table is built from, in "
                    "order. Drag rows up and down to reorder, in from the left to "
                    "add, back out to remove.")
        enable_drag_transfer(self.lb_avail, self.lb_sel, self._move_right)
        # And the other way: drag out of the step order to take it back
        # out, same as the "<-" button.
        enable_drag_transfer(self.lb_sel, self.lb_avail, self._move_left)
        enable_drag_reorder(self.lb_sel, self._sel_drop)

        # The same strip the main window draws under the pads, rather than
        # the families listed side by side as "Saw: 16   Sine: 16   ...".
        # That list said the same thing in a form nobody reads left to
        # right, and it could not show where a family SITS in the START
        # range - which is the question you have while arranging them.
        # Just the strip now - the count moved to the Step Order heading, so
        # the extra line this box used to reserve for it can go.
        # In `root`, not in wt_panel: Simple hides that whole frame, and the
        # strip has to be visible in both modes. Packed by _apply_mode so it
        # always lands in the right place relative to what is showing.
        # No slack: the canvas inside fills it exactly. The extra ten pixels
        # were left over from when a caption line lived here, and that moved
        # to the Step Order heading.
        alloc_box = tk.Frame(root, bg=BG_DARK, height=sc(MAIN_WAVE_H))
        alloc_box.pack_propagate(False)
        self.alloc_box = alloc_box
        # A RoundedPanel, not a plain frame: every other box in this dialog
        # has rounded corners, and a square one under them looks like a
        # widget that was forgotten rather than a deliberate difference.
        # One canvas, no panel around it. The rounding is done by painting
        # over the four corners after the strip is drawn - see
        # round_canvas_corners() for why nesting cannot work here.
        self.zone_canvas = tk.Canvas(alloc_box, bg=WAVE_BG,
                                      height=sc(MAIN_WAVE_H),
                                      highlightthickness=0, bd=0,
                                      cursor="hand2")
        self.zone_canvas.pack(fill="both", expand=True)
        self.zone_canvas.bind("<Configure>", lambda e: self._draw_zones())
        # Click a zone, hear and see that family - the same "pick one, get
        # a preview" the Available list already offers in Advanced, and in
        # Simple mode the only way to get one at all, since there is no
        # list there to click in.
        self.zone_canvas.bind("<Button-1>", self._on_zone_canvas_click)

        # In root, like the zone strip: the strip has to sit BETWEEN the
        # lists and the morph, and it cannot do that from outside wt_panel
        # while the morph is still inside it.
        morph_panel = RoundedPanel(root, title="Morph", parent_bg=BG_DARK,
                                   panel_bg=BG_PANEL, radius=12,
                                   title_font=ui_font(9, "bold"),
                                   body_padx=10, body_pady=(24, 8))
        self.morph_panel = morph_panel
        # On the panel's own title line, opposite "Morph". It used to sit
        # inside the picture with "step 64" under it, which said the step
        # count twice - once as a number in this line, once as the label of
        # the furthest waveform. Up here it costs no height at all.
        self.lbl_morph = tk.Label(morph_panel, text="", anchor="e")
        style_label(self.lbl_morph, bg=BG_PANEL, fg=FG_TEXT, font=ui_font(9, "bold"))
        stack_panel_corner(self.lbl_morph.master, (self.lbl_morph,))
        self.morph_canvas = tk.Canvas(morph_panel.body, bg=WAVE_BG,
                                       highlightthickness=0,
                                       height=sc(WT_MORPH_HEIGHT))
        self.morph_canvas.pack(fill="x")
        self.morph_canvas.bind(
            "<Configure>", lambda e: self._schedule_morph_work(autoplay=False))
        add_tooltip(self.morph_canvas,
                    "The waveforms this family steps through, front to back. The step "
    "being played is highlighted during preview.")
        self._morph_cache = None

        # No caption here any more. It read "Brass  \u00b7  64 morph steps"
        # and described the picture above it, so it moved into that picture,
        # onto the same edge as the step numbers. The "click a family"
        # prompt it also carried was a duplicate - the empty morph panel
        # says the same thing in the middle of itself.

        # --- footer ---
        foot = tk.Frame(root, bg=BG_DARK)
        self.foot = foot
        foot.pack(fill="x", pady=(10, 0))
        self.btn_clear = RoundedButton(foot, text="Clear Selection",
                                        command=self._clear_all, bg=BG_INPUT,
                                        fg=FG_TEXT, parent_bg=BG_DARK, width=130)
        self.btn_clear.pack(side="left", padx=(0, 12))
        add_tooltip(self.btn_clear,
                    "Empties the step order on the right. Nothing else is changed.")
        self.cb_autoplay = tk.Checkbutton(foot, text="Autoplay on click",
                                          variable=self.var_autoplay)
        style_checkbutton(self.cb_autoplay)
        self.cb_autoplay.pack(side="left", padx=(0, 14))
        add_tooltip(self.cb_autoplay,
                    "Plays the morph sweep as soon as you click a family. Clicking "
    "another always stops what is running. Its starting position is set "
    "under Settings → Defaults.")
        self.cb_map = tk.Checkbutton(foot, text="Save waveform overview (CSV)",
                                     variable=self.var_save_map)
        style_checkbutton(self.cb_map)
        self.cb_map.pack(side="left")
        add_tooltip(self.cb_map,
                    "Writes a table of what sits on all 255 steps: family, morph "
    "position and start frame. A file dialog opens after Apply.")

        # Deliberately identical to the Chop dialog's footer: same colours,
        # same widths, same padding, same order.
        cancel_btn = RoundedButton(foot, text="Cancel", command=self._cancel,
                                    bg=BG_INPUT, fg=FG_TEXT, parent_bg=BG_DARK)
        cancel_btn.pack(side="right", padx=4)
        self.btn_apply = RoundedButton(foot, text="Build Wavetable",
                                       command=self._apply, bg=BTN_GREEN,
                                       fg="#FFFFFF", parent_bg=BG_DARK, width=150)
        self.btn_apply.pack(side="right", padx=4)
        add_tooltip(self.btn_apply,
                    "Builds the wavetable and puts it on the pad with its .PRM. On the "
    "P-6, set SIZE to 1 and sweep START through the waveforms.")

        # Same reasoning as the alloc line used to need - status text
        # length varies a lot.
        self.lbl_status = tk.Label(root, text="", justify="left", anchor="w",
                                    wraplength=sc(560))
        style_label(self.lbl_status, fg=FG_MUTED, font=ui_font(8, "bold"))
        # The line has to stay - a build error or an import summary needs
        # somewhere to go, and it can run to two lines. Only its padding is
        # trimmed; the height it reserves is one line of 8pt text.
        self.lbl_status.pack(fill="x", pady=(4, 0))

    # -- logic -------------------------------------------------------------

    def _simple(self):
        return self.var_mode.get() == "Simple"

    def _apply_mode(self, restore=False):
        simple = self._simple()
        self._stop_preview()
        self._status("")
        # Everything below the pitch row is re-packed on every switch, all
        # of it anchored on self.foot - which is packed once in _build() and
        # never hidden. Anchoring on each other would mean each anchor had
        # to be packed already, and the FIRST one never is: pack() rejects
        # before=<widget that is not packed> outright.
        #
        # before=foot inserts immediately in front of the footer, so packing
        # them in the order they should appear gives exactly that order.
        if simple:
            # Shown here too now, exactly as Advanced packs it - Simple
            # used to fix these at the register's default, but there is no
            # reason a Simple pad can't be tuned and range-limited the same
            # way an Advanced one is.
            self.adv_row.pack(side="left", before=self.lbl_info)
            self.wt_panel.pack_forget()
            self.sets_panel.pack(fill="x", pady=(20, 0), before=self.foot)
            self.alloc_box.pack(fill="x", pady=(16, 0), before=self.foot)
            # Shown here too now: clicking a zone below selects and
            # previews that family, and this is where the preview goes -
            # the same panel Advanced uses, not a second one built to match.
            self.morph_panel.pack(fill="x", pady=(16, 0), before=self.foot)
            # Nothing to clear in Simple: the set comes from the tick boxes,
            # not from a list the user filled.
            self.btn_clear.pack_forget()
            self.lbl_mode_hint.config(text="")
            self._on_simple_set()
        else:
            # before=: pack() appends, so re-showing this frame would put it
            # AFTER the harmonics label that was packed later at build time.
            # The row then read "Register - 337 harmonics - Root note", with
            # the count wedged between two controls it does not belong to.
            self.adv_row.pack(side="left", before=self.lbl_info)
            # Hidden rather than disabled in Advanced: the sets have no
            # effect there, and a dead control that still shows a state
            # invites the reading that it does.
            self.sets_panel.pack_forget()
            self.wt_panel.pack(fill="both", expand=True, pady=(12, 0),
                               before=self.foot)
            self.alloc_box.pack(fill="x", pady=(8, 0), before=self.foot)
            self.morph_panel.pack(fill="x", pady=(8, 0), before=self.foot)
            # Same trap as adv_row: without before=, coming back from Simple
            # would land it after the CSV checkbox instead of in front of it.
            self.btn_clear.pack(side="left", padx=(0, 12), before=self.cb_autoplay)
            self.lbl_mode_hint.config(text="")
        if hasattr(self, "lb_avail"):
            self._fill_available()
        if not restore:
            self._on_register()
        else:
            self._refresh()
        self._pin_size()
        if PYP6_DEBUG:
            # After the geometry is pinned, not before: the numbers only
            # mean anything once the window has the size it will keep.
            self.after(120, self._dump_layout)

    def _pin_size(self):
        """Freezes the window at the size the current mode needs.

        Tk keeps a Toplevel glued to its requested size until an explicit
        width x height geometry is set. Setting one here means later content
        changes - a longer allocation line, a status message - redraw inside
        the window instead of resizing it. Called on every mode switch so
        Simple and Advanced can still have different sizes.
        """
        try:
            # Read before geometry("") wipes the current request: after the
            # reset the reported position is whatever Tk falls back to, and
            # putting that back moved the window a little on every mode
            # switch.
            where = wm_position_suffix(self) if self.winfo_ismapped() else ""
            self.geometry("")           # recompute from content once
            # Twice, and the LARGER of the two readings is kept. One pass
            # was enough on Tk 8.6/X11, but a widget whose size depends on
            # a <Configure> of its own - the canvases here do - can still
            # be reporting its pre-layout request after a single settle.
            # Pinning the window to that undersized number leaves the one
            # pack(expand=True) child, wt_panel, with nothing left over,
            # and the two family lists then have zero height with no error
            # anywhere. Taking the maximum can only ever ask for too much
            # room, which pack handles; too little is what loses widgets.
            self.update_idletasks()
            w1, h1 = self.winfo_reqwidth(), self.winfo_reqheight()
            self.update_idletasks()
            w = max(self.winfo_reqwidth(), w1, CHOP_MIN_W)
            h = max(self.winfo_reqheight(), h1, 200)
            if PYP6_DEBUG and (w1, h1) != (w, h):
                print(f"[swallowed] SynthDialog._pin_size: layout needed a "
                      f"second pass ({w1}x{h1} -> {w}x{h})")
            self.minsize(w, h)
            # Clamped against the screen, not just put back where it was.
            # Advanced is a good deal taller than Simple, and keeping the
            # old top-left while growing downward is what pushed the bottom
            # of the window off the display on the mode switch. `where` is
            # the value read at the top, before geometry("") wiped it.
            where = clamp_position_suffix(
                where, w, h, self.winfo_screenwidth(), self.winfo_screenheight())
            self.geometry(f"{w}x{h}{where}")
        except Exception as _e:
            _swallowed(_e, "SynthDialog._pin_size")

    def _dump_layout(self):
        """Prints what size every part of this dialog actually got.

        For the Tk 9 report where the two family lists and the morph
        preview never appeared on macOS while the pitch panel and the
        buttons did, with no error raised anywhere. A widget that is
        present but sized 1 pixel looks identical to one that was never
        created, and only the numbers tell the two apart:

          reqW x reqH   what the widget asked its parent for
          W x H         what it actually got
          mapped        whether Tk is drawing it at all

        Any line with mapped=0 or a height of 1 is the culprit. Runs only
        under PYP6_DEBUG=1 and touches nothing.
        """
        if not PYP6_DEBUG:
            return
        parts = [
            ("toplevel", self), ("wt_panel", getattr(self, "wt_panel", None)),
            ("lb_avail", getattr(self, "lb_avail", None)),
            ("sel_panel", getattr(self, "sel_panel", None)),
            ("lb_sel", getattr(self, "lb_sel", None)),
            ("alloc_box", getattr(self, "alloc_box", None)),
            ("zone_canvas", getattr(self, "zone_canvas", None)),
            ("morph_panel", getattr(self, "morph_panel", None)),
            ("morph_canvas", getattr(self, "morph_canvas", None)),
            ("foot", getattr(self, "foot", None)),
        ]
        print(f"[layout] SynthDialog, mode={self.var_mode.get()}, "
              f"Tcl/Tk {TK_PATCHLEVEL or '?'}")
        for name, w in parts:
            if w is None:
                print(f"[layout]   {name:<13} (not built)")
                continue
            try:
                print(f"[layout]   {name:<13} req {w.winfo_reqwidth():>5}x"
                      f"{w.winfo_reqheight():<5} got {w.winfo_width():>5}x"
                      f"{w.winfo_height():<5} mapped={int(bool(w.winfo_ismapped()))}")
            except Exception as _e:
                _swallowed(_e, f"SynthDialog._dump_layout/{name}")

    def _on_register(self):
        base, cycles, up = WT_REGISTERS[self.var_reg.get()]
        self.dd_note.values = [midi_to_name(base + o) for o in range(-6, 7)]
        self.var_note.set(midi_to_name(base))
        self.var_up.set(up)
        self._refresh()

    def _selection(self):
        return list(self.lb_sel.get(0, "end"))

    def simple_sets(self):
        """What Simple mode can build from: (label, [16 family names]).

        Basic is WT_SIMPLE_FAMILIES, the fixed sixteen - NOT every built-in,
        so adding a family to the app never changes what Simple builds for
        pads made before it existed. A collection contributes the first
        sixteen of its folder, which is all of it as they stand, and the
        cap is what keeps a larger collection added later from quietly
        exceeding WT_MAX_SELECTED.

        "Randomize" isn't listed here - unlike the others it has no fixed
        list to hand back, only a fresh one rolled each time it's chosen
        (see _on_simple_set and _roll_random_families). Handled as its own
        case in _simple_families instead of forcing a fake fixed list into
        this dict just to fit the same shape as the others.
        """
        out = [("Basic", list(WT_SIMPLE_FAMILIES))]
        for label, names in WT_FAMILY_GROUPS:
            if label == "Basic":
                continue
            # Multi families are taken OUT of their collection's set and
            # offered on their own below. One of them sits first in its
            # folder, so the [:16] slice put it beside fifteen sweeps -
            # where it gets 16 of the 255 steps and 16 of its 255 waveforms
            # reach the table. Advanced warns about exactly this; Simple has
            # no step order to warn about, so it must not build it that way.
            plain = [n for n in names if n not in WT_BUILTIN_MULTI][:WT_MAX_SELECTED]
            if plain:
                out.append((label, plain))
        for label, names in WT_FAMILY_GROUPS:
            for n in names:
                if n in WT_BUILTIN_MULTI:
                    out.append((n, [n]))
        return out

    def _all_family_names(self):
        """Every morphing family name across Basic and every collection,
        deduplicated - the pool Randomize draws its sixteen from.

        Multi families are excluded. Drawn into a set of sixteen, such a
        family gets a sixteenth of the steps and all but sixteen of its
        waveforms are dropped - a roll of the dice would have quietly
        produced a broken table about one time in eleven.
        """
        seen = []
        for _label, names in WT_FAMILY_GROUPS:
            for n in names:
                if n not in seen and n not in WT_BUILTIN_MULTI:
                    seen.append(n)
        return seen

    def _roll_random_families(self):
        """Picks a fresh sixteen at random from every available family and
        remembers the result, so repeated reads (a redraw, a label update)
        within the same choice see the same table instead of a new random
        set each time something merely re-reads it."""
        pool = self._all_family_names()
        n = min(WT_MAX_SELECTED, len(pool))
        self._randomized_families = random.sample(pool, n) if pool else list(WT_SIMPLE_FAMILIES)

    def _on_simple_set(self):
        """A different set means a different table - and a different zone
        strip, so the whole preview is rebuilt rather than just the label."""
        self._stop_preview()
        chosen = self.var_set.get() or "Basic"
        if chosen == "Randomize":
            self._roll_random_families()
        self._update_blurb(chosen)
        self.lbl_mode_hint.config(text="")
        self._refresh()

    def _update_blurb(self, chosen):
        """Fills the description card for the selected set."""
        fams = self._simple_families()
        multi = any(n in WT_BUILTIN_MULTI for n in fams)
        self.lbl_blurb_title.config(text=chosen)
        self.lbl_blurb_meta.config(
            text=f"{_n_families(len(fams))}  \u00b7  {WT_SEGMENTS} segments")
        self.lbl_blurb_text.config(text=wt_set_blurb(chosen, len(fams), multi))

    def _simple_families(self):
        """The sixteen families Simple will build from.

        Unticking the current box leaves the variable empty, which cannot
        build anything - so it falls back to Basic, the set this dialog
        opens with.
        """
        if self.var_set.get() == "Randomize":
            if not getattr(self, "_randomized_families", None):
                self._roll_random_families()
            return list(self._randomized_families)
        sets = dict(self.simple_sets())
        return list(sets.get(self.var_set.get()) or WT_SIMPLE_FAMILIES)

    def _active_selection(self):
        """Names, in step order. Simple mode uses the set its dropdown names."""
        return self._simple_families() if self._simple() else self._selection()

    def _resolve(self, name):
        """Name -> what the engine needs: a drawn entry, or the name itself."""
        return self.custom.get(name, name)

    def _resolved_selection(self):
        return [self._resolve(n) for n in self._active_selection()]

    def _user_groups(self):
        """User folder names, in tree order: the default first, then the
        rest alphabetically. Derived from the shapes themselves rather than
        kept in a separate list, so a folder cannot outlive its contents
        and go stale."""
        names = {e.get("group") or WT_DEFAULT_USER_GROUP
                 for e in self.custom.values() if isinstance(e, dict)}
        rest = sorted(n for n in names if n != WT_DEFAULT_USER_GROUP)
        return ([WT_DEFAULT_USER_GROUP] if WT_DEFAULT_USER_GROUP in names else []) + rest

    def _ask_user_group(self, title, count, default=None):
        """Which folder new shapes go into, or None if cancelled.

        Offers the folders that already hold something plus a new one. When
        nothing has ever been imported there is nothing to choose between,
        so it asks for a name directly instead of showing a one-item list -
        a dialog whose only options are "My Waveforms" and "new folder" is
        a dialog that should have been a text box.
        """
        existing = self._user_groups()
        if default is None:
            default = existing[0] if existing else WT_DEFAULT_USER_GROUP
        what = f"{count} waveform{'s' if count != 1 else ''}"
        if not existing:
            name = dark_ask_text(self, title,
                                 f"Folder for {what}:", default)
            return (name or "").strip() or default
        choice = dark_ask_choice(
            self, title,
            f"Put {what} into which folder?",
            existing + ["\u2026 new folder"], default)
        if choice is None:
            return None
        if not choice.startswith("\u2026"):
            return choice
        name = dark_ask_text(self, title, "Name for the new folder:", "")
        name = (name or "").strip()
        return name or None

    def _unique_custom_name(self, base="Custom", allow=None):
        """A free name based on `base`. `allow` is the one name that may be
        kept - the shape currently being edited."""
        taken = (set(self.custom) | {nm for nm, _f in WT_FAMILIES}) - {allow}
        if base not in taken:
            return base
        # Strip a trailing counter first, so editing "Custom 2" into a clash
        # gives "Custom 3" rather than "Custom 2 2".
        stem = re.sub(r"\s+\d+$", "", base) or base
        n = 2
        while f"{stem} {n}" in taken:
            n += 1
        return f"{stem} {n}"

    def _open_draw(self, existing=None):
        # The draw dialog previews at the pitch this dialog is set to, so it
        # needs the current settings, not the ones from the last build.
        midi, cycles, up = self._current_pitch()
        self.app._wt_last_config = {"note": self.var_note.get(),
                                    "cycles": cycles, "up": up}
        entry = self.custom.get(existing) if existing else None
        dlg = WaveformCreatorDialog(self, self.app, entry=entry)
        self.wait_window(dlg)
        if not dlg.result:
            return
        if dlg.result.get("delete"):
            gone = existing or dlg.result["delete"]
            self.custom.pop(gone, None)
            save_drawn_library({n: e for n, e in self.custom.items()
                                if wt_entry_is_usable(e)})
            for i in reversed(range(self.lb_sel.size())):
                if self.lb_sel.get(i) == gone:
                    self.lb_sel.delete(i)
            self._fill_available()
            self._refresh()
            self._status(f"{gone} deleted.", "warn")
            return
        new = dlg.result
        old_name = existing
        # Renaming has to carry the step order with it, otherwise the entry
        # in the right-hand list would point at a name that no longer exists.
        if old_name and old_name != new["name"] and old_name in self.custom:
            del self.custom[old_name]
            items = self._selection()
            self.lb_sel.delete(0, "end")
            for it in items:
                self.lb_sel.insert("end", new["name"] if it == old_name else it)
        # Reusing a name used to overwrite the older shape without a word.
        # Numbering it instead keeps both, and the status line says so -
        # a drawing cannot be reconstructed once it is gone.
        wanted = new["name"]
        new["name"] = self._unique_custom_name(wanted, allow=old_name)
        renamed = new["name"] != wanted
        # An edited shape keeps the folder it was already in - asking again
        # every time a curve is nudged would be noise. A new one asks once.
        if existing and isinstance(entry, dict):
            new["group"] = entry.get("group") or WT_DEFAULT_USER_GROUP
        else:
            group = self._ask_user_group("Waveform", 1)
            if group is None:
                self._status("Waveform not saved.", "info")
                return
            new["group"] = group
        self.custom[new["name"]] = new
        self._morph_shape_cache = None      # the shape changed under its name
        if not save_drawn_library({n: e for n, e in self.custom.items()
                                   if wt_entry_is_usable(e)}):
            self._status("Waveform kept for this pad, but the library could not be "
                         "written.", "bad")
        self._fill_available()
        # A shape you just drew is almost certainly meant to be used, so it
        # goes straight into the step order - unless it is already there
        # (editing an existing one) or there is no room left.
        note = (f"\"{wanted}\" was already taken, saved as \"{new['name']}\".  "
                if renamed else "")
        cur = self._selection()
        if new["name"] not in cur:
            if len(cur) < WT_MAX_SELECTED:
                self.lb_sel.insert("end", new["name"])
                self._status(f"{note}{new['name']} added to the step order.",
                             "warn" if renamed else "good")
            else:
                self._status(f"{note}{new['name']} is in the list on the left. The "
                             f"step order is full ({WT_MAX_SELECTED}), so it was "
                             f"not added - take something out to make room.",
                             "warn")
        elif renamed:
            self._status(note.strip(), "warn")
        self._refresh()

    def _import_cycles(self):
        """Reads a run of single-cycle files as one chained family run.

        The files are picked in the browser itself, which in this mode carries
        a second list for the order being built - the same shape as the Chop
        window, because it is the same job. Auditioning happens where the
        choosing happens, at this pad's root note, and the order in that list
        is the order the table morphs through.

        The shapes are chained (file 1 -> file 2 -> ...) instead of imported as
        separate static families, because a family that holds one shape twice
        fills its share of the table with the same sound repeated.

        This only builds the families and files them in their folder - it
        used to also drop them straight into the step order, but a bulk
        import is a library-building act, not a "build this pad now" one.
        The folder they landed in is opened instead, so what was just
        imported is right there to pick from.
        """
        cfg = getattr(self.app, "_wt_last_config", None) or {}
        try:
            hz = midi_to_hz(name_to_midi(self.var_note.get() or cfg.get("note", "C2")))
        except Exception:
            hz = 65.41
        start_dir = load_last_cycle_dir() or getattr(self.app, "import_root", None)
        browser = AudioPreviewDialog(self, initial_dir=start_dir, cycle_hz=hz,
                                     multi_select=True)
        self.wait_window(browser)
        try:
            if browser.current_dir and os.path.isdir(browser.current_dir):
                save_last_cycle_dir(browser.current_dir)
        except Exception as _e:
            _swallowed(_e, "SynthDialog._import_cycles")
        # AudioPreviewDialog takes the grab; without taking it back this
        # dialog stops being modal and clicks fall through to the one behind
        # it. SynthDialog has no _safe_grab helper, so it is done directly.
        try:
            self.update_idletasks()
            self.grab_set()
        except tk.TclError as _e:
            _swallowed(_e, "SynthDialog._import_cycles")
        paths = browser.selected_paths
        if not paths:
            return
        if len(paths) > WT_IMPORT_MAX_FILES and not dark_askyesno(
                "Import Cycles",
                f"{len(paths)} files are selected. Reading them all takes a "
                f"moment and every shape is kept in the saved library.\n\n"
                f"Import them?", parent=self):
            return

        self._status(f"Reading {len(paths)} cycles \u2026", "info")
        self.update_idletasks()
        try:
            entries, skipped, split_info = wt_import_cycle_folder(paths)
        except Exception as e:
            self._status("")
            dark_showerror("Import Cycles", f"Could not read the folder:\n{e}",
                           parent=self)
            return
        mode = getattr(browser, "cycle_mode", WT_CYCLE_MODE_DEFAULT)
        # Chain and Pairs both need a partner for the shape to morph into.
        # Multi does not - one waveform followed by silence is a table you
        # might actually want - so it is allowed through with just one.
        if len(entries) < (1 if mode == "Multi" else 2):
            self._status("")
            dark_showwarning(
                "Import Cycles",
                ("No usable cycles were found."
                 if mode == "Multi" else
                 f"Fewer than two usable cycles were found, so there is "
                 f"nothing to combine in {mode} mode.")
                + "\n\n" + "\n".join(f"\u2022 {s}" for s in skipped[:10]),
                parent=self)
            return

        # Named before anything is stored: a clash with a built-in family or
        # with a shape already in the library would otherwise overwrite it.
        fams = wt_families_for_mode(entries, mode)
        # What the chosen mode did with the count, said before the folder
        # prompt rather than after it. Both cases are easy to walk into by
        # accident and neither is visible in the result: an odd file out
        # becomes a static shape among morphs, and files past 255 are
        # simply not in the table.
        notes = []
        for fname, fsize, count in split_info:
            notes.append(
                f"\u201c{fname}\u201d is a whole wavetable, not a single cycle. "
                f"It was cut into {count} waveforms of {fsize} samples each, "
                f"and each one becomes its own shape.")
        if mode == "Pairs" and len(entries) % 2:
            notes.append(
                f"{len(entries)} cycles is an odd number, so the last one "
                f"(\u201c{entries[-1]['name']}\u201d) has no partner. It is kept "
                f"as a single static shape rather than dropped.")
        if mode == "Multi" and len(entries) > WT_MULTI_MAX:
            notes.append(
                f"{len(entries)} cycles were read, but a wavetable has "
                f"{WT_MULTI_MAX} steps. The first {WT_MULTI_MAX} are used and "
                f"the remaining {len(entries) - WT_MULTI_MAX} are left out.")
        if mode == "Multi" and len(entries) < WT_MULTI_MAX:
            notes.append(
                f"{len(entries)} of the {WT_MULTI_MAX} steps carry a waveform; "
                f"the remaining {WT_MULTI_MAX - len(entries)} stay silent. "
                f"Put this family in the step order on its own - sharing the "
                f"table with others gives it fewer than {WT_MULTI_MAX} steps "
                f"and only some of the shapes would make it in.")
        if notes and not dark_askyesno(
                "Import Cycles", "\n\n".join(notes) + "\n\nContinue?", parent=self):
            self._status("Import cancelled.", "info")
            return
        # Asked once for the whole run, not per family: a folder import is
        # one act, and sixteen prompts for sixteen chained shapes would be
        # sixteen chances to answer differently by accident.
        group = self._ask_user_group("Import Cycles", len(fams))
        if group is None:
            self._status("Import cancelled.", "info")
            return
        added = []
        for fam in fams:
            fam["name"] = self._unique_custom_name(fam["name"])
            fam["group"] = group
            self.custom[fam["name"]] = fam
            added.append(fam["name"])
        # wt_entry_is_usable, not kind == "draw". All five save sites rewrite
        # the whole library from self.custom, so this filter decided what
        # SURVIVED, not what got added - and a multi family failed it. A
        # Multi-mode import was written out of existence by the very save
        # that was meant to store it.
        save_drawn_library({n: e for n, e in self.custom.items()
                            if wt_entry_is_usable(e)})
        self._fill_available()
        # Open the folder the new families landed in - they are the reason
        # this just happened, so they should be right there to see, not
        # buried under a still-collapsed node.
        gid = WT_USER_GROUP_IID + group
        if self.lb_avail.exists(gid):
            self.lb_avail.item(gid, open=True)
            # _avail_open_only() now scrolls the folder to the top itself,
            # on idle. The bare see() that used to follow ran first and was
            # undone a moment later, so it only ever queued a redraw.
            self._avail_open_only(gid)

        self._status(f"{len(entries)} cycles \u2192 {len(added)} families "
                     f"({mode}) in \u201c{group}\u201d",
                     "good" if not skipped else "warn")
        if skipped:
            dark_showwarning(
                "Some Files Skipped",
                "These were not read as single cycles:\n\n"
                + "\n".join(f"\u2022 {s}" for s in skipped[:10])
                + (f"\n\n\u2026 and {len(skipped) - 10} more." if len(skipped) > 10 else ""),
                parent=self)

    def _fill_available(self):
        """Built-ins first, then the drawn ones, so the fixed set keeps a
        stable order no matter how many shapes get added."""
        opened = {iid for iid in self.lb_avail.get_children("")
                   if self.lb_avail.item(iid, "open")}
        first_fill = not self.lb_avail.get_children("")
        self.lb_avail.delete(*self.lb_avail.get_children(""))

        builtin_labels = {lab for lab, _n in WT_FAMILY_GROUPS}

        def add_group(label, names, user=False):
            if not names:
                return
            gid = (WT_USER_GROUP_IID if user else WT_GROUP_IID) + label
            # A user folder named like a built-in collection gets a marker,
            # or the tree would show two rows with identical text and no way
            # to tell which one holds what.
            text = (f"{label}  (yours)" if user and label in builtin_labels
                    else label)
            # Basic open on first build, the collections closed - they are
            # sixteen entries each and would bury the set most tables are
            # actually built from. After that the user's own open/closed
            # state is what is restored, so a refresh never folds a group
            # away under them.
            is_open = (label == "Basic") if first_fill else (gid in opened)
            # Guarded like the children below. The group row used to be the
            # one insert here that could still abort the whole fill, and it
            # did - a duplicate id raised straight out of _fill_available
            # and the Synth dialog never opened at all.
            try:
                self.lb_avail.insert("", "end", iid=gid, text=text,
                                     open=is_open, tags=("group",))
            except tk.TclError as _e:
                _swallowed(_e, "SynthDialog._fill_available.group")
                return
            for nm in names:
                # A colliding id (e.g. an imported shape that happens to
                # share a name with a built-in family) must not abort the
                # rest of this fill - that used to leave this group, and
                # every group after it, looking empty even though their
                # shapes were all still in the library.
                try:
                    self.lb_avail.insert(gid, "end", iid=nm, text=nm,
                                          tags=("family",))
                except tk.TclError as _e:
                    _swallowed(_e, "SynthDialog._fill_available.add_group")

        for label, names in WT_FAMILY_GROUPS:
            add_group(label, names)
        # The user's own shapes, one node per folder. Sorted inside a
        # folder by name so a chained import reads in its import order,
        # which is what its numbering means.
        by_group = {}
        for nm, e in self.custom.items():
            grp = (e.get("group") if isinstance(e, dict) else None) \
                or WT_DEFAULT_USER_GROUP
            by_group.setdefault(grp, []).append(nm)
        for label in self._user_groups():
            add_group(label, sorted(by_group.get(label, []), key=wt_natural_key),
                      user=True)
        self._sync_delete_button()

    def _on_avail_double(self, _event=None):
        name = self._avail_first_selected()
        if name is None:
            # A group row: no "break" here, unlike below - that would
            # stop the event before it ever reaches ttk's own handler,
            # which is what actually opens or closes it. This binding
            # replaces the widget's default one rather than adding to it,
            # so without letting the event through explicitly, a double
            # click on a group did nothing at all.
            return
        if name in self.custom:
            self._edit_selected_custom()
        else:
            self._move_right()

    def _edit_selected_custom(self, _event=None):
        name = self._avail_first_selected()
        if not name:
            return
        entry = self.custom.get(name)
        if isinstance(entry, dict) and entry.get("kind") == "multi":
            # The drawing editor works on one A/B pair. A Multi family holds
            # a whole list, and opening it there would have shown the first
            # shape and quietly written back a two-shape family over all of
            # them on save.
            self._status(
                f"\u201c{name}\u201d holds {len(entry.get('shapes') or [])} "
                f"waveforms and cannot be opened in the drawing editor. "
                f"Import the cycles again to change it.", "info")
            return
        if name in self.custom:
            self._open_draw(existing=name)

    def _move_right(self):
        cur = self._selection()
        added, skipped, no_room = 0, [], []
        for name in self._avail_selected():
            if name in cur:
                skipped.append(name)
                continue
            if len(cur) >= WT_MAX_SELECTED:
                no_room.append(name)
                continue
            self.lb_sel.insert("end", name)
            cur.append(name)
            added += 1
        self._refresh()
        # A Multi family addresses its shapes against the full 255 steps, so
        # it only lands 1:1 when it has the table to itself. Beside anything
        # else it gets a fraction of the steps and most of its shapes never
        # appear - which looks like a broken import rather than a choice the
        # step order made.
        multi = [n for n in cur
                 if n in WT_BUILTIN_MULTI or wt_entry_is_multi(self.custom.get(n))]
        if multi and len(cur) > 1:
            self._status(
                f"\u201c{multi[0]}\u201d holds one waveform per step and needs all "
                f"{WT_SEGMENTS} of them. Sharing the step order leaves it "
                f"{wt_split_steps(len(cur))[0]}, so most of its shapes will not "
                f"be in the table.", "warn")
            return
        if no_room:
            self._status(f"The step order holds {WT_MAX_SELECTED} families at most. "
                         f"No room for {', '.join(no_room)} - take something out "
                         f"first.", "warn")
            return
        # Silently doing nothing is the worst outcome here - the click looks
        # broken. Each family can only appear once, so say so.
        if skipped and not added:
            self._status("Already in the step order: " + ", ".join(skipped)
                         + ".  Each family can be used once; reorder it with the "
                           "arrows instead.", "warn")
        elif skipped:
            self._status(f"Added {added}, skipped {len(skipped)} already in the "
                         f"step order ({', '.join(skipped)}).", "info")
        else:
            self._status("")

    def _move_left(self):
        removed = [self.lb_sel.get(i) for i in self.lb_sel.curselection()]
        if self.prev_playing and self.prev_family in removed:
            self._stop_preview()
        for i in reversed(self.lb_sel.curselection()):
            self.lb_sel.delete(i)
        self._refresh()

    def _clear_all(self):
        self.lb_sel.delete(0, "end")
        self._refresh()

    def _sel_drop(self, rows, gap):
        """Drag-and-drop counterpart to _reorder()."""
        items, moved = reorder_list(self._selection(), rows, gap)
        self.lb_sel.delete(0, "end")
        for it in items:
            self.lb_sel.insert("end", it)
        for i in moved:
            self.lb_sel.selection_set(i)
        if moved:
            self.lb_sel.see(moved[0])
        self._refresh()

    def _reorder(self, delta):
        idx = list(self.lb_sel.curselection())
        if not idx:
            return
        items = self._selection()
        order = idx if delta < 0 else list(reversed(idx))
        moved = []
        for i in order:
            j = i + delta
            if 0 <= j < len(items) and j not in moved:
                items[i], items[j] = items[j], items[i]
                moved.append(j)
        self.lb_sel.delete(0, "end")
        for it in items:
            self.lb_sel.insert("end", it)
        for i in moved:
            self.lb_sel.selection_set(i)
        if moved:
            # Aimed at whichever end the movement is heading toward, and
            # only once: two calls back to back (one per edge) was what
            # caused a visible jitter right at the list's edges - Tk
            # settling the scroll position twice in the same tick instead
            # of once.
            self.lb_sel.see(min(moved) if delta < 0 else max(moved))
        self._refresh()

    def _current_pitch(self):
        try:
            midi = name_to_midi(self.var_note.get())
        except (ValueError, KeyError):
            midi = WT_REGISTERS[self.var_reg.get()][0]
        cycles = WT_REGISTERS[self.var_reg.get()][1]
        try:
            # Held to the device ceiling. to=36 on the Spinbox only governs
            # its arrows - the field is typable and the value can also
            # arrive from a stored config, and anything above 36 would
            # spend harmonics on a range the P-6 will not play.
            up = max(0, min(WT_DEVICE_MAX_UP, int(self.var_up.get())))
            if up != self.var_up.get():
                self.var_up.set(up)
        except (tk.TclError, ValueError):
            up = 0
        return midi, cycles, up

    def _refresh(self):
        midi, cycles, up = self._current_pitch()
        # cents is discarded: the info line no longer shows the deviation,
        # and naming it would suggest it still matters here.
        L, f_real, _cents = wt_tuning_info(midi, cycles)
        h, h_max = wt_harmonics_for(L, cycles, up)
        # Trimmed to the three numbers that inform a decision. What went:
        # the segment length in frames and the total duration, both fixed
        # by the register that is already named in the dropdown above; the
        # cents deviation, which is the unavoidable rounding of a cycle to
        # whole samples and not something anyone can act on; START 0-254,
        # which is the same for every table; and the top frequency, which
        # is just harmonics x root and never the reason to change anything.
        #
        # The warning now carries its own frame count, since the line no
        # longer shows one to compare against.
        warn = "" if L <= WT_MAX_SEG_FRAMES else \
            f"    \u00b7    segment too long: {L} frames, max {WT_MAX_SEG_FRAMES}"

        sel = self._selection()
        # Blank until there is something to describe. In Advanced with an
        # empty Step Order these numbers describe a table that does not
        # exist yet - "337 of 337 possible harmonics" of nothing - and read
        # as if the dialog were already configured. Simple mode always has
        # its fixed set, so it always has something to say.
        if self._simple() or sel:
            # Hz and the step length were dropped: the register names the
            # pitch already, and nobody sets a wavetable up by its segment
            # duration in milliseconds. What is left is the one number that
            # changes with the range spinner next to it.
            # The harmonic count says what survives; this says what that
            # buys you in notes, which is the form the decision is
            # actually made in. It matters most in Simple mode, where the
            # "Plays up to" spinner is hidden altogether and the
            # register's own range is the only thing setting it - a Bass
            # table plays its root and everything below, and nothing
            # above, which was previously stated nowhere in the window.
            # Two separate ceilings, and the lower one wins. The table's
            # own is the band limit (wt_playable_range); the P-6's is a
            # flat three octaves off the root. Naming which one is doing
            # the stopping is the point - "give it fewer harmonics" fixes
            # the first and does nothing at all for the second.
            # "Plays up to" is the SAMPLER's reach and nothing else: three
            # octaves off the root, always, however the table is built.
            # Saying "plays up to C2 (its root)" for a full-harmonic Bass
            # table was simply wrong - the P-6 plays it right up to C5,
            # it just folds the partials that no longer fit on the way.
            #
            # The band limit is a separate claim about quality, so it is
            # stated separately and only while it actually bites. Where
            # the two meet there is nothing left to qualify and the
            # second half drops away.
            clean = wt_playable_range(L, cycles, up)
            reach = f"plays up to {midi_to_name(midi + WT_DEVICE_MAX_UP)}"
            if clean < WT_DEVICE_MAX_UP:
                reach += f", clean to {midi_to_name(midi + clean)}"
            self.lbl_info.config(
                text=f"{h} of {h_max} possible harmonics  \u00b7  {reach}{warn}")
        else:
            self.lbl_info.config(text="")
        # Families already in use are dimmed in the left column, so the state
        # is visible before anyone clicks the arrow.
        used = set(sel)
        for grp in self.lb_avail.get_children(""):
            for iid in self.lb_avail.get_children(grp):
                self.lb_avail.item(iid, tags=("used",) if iid in used else ("family",))
        # The strip carries the per-family step counts now, so the line
        # under it only has to say how full the order is.
        # On the Step Order panel's own heading. It used to sit on a line of
        # its own under the strip, in a smaller font, describing the list
        # two panels away from it.
        active = self._active_selection()
        if active:
            cap = "   (full)" if len(active) >= WT_MAX_SELECTED else ""
            self.sel_panel.set_title(
                f"Step Order: {len(active)} of {WT_MAX_SELECTED} families"
                f"   \u00b7   {WT_SEGMENTS} segments{cap}")
        else:
            self.sel_panel.set_title("Step Order")
        self._draw_zones()
        self._update_preview_label()

    # -- preview -----------------------------------------------------------

    def _pick_preview(self, listbox):
        """Called from either list. The two are now different widget kinds,
        so reading "what is picked" and "clear the other one" has to branch
        rather than assume a Listbox on both sides."""
        if listbox is self.lb_avail:
            picked = self._avail_first_selected()
            if picked is None:
                return          # a group row carries no family to preview
        else:
            cur = listbox.curselection()
            if not cur:
                return
            picked = listbox.get(cur[0])
        # Switching families mid-sweep used to leave the old one playing under
        # the new one's curves - what you saw and what you heard came from
        # different families. The sound belongs to the drawing on screen, so
        # picking a different one ends it.
        if self.prev_playing and picked != self.prev_family:
            self._stop_preview()
        self.prev_family = picked
        if listbox is self.lb_avail:
            self.lb_sel.selection_clear(0, "end")
        else:
            self.lb_avail.selection_remove(*self.lb_avail.selection())
        self._sync_delete_button()
        self._update_preview_label()
        # So the zone strip's active-zone outline follows the pick, not
        # just whatever a step-order change last redrew it for.
        self._draw_zones()
        # Debounced. Rendering the stack costs ~10 ms and building an autoplay
        # sweep ~50 ms, so arrowing through the list at five clicks a second
        # queued a third of a second of work per second and the window stopped
        # responding. Only the family you land on is worth rendering.
        self._schedule_morph_work()

    MORPH_DEBOUNCE_MS = 130

    def _schedule_morph_work(self, autoplay=True):
        if getattr(self, "_morph_job", None):
            try:
                self.after_cancel(self._morph_job)
            except (tk.TclError, ValueError) as _e:
                _swallowed(_e, "SynthDialog._schedule_morph_work")
        # A resize that arrives while a click is pending must not cancel the
        # click's intent to play.
        self._morph_autoplay = autoplay or getattr(self, "_morph_autoplay", False)
        self._morph_job = self.after(self.MORPH_DEBOUNCE_MS, self._do_morph_work)

    def _do_morph_work(self):
        self._morph_job = None
        autoplay = getattr(self, "_morph_autoplay", False)
        self._morph_autoplay = False
        try:
            self._draw_morph()
        except tk.TclError:
            return
        # Only when nothing is running: clicking the family that is already
        # playing should not cut it off, and a switch stopped the previous one
        # back in _pick_preview.
        if autoplay and self.var_autoplay.get() and not self.prev_playing \
                and self.prev_family:
            self._toggle_preview()

    def _status(self, text, kind="info", clear_after=6000):
        """One place for the line under the dialog.

        Everything used to be muted grey, including the messages that ask you
        to do something - so "the step order is full" read like a footnote
        and got missed. The tone now picks the colour.

        Messages also expire. "2 waveforms deleted" is about something that
        already happened; leaving it up means that ten minutes later the
        dialog still reports an action the user has long forgotten, and it
        is impossible to tell a fresh message from a stale one. Pass
        clear_after=None for a message that describes a lasting STATE
        rather than an event.
        """
        # Both spellings on purpose. The app's show_status() grew its own
        # vocabulary ("success"/"warning") and this one grew another
        # ("good"/"warn"/"bad"); only "info" meant the same in both, and a
        # name from the wrong list produced no error - just a grey line
        # where a red one was meant. Accepting either makes the two
        # interchangeable instead of quietly different.
        colors = {"info": FG_MUTED,
                  "good": ACCENT_GREEN, "success": ACCENT_GREEN,
                  "warn": ACCENT_ORANGE, "warning": ACCENT_ORANGE,
                  "bad": ACCENT_RED, "error": ACCENT_RED}
        self.lbl_status.config(text=text, fg=colors.get(kind, FG_MUTED))
        # Any pending expiry belongs to the message just replaced.
        job = getattr(self, "_status_job", None)
        if job:
            try:
                self.after_cancel(job)
            except tk.TclError as _e:
                _swallowed(_e, "SynthDialog._status")
        self._status_job = None
        if text and clear_after:
            self._status_job = self.after(clear_after, self._clear_status)

    def _clear_status(self):
        self._status_job = None
        try:
            if self.winfo_exists():
                self.lbl_status.config(text="")
        except tk.TclError as _e:
            _swallowed(_e, "SynthDialog._clear_status")

    def _selected_custom_names(self):
        """The drawn families highlighted on the left, in list order.

        The listbox is already selectmode="extended", so a range was always
        selectable - only delete acted on the first entry alone. Selecting a
        folder's header stands in for everything inside it, so deleting a
        folder does not first require opening it and marking every shape by
        hand.
        """
        names = [n for n in self._avail_selected() if n in self.custom]
        for label in self._avail_selected_groups():
            for n, e in self.custom.items():
                grp = (e.get("group") if isinstance(e, dict) else None) \
                    or WT_DEFAULT_USER_GROUP
                if grp == label and n not in names:
                    names.append(n)
        return names

    def _sync_delete_button(self):
        """Live as soon as at least one drawn family is highlighted."""
        if not hasattr(self, "btn_del"):
            return
        self.btn_del.config_state("normal" if self._selected_custom_names()
                                  else "disabled")

    def _delete_custom(self):
        names = self._selected_custom_names()
        if not names:
            return
        folders = self._avail_selected_groups()
        in_order = [n for n in names if n in self._selection()]
        # Built-ins can be part of the highlighted range without being
        # deletable, so the count that is confirmed is the one that will go.
        if folders:
            if len(folders) == 1:
                question = (f"Remove the folder \u201c{folders[0]}\u201d and its "
                            f"{len(names)} waveform"
                            f"{'s' if len(names) != 1 else ''}?")
            else:
                shown = "\n".join(f"\u2022 {f}" for f in folders)
                question = (f"Remove these {len(folders)} folders and their "
                            f"{len(names)} waveforms in total?\n\n{shown}")
        elif len(names) == 1:
            question = f"Remove \"{names[0]}\" from the saved waveforms?"
        else:
            shown = "\n".join(f"\u2022 {n}" for n in names[:12])
            more = f"\n\u2026 and {len(names) - 12} more." if len(names) > 12 else ""
            question = (f"Remove these {len(names)} waveforms from the saved "
                        f"waveforms?\n\n{shown}{more}")
        if not dark_askyesno(
                "Delete Waveform" + ("s" if len(names) > 1 else ""),
                question +
                (f"\n\n{len(in_order)} of them are in the step order and will be "
                 f"taken out." if len(in_order) > 1 else
                 "\n\nIt is currently in the step order and will be taken out."
                 if in_order else "") +
                "\n\nWavetables already built with them are not affected.",
                parent=self):
            return
        gone = set(names)
        for name in names:
            self.custom.pop(name, None)
        save_drawn_library({n: e for n, e in self.custom.items()
                            if wt_entry_is_usable(e)})
        for i in reversed(range(self.lb_sel.size())):
            if self.lb_sel.get(i) in gone:
                self.lb_sel.delete(i)
        if self.prev_family in gone:
            self.prev_family = None
        self._fill_available()
        self._sync_delete_button()
        self._refresh()
        if folders:
            self._status(f"Folder \u201c{folders[0]}\u201d deleted."
                         if len(folders) == 1 else
                         f"{len(folders)} folders deleted.", "warn")
        else:
            self._status(f"{names[0]} deleted." if len(names) == 1
                         else f"{len(names)} waveforms deleted.", "warn")

    def _morph_shapes(self, family, count):
        """Renders the shapes this family steps through, for display only.

        Rendered at the real segment length and harmonic count, not at a
        convenient round number. A coarser display costs accuracy exactly
        where it is least acceptable: families whose morph mainly adds upper
        harmonics - Saw above all - looked far flatter than they sound,
        because at 64 harmonics the ones being added were never there. At the
        true resolution all sixteen families are drawn with no visible loss,
        for about 15 ms per redraw.
        """
        midi, cycles, up = self._current_pitch()
        try:
            L, f_real, _c = wt_tuning_info(midi, cycles)
            h, _hm = wt_harmonics_for(L, cycles, up)
        except Exception:
            L, f_real, h, cycles = 674, 65.41, 337, 1
        Lp = int(min(L, WT_MORPH_MAX_POINTS))
        hp = max(4, min(int(h), Lp // (2 * max(1, cycles))))
        # Cached per family and per pitch setting: going back and forth
        # between two families is the normal way to compare them, and the
        # second visit should not cost another render.
        key = (family, Lp, cycles, hp, count)
        cached = getattr(self, "_morph_shape_cache", None)
        if cached is not None and cached[0] == key:
            return cached[1]
        synth = WTSynth(Lp, cycles, hp)
        _name, fn = wt_family_entry(self._resolve(family))
        out = []
        for j in range(count):
            m = 0.5 if count == 1 else j / (count - 1)
            w, _d = fn(synth, m, f_real)
            w = synth.band_limit(np.asarray(w, dtype=np.float64))
            peak = np.max(np.abs(w))
            out.append(w / peak if peak > 1e-12 else w)
        self._morph_shape_cache = (key, out)
        return out

    def _morph_geometry(self):
        """Layout of the stack, derived from the canvas as it actually is.

        The height was previously taken from WT_MORPH_HEIGHT, the value the
        canvas *asks* for. Tk grants that only when there is room; in a
        squeezed dialog the canvas ends up shorter and the curves at the back
        were drawn above its top edge, so the stack looked like it stopped
        after a few steps. Everything is sized off winfo_height() now, and
        the arithmetic below places the topmost curve exactly on the margin,
        so all of them fit whatever height it gets.
        """
        c = self.morph_canvas
        w = max(2, c.winfo_width())
        h = max(2, c.winfo_height())
        margin = 6
        usable = h - 2 * margin
        if usable < 30 or w < 80:
            return None
        depth_x = w * 0.22
        depth_y = usable * 0.5
        amp = (usable - depth_y) / 2.0
        base_y = h - margin - amp
        return w, h, depth_x, depth_y, amp, base_y, w - depth_x - 4

    def _morph_points(self, vals, idx, shown, geo):
        w, h, depth_x, depth_y, amp, base_y, front_w = geo
        frac = idx / max(1, shown - 1)
        ox, oy = depth_x * frac, -depth_y * frac
        step = max(1, len(vals) // 220)
        pts = []
        for i in range(0, len(vals), step):
            pts += [ox + i / (len(vals) - 1) * front_w,
                    base_y + oy - vals[i] * amp]
        return pts, ox, oy

    def _draw_morph(self):
        c = getattr(self, "morph_canvas", None)
        if c is None:
            return
        c.delete("all")
        geo = self._morph_geometry()
        if geo is None:
            self._morph_cache = None
            return          # too small to show anything meaningful
        w, h = geo[0], geo[1]
        if not self.prev_family:
            c.create_text(w / 2, h / 2, text="Click a family to see its morph",
                          fill=FG_MUTED, font=ui_font(8))
            self._morph_cache = None
            return

        total = self._preview_steps(self.prev_family)
        shown = max(2, min(WT_MORPH_SHOWN, total))
        try:
            shapes = self._morph_shapes(self.prev_family, shown)
        except Exception as e:
            c.create_text(w / 2, h / 2, text=f"Could not render: {e}",
                          fill=FG_MUTED, font=ui_font(8))
            return
        self._morph_cache = (self.prev_family, shapes, total)
        line = readable_on(WAVE_COLOR, WAVE_BG, 7.0)

        # Back to front, each shape filled with the canvas colour before it is
        # stroked: that is what makes a nearer curve hide the one behind it,
        # which is the whole reason the stack reads as depth. The fill runs
        # down to the bottom edge, not just to the curve's own baseline -
        # anything further away lives above this curve, so a short fill would
        # occlude nothing.
        for idx in range(shown - 1, -1, -1):
            pts, ox, oy = self._morph_points(shapes[idx], idx, shown, geo)
            far = idx / max(1, shown - 1)
            col = blend_colors(line, WAVE_BG, 0.62 * far)
            poly = pts + [pts[-2], h, pts[0], h]
            c.create_polygon(*poly, fill=WAVE_BG, outline="")
            c.create_line(*pts, fill=col, width=2 if idx == 0 else 1,
                          tags=f"step{idx}")
        # The "step 1" caption that used to sit here is gone too now - it
        # marked which edge the sweep starts from, but wasn't asked for.
        self._sync_morph_label()
        self._highlight_morph_step(None)

    def _highlight_morph_step(self, frac):
        """Marks the step currently sounding. `frac` runs 0..1, None clears."""
        c = getattr(self, "morph_canvas", None)
        if c is None or not self._morph_cache:
            return
        c.delete("morphmark")
        if frac is None:
            return
        geo = self._morph_geometry()
        if geo is None:
            return
        _fam, shapes, _total = self._morph_cache
        shown = len(shapes)
        idx = int(min(shown - 1, max(0, round(frac * (shown - 1)))))
        # Same helper the stack uses, so the marker can never sit next to the
        # curve it is meant to be on.
        pts, _ox, _oy = self._morph_points(shapes[idx], idx, shown, geo)
        c.create_line(*pts, fill=ACCENT_ORANGE, width=2, tags="morphmark")

    PREVIEW_STEP_CAP = 64

    def _actual_steps(self, family):
        """How many steps this family really gets in the built table -
        uncapped, so the label can state a fact rather than a rendering
        shortcut."""
        sel = self._active_selection()
        if family in sel:
            return wt_split_steps(len(sel))[sel.index(family)]
        return wt_split_steps(len(sel) + 1)[-1]

    def _preview_steps(self, family):
        # With an empty selection this would be all 255 segments, i.e. 255
        # additive syntheses before a single sample is heard. The morph is
        # smooth enough that 64 sounds the same. This cap is for rendering
        # and audio preview cost only - it must never be shown to the user
        # as the step count, which _actual_steps is for.
        return min(self._actual_steps(family), self.PREVIEW_STEP_CAP)

    def _on_zone_canvas_click(self, event):
        """Clicking a zone selects and previews that family - the zone
        strip's own version of clicking a row in the Available list.

        Reuses the region data _ZoneHoverTooltip already tracks for the
        same canvas rather than re-deriving zone boundaries a second way:
        the two would only ever need to agree with each other anyway.
        """
        zone_tip = getattr(self.zone_canvas, "_zone_tip", None)
        if zone_tip is None:
            return
        region = zone_tip._region_at(event.x)
        if region is None:
            return
        _x0, _x1, name, _lo, _hi = region
        if self.prev_playing and name != self.prev_family:
            self._stop_preview()
        self.prev_family = name
        # Advanced-only widgets; Simple mode has no lists at all.
        #
        # The step order IS what the strip draws, so the clicked zone has a
        # row up there and it gets selected. This used to CLEAR both lists
        # instead, which left the outline on the strip and the name in the
        # Morph header pointing at a family nothing in the list agreed with
        # - the one place in the dialog where clicking something told you
        # less than before you clicked.
        if hasattr(self, "lb_avail"):
            self.lb_avail.selection_remove(*self.lb_avail.selection())
        if hasattr(self, "lb_sel"):
            self.lb_sel.selection_clear(0, "end")
            try:
                idx = self._selection().index(name)
            except ValueError:
                idx = None
            if idx is not None:
                self.lb_sel.selection_set(idx)
                self.lb_sel.activate(idx)
                self.lb_sel.see(idx)
        if hasattr(self, "_sync_delete_button"):
            self._sync_delete_button()
        self._update_preview_label()
        # So the active-zone outline appears on this zone immediately,
        # rather than waiting for some other reason to redraw the strip.
        self._draw_zones()
        self._schedule_morph_work()

    def _draw_zones(self):
        """Redraws the strip from whatever is currently active.

        Uses the same names the build will use: in Simple that is the set
        the dropdown names, in Advanced the step order. Anything else would
        be a picture of a table nobody is about to make.
        """
        if not hasattr(self, "zone_canvas"):
            return
        c = self.zone_canvas
        c.delete("all")
        names = self._active_selection()
        # The canvas's REAL size, with no floor under it. A max() against
        # the requested height was wrong in the one case that matters:
        # before the layout settles winfo_height() is 1, the floor made it
        # 80, and the border was then drawn at y=79 on a canvas one pixel
        # tall - off the bottom, and never seen. Anything below a few
        # pixels is not laid out yet, and <Configure> will call this again
        # the moment it is.
        width, height = c.winfo_width(), c.winfo_height()
        if width < 8 or height < 8:
            return
        if names:
            # Handle imported/custom chains (strings in self.custom) and dicts
            labels = []
            for n in names:
                if isinstance(n, dict):
                    labels.append(n.get("name") or "Custom")
                elif n in self.custom:
                    labels.append(n)
                else:
                    labels.append(wt_family_entry(n)[0])
            draw_wavetable_zones(c, {"families": labels,
                                     "counts": wt_split_steps(len(names))},
                                 width, height, top_pad=0, bot_pad=0)
            # Outlines whichever zone is currently playing, or was last -
            # reuses the same region data the hover tooltip tracks for this
            # canvas rather than re-deriving zone boundaries a second way.
            # Drawn before round_canvas_corners below, so on the first or
            # last zone the corner-rounding step clips this outline into
            # the same rounded shape as the zone itself, instead of a
            # square corner poking out past it.
            zone_tip = getattr(c, "_zone_tip", None)
            if zone_tip is not None and self.prev_family:
                for x0, x1, name, _lo, _hi in zone_tip.regions:
                    if name == self.prev_family:
                        self._draw_active_zone_outline(c, x0, x1, width, height)
                        break
        else:
            c.create_text(width / 2, height / 2,
                           text=f"Nothing selected \u2013 move at least one family "
                                f"to the right (up to {WT_MAX_SELECTED})",
                           fill=FG_MUTED, font=ui_font(9), anchor="c")
        # Last, so it paints over whatever the strip put in the corners.
        round_canvas_corners(c, width, height, sc(10), BG_DARK, BORDER_LIGHT)

    def _draw_active_zone_outline(self, c, x0, x1, width, height):
        """Outlines a zone's own rectangle, rounded only on whichever side
        actually touches the strip's own rounded corner (the left side of
        the first zone, the right side of the last), sharp everywhere
        else. Letting round_canvas_corners() clip a plain rectangle's
        corner into shape afterward turned out not to work reliably - its
        corner-covering polygons are sized for the strip's own edge, not
        whatever this outline's inset happened to leave behind - so the
        rounded corners are built directly instead, the same four-arc,
        four-line construction _canvas_round_outline() uses for the strip
        itself.
        """
        lw = sc(2)
        half = lw / 2.0
        x0i, x1i = max(x0, half), min(x1, width - half)
        y0i, y1i = half, height - half
        round_left = x0 <= 0.5
        round_right = x1 >= width - 0.5
        r = max(0, min(sc(10), (x1i - x0i) / 2.0, (y1i - y0i) / 2.0))
        kw = dict(fill=ACCENT_BLUE, width=lw, tags="active_zone")
        akw = dict(style="arc", outline=ACCENT_BLUE, width=lw, tags="active_zone")
        if not round_left and not round_right:
            c.create_rectangle(x0i, y0i, x1i, y1i, outline=ACCENT_BLUE,
                               width=lw, tags="active_zone")
            return
        lpad, rpad = (r if round_left else 0), (r if round_right else 0)
        c.create_line(x0i + lpad, y0i, x1i - rpad, y0i, **kw)
        c.create_line(x0i + lpad, y1i, x1i - rpad, y1i, **kw)
        c.create_line(x0i, y0i + lpad, x0i, y1i - lpad, **kw)
        c.create_line(x1i, y0i + rpad, x1i, y1i - rpad, **kw)
        if round_left:
            c.create_arc(x0i, y0i, x0i + 2 * r, y0i + 2 * r, start=90, extent=90, **akw)
            c.create_arc(x0i, y1i - 2 * r, x0i + 2 * r, y1i, start=180, extent=90, **akw)
        if round_right:
            c.create_arc(x1i - 2 * r, y0i, x1i, y0i + 2 * r, start=0, extent=90, **akw)
            c.create_arc(x1i - 2 * r, y1i - 2 * r, x1i, y1i, start=270, extent=90, **akw)

    def _update_preview_label(self):
        if not self.prev_family:
            self.btn_prev.text = "\u25b6"
            self.btn_prev.config_state("disabled")
            self.btn_prev._draw()
            self._draw_morph()
            return
        self.btn_prev.config_state("normal")
        if not self.prev_playing:
            self.btn_prev.text = "\u25b6"
            self.btn_prev._draw()
        self._sync_morph_label()
        self._draw_morph()

    def _sync_morph_label(self):
        """The family and its step count, on the Morph panel's title line."""
        if not hasattr(self, "lbl_morph"):
            return
        if not self.prev_family:
            self.lbl_morph.config(text="")
            return
        n = self._actual_steps(self.prev_family)
        # Simple mode has no "add" step to speak of - every family clicked
        # there came from the table's own zone strip, so it was always
        # already in. The note is Advanced-only, for a family clicked in
        # Available before it has been moved into the step order.
        note = "" if self._simple() or self.prev_family in self._active_selection() \
            else "   (once added)"
        # Handle three cases: dict (custom family), string in self.custom
        # (imported chain), or standard family name in WT_FAMILY_MAP
        if isinstance(self.prev_family, dict):
            display_name = self.prev_family.get("name") or "Custom"
        elif self.prev_family in self.custom:
            display_name = self.prev_family
        else:
            display_name = wt_family_entry(self.prev_family)[0]
        self.lbl_morph.config(
            text=f"{display_name}   \u00b7   {n} steps{note}")

    def _stop_preview(self):
        if self.prev_playing:
            try:
                sd.stop()
            except Exception as _e:
                _swallowed(_e, "SynthDialog._stop_preview")
            self.prev_playing = False
        self._cancel_finish_job()
        self._prev_token = getattr(self, "_prev_token", 0) + 1
        try:
            self._highlight_morph_step(None)
        except (tk.TclError, AttributeError) as _e:
            _swallowed(_e, "SynthDialog._stop_preview")

    def _toggle_preview(self):
        if self.prev_playing:
            self._stop_preview()
            self._update_preview_label()
            return
        if not self.prev_family:
            return
        midi, cycles, up = self._current_pitch()
        steps = self._preview_steps(self.prev_family)
        try:
            audio = wt_render_sweep(self._resolve(self.prev_family),
                                    midi, cycles, up, steps)
            sd.play(audio, WT_SR)
        except Exception as e:
            self._status(f"Preview failed: {e}", "bad")
            return
        self.prev_playing = True
        self.btn_prev.text = "\u25a0"
        self.btn_prev._draw()
        # Wall clock rather than a frame counter: sounddevice reports no
        # position here, and the sweep has a known, fixed length. The token
        # makes a stale tick from a previous run stop by itself.
        self._prev_started = time.time()
        self._prev_token = getattr(self, "_prev_token", 0) + 1
        self._tick_morph_marker(self._prev_token)
        self._cancel_finish_job()
        # Tagged with the token as well. Switching family mid-sweep left the
        # abandoned run's finish timer alive; it fired later and ended the
        # sweep that was playing by then - marker frozen part-way, sound
        # carrying on. Cancelling is the fix, the token is the safety net for
        # a callback already queued when the cancel arrives.
        self._finish_job = self.after(
            int(WT_PREVIEW_SECONDS * 1000) + 250,
            lambda t=self._prev_token: self._preview_finished(t))

    def _tick_morph_marker(self, token):
        if token != getattr(self, "_prev_token", 0) or not self.prev_playing:
            return
        elapsed = time.time() - getattr(self, "_prev_started", time.time())
        frac = min(1.0, elapsed / max(0.001, WT_PREVIEW_SECONDS))
        try:
            self._highlight_morph_step(frac)
        except tk.TclError:
            return
        if frac < 1.0:
            self.after(40, lambda: self._tick_morph_marker(token))

    def _cancel_finish_job(self):
        job = getattr(self, "_finish_job", None)
        if job:
            try:
                self.after_cancel(job)
            except (tk.TclError, ValueError) as _e:
                _swallowed(_e, "SynthDialog._cancel_finish_job")
        self._finish_job = None

    def _preview_finished(self, token=None):
        if token is not None and token != getattr(self, "_prev_token", 0):
            return          # belongs to a sweep that was replaced
        self._finish_job = None
        self.prev_playing = False
        self._prev_token = getattr(self, "_prev_token", 0) + 1
        try:
            self._highlight_morph_step(None)
        except tk.TclError as _e:
            _swallowed(_e, "SynthDialog._preview_finished")
        self._update_preview_label()

    # -- apply -------------------------------------------------------------

    def _cancel(self):
        self._stop_preview()        # also cancels the finish timer
        # A pending redraw would fire into a window that no longer exists.
        if getattr(self, "_morph_job", None):
            try:
                self.after_cancel(self._morph_job)
            except (tk.TclError, ValueError) as _e:
                _swallowed(_e, "SynthDialog._cancel")
            self._morph_job = None
        try:
            self.grab_release()
        except tk.TclError as _e:
            _swallowed(_e, "SynthDialog._cancel")
        self.destroy()

    def _apply(self):
        sel = self._active_selection()
        if not sel:
            dark_showwarning("Nothing selected",
                             "Please choose at least one waveform family.",
                             parent=self)
            return
        midi, cycles, up = self._current_pitch()
        self._stop_preview()
        self.btn_apply.config_state("disabled")
        self._status("Building wavetable \u2026", "info")
        self.update_idletasks()
        try:
            pcm, rows, meta = wt_build(self._resolved_selection(), midi, cycles, up)
        except Exception as e:
            self.btn_apply.config_state("normal")
            self._status("")
            dark_showerror("Wavetable", str(e), parent=self)
            return
        self.result = {
            "config": {
                "mode": self.var_mode.get(),
                "simple_set": self.var_set.get() or "Basic",
                "register": self.var_reg.get(),
                "note": self.var_note.get(),
                "up": up,
                "families": list(sel),
                # Only the shapes actually used - a preset should not carry
                # drawings the table does not contain.
                "custom": [self.custom[n] for n in sel if n in self.custom],
                "save_map": bool(self.var_save_map.get()),
            },
            "pcm": pcm,
            "rows": rows,
            "meta": meta,
        }
        try:
            self.grab_release()
        except tk.TclError as _e:
            _swallowed(_e, "SynthDialog._apply")
        self.destroy()


class SampleSlot:
    def __init__(self, parent, pad_num, app):
        self.pad_num = pad_num
        self.app = app
        self.filepath = None
        self.display_name = None
        self.target_rate = tk.IntVar(value=44100)
        self.pitch_cents = tk.IntVar(value=0)
        # Wavetable state. None means this is an ordinary sample pad; a dict
        # means the pad was built by the Synth dialog and its rate/pitch/mono
        # controls are replaced by the init patch and poly switch.
        self.wavetable = None
        self.wt_patch = tk.StringVar(value="Init")
        self.wt_poly = tk.BooleanVar(value=False)

        self.panel = RoundedPanel(parent, title=f"PAD_{pad_num}",
                                   parent_bg=parent.cget("bg"), panel_bg=BG_PANEL,
                                   border=BORDER_LIGHT, radius=14, title_fg=ACCENT_BLUE)
        self.panel.grid(row=(pad_num - 1) // 3, column=(pad_num - 1) % 3,
                         padx=6, pady=6, sticky="nsew")
        self.frame = self.panel.body

        # A row rather than the label alone: the PRM marker needs its own
        # color, and one Label cannot carry two.
        name_row = tk.Frame(self.frame, bg=BG_PANEL)
        name_row.pack(fill="x")
        self.label = tk.Label(name_row, text="No sample loaded", width=26,
                               anchor="w")
        style_label(self.label, bg=BG_PANEL, fg=PAD_NAME_FG, font=ui_font(9))
        self.label.pack(side="left", fill="x", expand=True)
        self.prm_tag = tk.Label(name_row, text="", width=4, anchor="e")
        style_label(self.prm_tag, bg=BG_PANEL, fg=PRM_TAG_FG, font=ui_font(8, "bold"))
        self.prm_tag.pack(side="right", padx=(4, 0))
